<h2 class="nobreak" title="II King Henry VI." id="idb">
<span class="smaller">THE SECOND PART OF</span>
KING HENRY THE SIXTH.</h2></div>

<h3 class="h3main" title="Dramatis Personæ." id="iikh6-dp">
DRAMATIS PERSONÆ†.</h3>

<div class="dpbox">
<div class="right toppada"><small><a href="#idtoc" class="pginternal">toc</a></small></div>
<ul>
<li><span class="smcaps">K<span>ING</span></span> <span class="smcaps">H<span>ENRY</span></span> the Sixth.</li>
<li><span class="smcaps">H<span>UMPHREY</span>,</span> Duke of Gloucester, his uncle.</li>
<li><span class="smcaps">C<span>ARDINAL</span></span> <span class="smcaps">B<span>EAUFORT</span>,</span> Bishop of Winchester, great-uncle to the King.</li>
<li><span class="smcaps">R<span>ICHARD</span></span> <span class="smcaps">P<span>LANTAGENET</span>,</span> Duke of York.</li>
<li><span class="smcaps">E<span>DWARD</span></span> and <span class="smcaps">R<span>ICHARD</span>,</span> his sons.</li>
<li><span class="smcaps">D<span>UKE</span></span> <span class="smmaj">OF</span> <span class="smcaps">S<span>OMERSET</span>.</span></li>
<li><span class="smcaps">D<span>UKE</span></span> <span class="smmaj">OF</span> <span class="smcaps">S<span>UFFOLK</span>.</span></li>
<li><span class="smcaps">D<span>UKE</span></span> <span class="smmaj">OF</span> <span class="smcaps">B<span>UCKINGHAM</span>.</span></li>
<li><span class="smcaps">L<span>ORD</span></span> <span class="smcaps">C<span>LIFFORD</span>.</span></li>
<li>Young <span class="smcaps">C<span>LIFFORD</span>,</span> his son.</li>
<li><span class="smcaps">E<span>ARL</span></span> <span class="smmaj">OF</span> <span class="smcaps">S<span>ALISBURY</span>.</span></li>
<li><span class="smcaps">E<span>ARL</span></span> <span class="smmaj">OF</span> <span class="smcaps">W<span>ARWICK</span>.</span></li>
<li><span class="smcaps">L<span>ORD</span></span> <span class="smcaps">S<span>CALES</span>.</span></li>
<li><span class="smcaps">L<span>ORD</span></span> <span class="smcaps">S<span>AY</span>.</span></li>
<li><span class="smcaps">S<span>IR</span></span> <span class="smcaps">H<span>UMPHREY</span></span> <span class="smcaps">S<span>TAFFORD</span>,</span> and <span class="smcaps">W<span>ILLIAM</span></span> <span class="smcaps">S<span>TAFFORD</span>,</span> his brother.</li>
<li><span class="smcaps">S<span>IR</span></span> <span class="smcaps">J<span>OHN</span></span> <span class="smcaps">S<span>TANLEY</span>.</span></li>
<li><span class="smcaps">V<span>AUX.</span></span></li>
<li><span class="smcaps">M<span>ATTHEW</span></span> <span class="smcaps">G<span>OFFE</span></span>‡.</li>
<li>A Sea-captain, Master, and Master’s-Mate, and
 <span class="smcaps">W<span>ALTER</span></span>
 <span class="smcaps">W<span>HITMORE.</span></span></li>
<li>Two Gentlemen, prisoners with Suffolk.</li>
<li><span class="smcaps">J<span>OHN</span></span> <span class="smcaps">H<span>UME</span></span> and <span class="smcaps">J<span>OHN</span></span> <span class="smcaps">S<span>OUTHWELL</span>,</span> priests.</li>
<li><span class="smcaps">B<span>OLINGBROKE</span>,</span> a conjurer.</li>
<li><span class="smcaps">T<span>HOMAS</span></span> <span class="smcaps">H<span>ORNER</span>,</span> an armourer. <span class="smcaps">P<span>ETER</span>,</span> his man.</li>
<li>Clerk of Chatham. Mayor of Saint Alban’s.</li>
<li><span class="smcaps">S<span>IMPCOX</span>,</span> an impostor.</li>
<li><span class="smcaps">A<span>LEXANDER</span></span> <span class="smcaps">I<span>DEN</span>,</span> a Kentish gentleman.</li>
<li><span class="smcaps">J<span>ACK</span></span> <span class="smcaps">C<span>ADE</span>,</span> a rebel.</li>
<li><span class="smcaps">G<span>EORGE</span></span> <span class="smcaps">B<span>EVIS</span>,</span> <span class="smcaps">J<span>OHN</span></span> <span class="smcaps">H<span>OLLAND</span>,</span> <span class="smcaps">D<span>ICK</span></span> the butcher, <span class="smcaps">S<span>MITH</span></span> the weaver,
 <span class="smcaps">M<span>ICHAEL</span>,</span> &amp;c., followers of Cade.</li>
<li>Two Murderers.</li>
<li><span class="smcaps">M<span>ARGARET</span>,</span> Queen to King Henry.</li>
<li><span class="smcaps">E<span>LEANOR</span>,</span> Duchess of Gloucester.</li>
<li><span class="smcaps">M<span>ARGARET</span></span> <span class="smcaps">J<span>OURDAIN</span>,</span> a witch.</li>
<li>Wife to Simpcox.</li>
</ul></div>

<div class="djust">Lords, Ladies, and Attendants, Petitioners, Aldermen, a Herald, a
Beadle, Sheriff, and Officers, Citizens, ’Prentices, Falconers,
Guards, Soldiers, Messengers, &amp;c.</div>

<div class="toppada">A Spirit.</div>

<div class="toppada"><span class="smcaps">S<span>CENE</span>:</span> <i>England</i>.</div>

<p class="footnote"> <span class="fnline"> </span>
 † <span class="smcaps">D<span>RAMATIS</span></span>
 <span class="smcaps">P<span>ERSONÆ</span>.</span>]
 First given imperfectly by Rowe.<br>
 ‡ <span class="smcaps">M<span>ATTHEW</span></span>
 <span class="smcaps">G<span>OFFE</span>.</span>] Edd. (French conj.).
om. Rowe.</p>

<h3 class="pgbrk" title="ACT I.">
THE SECOND PART OF
<span class="larger">KING HENRY VI.</span>
ACT I.</h3>

<h4 class="h4main"><span class="dnavigate">baa</span>
<span class="smcaps">S<span>CENE</span></span> I. <i>London. The palace</i>.</h4>

<div class="sd-schg"><i>Flourish of trumpets: then hautboys.
Enter,</i> <span class="smcaps">T<span>HE</span></span>
<span class="smcaps">K<span>ING</span>,</span> <span class="smcaps">H<span>UMPHREY</span>,</span> Duke of
Gloucester, <span class="smcaps">S<span>ALISBURY</span>,</span>
<span class="smcaps">W<span>ARWICK</span>,</span> <i>and</i>
<span class="smcaps">C<span>ARDINAL</span></span> <span class="smcaps">B<span>EAUFORT</span>,</span> <i>on the
one side;</i> <span class="smcaps">T<span>HE</span></span>
<span class="smcaps">Q<span>UEEN</span>,</span>
<span class="smcaps">S<span>UFFOLK</span>,</span>
<span class="smcaps">Y<span>ORK</span>,</span> <span class="smcaps">S<span>OMERSET</span>,</span> <i>and</i> <span class="smcaps">B<span>UCKINGHAM</span>,</span> <i>on the other</i>.</div>

<div class="dverse1"><a class="lnum pginternal" href="#lnote-baa001" id="lnum-baa001">♦</a>
 <span class="sd-cn">Suf.</span>
 As by your high imperial majesty</div>
<div class="dverse"><a class="lnum pginternal" href="#lnote-baa002" id="lnum-baa002">♦</a>
 I had in charge at my depart for France,</div>
<div class="dverse">As procurator to your excellence,</div>
<div class="dverse">To marry Princess Margaret for your grace,</div>
<div class="dverse"><span class="lnum">5</span> So, in the famous ancient city Tours,</div>
<div class="dverse">In presence of the Kings of France and Sicil,</div>
<div class="dverse"><a class="lnum pginternal" href="#lnote-baa007" id="lnum-baa007">♦</a>
 The Dukes of Orleans, Calaber, Bretagne and Alençon,</div>
<div class="dverse">Seven earls, twelve barons and twenty reverend bishops,</div>
<div class="dverse">I have perform’d my task and was espoused:</div>
<div class="dverse"><span class="lnum">10</span> And humbly now upon my bended knee,</div>
<div class="dverse">In sight of England and her lordly peers,</div>
<div class="dverse">Deliver up my title in the queen</div>
<div class="dverse"><a class="lnum pginternal" href="#lnote-baa013" id="lnum-baa013">♦</a>
 To your most gracious hands, that are the substance</div>
<div class="dverse">Of that great shadow I did represent;</div>
<div class="dverse"><span class="lnum">15</span> The happiest gift that ever marquess gave,</div>
<div class="dverse">The fairest queen that ever king received.</div>

<div class="dverse1"><span class="sd-cn">King.</span>
 Suffolk, arise. Welcome, Queen Margaret:</div>
<div class="dverse">I can express no kinder sign of love</div>
<div class="dverse"><a class="lnum pginternal" href="#lnote-baa019" id="lnum-baa019">♦</a>
 Than this kind kiss. O Lord, that lends me life,</div>
<div class="dverse"><span class="lnum">20</span>
 Lend me a heart replete with thankfulness!</div>
<div class="dverse">For thou hast given me in this beauteous face</div>
<div class="dverse">A world of earthly blessings to my soul,</div>
<div class="dverse">If sympathy of love unite our thoughts.</div>

<div class="dverse1"><span class="sd-cn">Queen.</span>
 Great King of England and my gracious lord,</div>
<div class="dverse"><span class="lnum">25</span>
 The mutual conference that my mind hath had,</div>
<div class="dverse">By day, by night, waking and in my dreams,</div>
<div class="dverse">In courtly company or at my beads,</div>
<div class="dverse"><a class="lnum pginternal" href="#lnote-baa028" id="lnum-baa028">♦</a>
 With you, mine alder-liefest sovereign,</div>
<div class="dverse">Makes me the bolder to salute my king</div>
<div class="dverse"><span class="lnum">30</span>
 With ruder terms, such as my wit affords</div>
<div class="dverse">And over-joy of heart doth minister.</div>

<div class="dverse1"><span class="sd-cn">King.</span>
 Her sight did ravish; but her grace in speech,</div>
<div class="dverse">Her words y-clad with wisdom’s majesty,</div>
<div class="dverse"><a class="lnum pginternal" href="#lnote-baa034" id="lnum-baa034">♦</a>
 Makes me from wondering fall to weeping joys;</div>
<div class="dverse"><span class="lnum">35</span> Such is the fulness of my heart’s content.</div>
<div class="dverse">Lords, with one cheerful voice welcome my love.</div>

<div class="dverse1"><a class="lnum pginternal" href="#lnote-baa037" id="lnum-baa037">♦</a>
 <span class="sd-cn">All</span>
 <span class="sd-inline">[<i>kneeling</i>].</span>
 Long live Queen Margaret, England’s happiness!</div>

<div class="dverse1"><span class="sd-cn">Queen.</span>
 We thank you all.
 <span class="sd-verseend">[<i>Flourish.</i></span></div>

<div class="dverse1"><span class="sd-cn">Suff.</span>
 My lord protector, so it please your grace,</div>
<div class="dverse"><span class="lnum">40</span> Here are the articles of contracted peace</div>
<div class="dverse">Between our sovereign and the French king Charles,</div>
<div class="dverse">For eighteen months concluded by consent.</div>

<div class="dprose1 lhclose"><span class="sd-cn">Glou.</span>
 <span class="sd-inline">[<i>Reads</i>]</span>
 <span class="smprint">‘Imprimis, it is agreed between the French king Charles, and William de la Pole, Marquess of Suffolk, ambassador for <span class="lnum">45</span>
 Henry King of England, that the said Henry shall espouse the Lady Margaret, daughter unto Reignier King of Naples, Sicilia and <a class="lnum pginternal" href="#lnote-baa047" id="lnum-baa047">♦</a>
 Jerusalem, and crown her Oueen of England ere the thirtieth of May next <a class="lnum pginternal" href="#lnote-baa048" id="lnum-baa048">♦</a>
 ensuing. Item, that the duchy of Anjou and the county of Maine <a class="lnum pginternal" href="#lnote-baa049" id="lnum-baa049">♦</a>
 shall be released and delivered to the king her father’—</span>
 <span class="sd-proseend">[<i>Lets the paper fall.</i></span>
</div>

<div class="dverse1"><span class="sd-cn">King.</span>
 Uncle, how now!</div>

<div class="dverse1"><span class="lnum">50</span>
 <span class="sd-cn">Glou.</span>
 <span class="i09"> </span> Pardon me, gracious lord;</div>
<div class="dverse"><a class="lnum pginternal" href="#lnote-baa051" id="lnum-baa051">♦</a>
 Some sudden qualm hath struck me at the heart</div>
<div class="dverse">And dimm’d mine eyes, that I can read no further.</div>

<div class="dverse1"><span class="sd-cn">King.</span>
 Uncle of Winchester, I pray, read on.</div>

<div class="dprose1 lhclose"><a class="lnum pginternal" href="#lnote-baa054" id="lnum-baa054">♦</a>
 <span class="sd-cn">Car.</span>
 <span class="sd-inline">[<i>Reads</i>]</span>
 <span class="smprint">‘Item, It is further agreed between them, that the
 <a class="lnum pginternal" href="#lnote-baa055" id="lnum-baa055">55</a>
 duchies of Anjou and Maine shall be released and delivered over to the king
 her father, and she sent over of the King of England’s own
 <a class="lnum pginternal" href="#lnote-baa057" id="lnum-baa057">♦</a>
 proper cost and charges, without having any dowry.’</span>
</div>

<div class="dverse1"><a class="lnum pginternal" href="#lnote-baa058" id="lnum-baa058">♦</a>
 <span class="sd-cn">King.</span>
  They please us well. Lord marquess, kneel down:</div>
<div class="dverse">We here create thee the first duke of Suffolk,</div>
<div class="dverse"><a class="lnum pginternal" href="#lnote-baa060" id="lnum-baa060">60</a>
 And gird thee with the sword. Cousin of York,</div>
<div class="dverse">We here discharge your grace from being regent</div>
<div class="dverse"><a class="lnum pginternal" href="#lnote-baa062" id="lnum-baa062">♦</a>
 I’ the parts of France, till term of eighteen months</div>
<div class="dverse">Be full expired. Thanks, uncle Winchester,</div>
<div class="dverse"><a class="lnum pginternal" href="#lnote-baa064" id="lnum-baa064">♦</a>
 Gloucester, York, Buckingham, Somerset,</div>
<div class="dverse"><span class="lnum">65</span> Salisbury, and Warwick;</div>
<div class="dverse"><a class="lnum pginternal" href="#lnote-baa066" id="lnum-baa066">♦</a>
 We thank you all for this great favour done,</div>
<div class="dverse">In entertainment to my princely queen.</div>
<div class="dverse">Come, let us in, and with all speed provide</div>
<div class="dverse"><a class="lnum pginternal" href="#lnote-baa069" id="lnum-baa069">♦</a>
 To see her coronation be perform’d.
 <span class="sd-verseend">[<i>Exeunt King, Queen, and Suffolk.</i></span></div>

<div class="dverse1"><a class="lnum pginternal" href="#lnote-baa070" id="lnum-baa070">70</a>
 <span class="sd-cn">Glou.</span>
  Brave peers of England, pillars of the state,</div>
<div class="dverse">To you Duke Humphrey must unload his grief,</div>
<div class="dverse">Your grief, the common grief of all the land.</div>
<div class="dverse">What! did my brother Henry spend his youth,</div>
<div class="dverse">His valour, coin and people, in the wars?</div>
<div class="dverse"><span class="lnum">75</span> Did he so often lodge in open field,</div>
<div class="dverse">In winter’s cold and summer’s parching heat,</div>
<div class="dverse">To conquer France, his true inheritance?</div>
<div class="dverse">And did my brother Bedford toil his wits,</div>
<div class="dverse">To keep by policy what Henry got?</div>
<div class="dverse"><span class="lnum">80</span> Have you yourselves, Somerset, Buckingham,</div>
<div class="dverse">Brave York, Salisbury, and victorious Warwick,</div>
<div class="dverse">Received deep scars in France and Normandy?</div>
<div class="dverse"><a class="lnum pginternal" href="#lnote-baa083" id="lnum-baa083">♦</a>
 Or hath mine uncle Beaufort and myself,</div>
<div class="dverse">With all the learned council of the realm,</div>
<div class="dverse"><span class="lnum">85</span> Studied so long, sat in the council-house</div>
<div class="dverse">Early and late, debating to and fro</div>
<div class="dverse">How France and Frenchmen might be kept in awe,</div>
<div class="dverse"><a class="lnum pginternal" href="#lnote-baa088" id="lnum-baa088">♦</a>
 And had his highness in his infancy</div>
<div class="dverse">Crowned in Paris in despite of foes?</div>
<div class="dverse"><span class="lnum">90</span> And shall these labours and these honours die?</div>
<div class="dverse">Shall Henry’s conquest, Bedford’s vigilance,</div>
<div class="dverse">Your deeds of war and all our counsel die?</div>
<div class="dverse">O peers of England, shameful is this league!</div>
<div class="dverse">Fatal this marriage, cancelling your fame,</div>
<div class="dverse"><span class="lnum">95</span> Blotting your names from books of memory,</div>
<div class="dverse">Razing the characters of your renown,</div>
<div class="dverse">Defacing monuments of conquer’d France,</div>
<div class="dverse">Undoing all, as all had never been!</div>

<div class="dverse1"><span class="sd-cn">Car.</span>
 Nephew, what means this passionate discourse,</div>
<div class="dverse"><a class="lnum pginternal" href="#lnote-baa100" id="lnum-baa100">100</a>
 This peroration with such circumstance?</div>
<div class="dverse">For France, ’tis ours; and we will keep it still.</div>

<div class="dverse1"><span class="sd-cn">Glou.</span>
 Ay, uncle, we will keep it, if we can;</div>
<div class="dverse">But now it is impossible we should:</div>
<div class="dverse"><a class="lnum pginternal" href="#lnote-baa104" id="lnum-baa104">♦</a>
 Suffolk, the new-made duke that rules the roast,</div>
<div class="dverse"><a class="lnum pginternal" href="#lnote-baa105" id="lnum-baa105">105</a>
 Hath given the duchy of Anjou and Maine</div>
<div class="dverse">Unto the poor King Reignier, whose large style</div>
<div class="dverse">Agrees not with the leanness of his purse.</div>

<div class="dverse1"><span class="sd-cn">Sal.</span>
 Now, by the death of Him that died for all,</div>
<div class="dverse">These counties were the keys of Normandy.</div>
<div class="dverse"><span class="lnum">110</span> But wherefore weeps Warwick, my valiant son?</div>

<div class="dverse1"><span class="sd-cn">War.</span>
 For grief that they are past recovery:</div>
<div class="dverse">For, were there hope to conquer them again,</div>
<div class="dverse">My sword should shed hot blood, mine eyes no tears.</div>
<div class="dverse">Anjou and Maine! myself did win them both;</div>
<div class="dverse"><span class="lnum">115</span> Those provinces these arms of mine did conquer:</div>
<div class="dverse"><a class="lnum pginternal" href="#lnote-baa116" id="lnum-baa116">♦</a>
 And are the cities, that I got with wounds,</div>
<div class="dverse">Deliver’d up again with peaceful words?</div>
<div class="dverse"><a class="lnum pginternal" href="#lnote-baa118" id="lnum-baa118">♦</a>
 Mort Dieu!</div>

<div class="dverse1"><a class="lnum pginternal" href="#lnote-baa119" id="lnum-baa119">♦</a>
 <span class="sd-cn">York.</span>
  For Suffolk’s duke, may he be suffocate,</div>
<div class="dverse"><span class="lnum">120</span> That dims the honour of this warlike isle!</div>
<div class="dverse">France should have torn and rent my very heart,</div>
<div class="dverse">Before I would have yielded to this league.</div>
<div class="dverse">I never read but England’s kings have had</div>
<div class="dverse">Large sums of gold and dowries with their wives;</div>
<div class="dverse"><span class="lnum">125</span> And our King Henry gives away his own,</div>
<div class="dverse">To match with her that brings no vantages.</div>

<div class="dverse1"><span class="sd-cn">Glou.</span>
 A proper jest, and never heard before,</div>
<div class="dverse">That Suffolk should demand a whole fifteenth</div>
<div class="dverse">For costs and charges in transporting her!</div>
<div class="dverse"><a class="lnum pginternal" href="#lnote-baa130" id="lnum-baa130">130</a>
 She should have stayed in France and starved in France,</div>
<div class="dverse">Before—</div>

<div class="dverse1"><span class="sd-cn">Car.</span>
 My lord of Gloucester, now ye grow too hot:</div>
<div class="dverse">It was the pleasure of my lord the king.</div>

<div class="dverse1"><span class="sd-cn">Glou.</span>
 My lord of Winchester, I know your mind;</div>
<div class="dverse"><span class="lnum">135</span> ’Tis not my speeches that you do mislike,</div>
<div class="dverse">But ’tis my presence that doth trouble ye.</div>
<div class="dverse">Rancour will out: proud prelate, in thy face</div>
<div class="dverse">I see thy fury: if I longer stay.</div>
<div class="dverse">We shall begin our ancient bickerings.</div>
<div class="dverse"><span class="lnum">140</span> Lordings, farewell; and say, when I am gone,</div>
<div class="dverse">I prophesied France will be lost ere long. <span class="sd-verseend">[<i>Exit.</i></span></div>

<div class="dverse1"><span class="sd-cn">Car.</span>
 So, there goes our protector in a rage.</div>
<div class="dverse">Tis known to you he is mine enemy,</div>
<div class="dverse">Nay, more, an enemy unto you all,</div>
<div class="dverse"><span class="lnum">145</span> And no great friend, I fear me, to the king.</div>
<div class="dverse">Consider, lords, he is the next of blood,</div>
<div class="dverse">And heir apparent to the English crown:</div>
<div class="dverse">Had Henry got an empire by his marriage,</div>
<div class="dverse"><a class="lnum pginternal" href="#lnote-baa149" id="lnum-baa149">♦</a>
 And all the wealthy kingdoms of the west,</div>
<div class="dverse"><span class="lnum">150</span> There’s reason he should be displeased at it.</div>
<div class="dverse">Look to it, lords; let not his smoothing words</div>
<div class="dverse">Bewitch your hearts; be wise and circumspect.</div>
<div class="dverse">What though the common people favour him,</div>
<div class="dverse">Calling him ‘Humphrey, the good Duke of Gloucester,’</div>
<div class="dverse"><span class="lnum">155</span> Clapping their hands, and crying with loud voice,</div>
<div class="dverse">‘Jesu maintain your royal excellence!’</div>
<div class="dverse">With ‘God preserve the good Duke Humphrey!’</div>
<div class="dverse">I fear me, lords, for all this flattering gloss,</div>
<div class="dverse">He will be found a dangerous protector.</div>

<div class="dverse1"><span class="lnum">160</span>
 <span class="sd-cn">Buck.</span>
  Why should he, then, protect our sovereign,</div>
<div class="dverse">He being of age to govern of himself?</div>
<div class="dverse">Cousin of Somerset, join you with me,</div>
<div class="dverse"><a class="lnum pginternal" href="#lnote-baa163" id="lnum-baa163">♦</a>
 And all together, with the Duke of Suffolk,</div>
<div class="dverse"><a class="lnum pginternal" href="#lnote-baa164" id="lnum-baa164">♦</a>
 We’ll quickly hoise Duke Humphrey from his seat.</div>

<div class="dverse1"><span class="lnum">165</span>
 <span class="sd-cn">Car.</span>
  This weighty business will not brook delay;</div>
<div class="dverse">I’ll to the Duke of Suffolk presently. <span class="sd-verseend">[<i>Exit.</i></span></div>

<div class="dverse1"><span class="sd-cn">Som.</span>
 Cousin of Buckingham, though Humphrey’s pride</div>
<div class="dverse">And greatness of his place be grief to us,</div>
<div class="dverse">Yet let us watch the haughty cardinal:</div>
<div class="dverse"><span class="lnum">170</span> His insolence is more intolerable</div>
<div class="dverse">Than all the princes in the land beside:</div>
<div class="dverse">If Gloucester be displaced, he’ll be protector.</div>

<div class="dverse1"><a class="lnum pginternal" href="#lnote-baa173" id="lnum-baa173">♦</a>
 <span class="sd-cn">Buck.</span>
  Or thou or I, Somerset, will be protector,</div>
<div class="dverse"><a class="lnum pginternal" href="#lnote-baa174" id="lnum-baa174">♦</a>
 Despite Duke Humphrey or the cardinal.
 <span class="sd-verseend">[<i>Exeunt Buckingham and Somerset.</i></span></div>

<div class="dverse1"><a class="lnum pginternal" href="#lnote-baa175" id="lnum-baa175">175</a>
 <span class="sd-cn">Sal.</span>
  Pride went before, ambition follows him.</div>
<div class="dverse">While these do labour for their own preferment,</div>
<div class="dverse">Behoves it us to labour for the realm.</div>
<div class="dverse">I never saw but Humphrey Duke of Gloucester</div>
<div class="dverse">Did bear him like a noble gentleman.</div>
<div class="dverse"><span class="lnum">180</span> Oft have I seen the haughty cardinal,</div>
<div class="dverse">More like a soldier than a man o’ the church,</div>
<div class="dverse">As stout and proud as he were lord of all,</div>
<div class="dverse">Swear like a ruffian and demean himself</div>
<div class="dverse">Unlike the ruler of a commonweal.</div>
<div class="dverse"><span class="lnum">185</span> Warwick, my son, the comfort of my age,</div>
<div class="dverse">Thy deeds, thy plainness and thy housekeeping,</div>
<div class="dverse"><a class="lnum pginternal" href="#lnote-baa187" id="lnum-baa187">♦</a>
 Hath won the greatest favour of the commons,</div>
<div class="dverse">Excepting none but good Duke Humphrey:</div>
<div class="dverse"><a class="lnum pginternal" href="#lnote-baa189" id="lnum-baa189">♦</a>
 And, brother York, thy acts in Ireland,</div>
<div class="dverse"><span class="lnum">190</span> In bringing them to civil discipline,</div>
<div class="dverse">Thy late exploits done in the heart of France,</div>
<div class="dverse">When thou wert regent for our sovereign,</div>
<div class="dverse">Have made thee fear’d and honour’d of the people:</div>
<div class="dverse">Join we together, for the public good,</div>
<div class="dverse"><span class="lnum">195</span> In what we can, to bridle and suppress</div>
<div class="dverse">The pride of Suffolk and the cardinal,</div>
<div class="dverse">With Somerset’s and Buckingham’s ambition;</div>
<div class="dverse">And, as we may, cherish Duke Humphrey’s deeds,</div>
<div class="dverse"><a class="lnum pginternal" href="#lnote-baa199" id="lnum-baa199">♦</a>
 While they do tend the profit of the land.</div>

<div class="dverse1"><span class="lnum">200</span>
 <span class="sd-cn">War.</span>
  So God help Warwick, as he loves the land,</div>
<div class="dverse"><a class="lnum pginternal" href="#lnote-baa201" id="lnum-baa201">♦</a>
 And common profit of his country!</div>

<div class="dverse1"><a class="lnum pginternal" href="#lnote-baa202" id="lnum-baa202">♦</a>
 <span class="sd-cn">York.</span>
 <span class="sd-inline">[<i>Aside</i>]</span>
  And so says York, for he hath greatest  cause.</div>

<div class="dverse1"><a class="lnum pginternal" href="#lnote-baa203" id="lnum-baa203">♦</a>
 <span class="sd-cn">Sal.</span>
  Then let’s make haste away, and look unto the main.</div>

<div class="dverse1"><a class="lnum pginternal" href="#lnote-baa204" id="lnum-baa204">♦</a>
 <span class="sd-cn">War.</span>
  Unto the main! O father, Maine is lost;</div>
<div class="dverse"><a class="lnum pginternal" href="#lnote-baa205" id="lnum-baa205">205</a>
 That Maine which by main force Warwick did win,</div>
<div class="dverse">And would have kept so long as breath did last!</div>
<div class="dverse">Main chance, father, you meant; but I meant Maine,</div>
<div class="dverse"><a class="lnum pginternal" href="#lnote-baa208" id="lnum-baa208">♦</a>
 Which I will win from France, or else be slain.
<span class="sd-verseend">[<i>Exeunt Warwick and Salisbury.</i></span></div>

<div class="dverse1"><a class="lnum pginternal" href="#lnote-baa209" id="lnum-baa209">♦</a>
 <span class="sd-cn">York.</span>
  Anjou and Maine are given to the French;</div>
<div class="dverse"><span class="lnum">210</span> Paris is lost; the state of Normandy</div>
<div class="dverse">Stands on a tickle point, now they are gone:</div>
<div class="dverse">Suffolk concluded on the articles,</div>
<div class="dverse">The peers agreed, and Henry was well pleased</div>
<div class="dverse">To change two dukedoms for a duke’s fair daughter.</div>
<div class="dverse"><span class="lnum">215</span> I cannot blame them all: what is’t to them?</div>
<div class="dverse"><a class="lnum pginternal" href="#lnote-baa216" id="lnum-baa216">♦</a>
 ’Tis thine they give away, and not their own.</div>
<div class="dverse"><a class="lnum pginternal" href="#lnote-baa217" id="lnum-baa217">♦</a>
 Pirates may make cheap pennyworths of their pillage</div>
<div class="dverse">And purchase friends and give to courtezans,</div>
<div class="dverse">Still revelling like lords till all be gone;</div>
<div class="dverse"><span class="lnum">220</span> While as the silly owner of the goods</div>
<div class="dverse"><a class="lnum pginternal" href="#lnote-baa221" id="lnum-baa221">♦</a>
 Weeps over them and wrings his hapless hands</div>
<div class="dverse">And shakes his head and trembling stands aloof.</div>
<div class="dverse">While all is shared and all is borne away,</div>
<div class="dverse"><a class="lnum pginternal" href="#lnote-baa224" id="lnum-baa224">♦</a>
 Ready to starve and dare not touch his own:</div>
<div class="dverse"><span class="lnum">225</span> So York must sit and fret and bite his tongue,</div>
<div class="dverse">While his own lands are bargain’d for and sold.</div>
<div class="dverse">Methinks the realms of England, France and Ireland</div>
<div class="dverse">Bear that proportion to my flesh and blood</div>
<div class="dverse">As did the fatal brand Althæa burn’d</div>
<div class="dverse"><span class="lnum">230</span> Unto the prince’s heart of Calydon.</div>
<div class="dverse">Anjou and Maine both given unto the French!</div>
<div class="dverse">Cold news for me, for I had hope of France,</div>
<div class="dverse"><a class="lnum pginternal" href="#lnote-baa233" id="lnum-baa233">♦</a>
 Even as I have of fertile England’s soil.</div>
<div class="dverse">A day will come when York shall claim his own;</div>
<div class="dverse"><span class="lnum">235</span>
 And therefore I will take the Nevils’ parts</div>
<div class="dverse">And make a show of love to proud Duke Humphrey,</div>
<div class="dverse">And, when I spy advantage, claim the crown,</div>
<div class="dverse">For that’s the golden mark I seek to hit:</div>
<div class="dverse">Nor shall proud Lancaster usurp my right,</div>
<div class="dverse"><span class="lnum">240</span>
 Nor hold the sceptre in his childish fist,</div>
<div class="dverse">Nor wear the diadem upon his head,</div>
<div class="dverse"><a class="lnum pginternal" href="#lnote-baa242" id="lnum-baa242">♦</a>
 Whose church-like humours fits not for a crown.</div>
<div class="dverse">Then, York, be still awhile, till time do serve:</div>
<div class="dverse">Watch thou and wake when others be asleep,</div>
<div class="dverse"><span class="lnum">245</span>
 To pry into the secrets of the state;</div>
<div class="dverse"><a class="lnum pginternal" href="#lnote-baa246" id="lnum-baa246">♦</a>
 Till Henry, surfeiting in joys of love,</div>
<div class="dverse"><a class="lnum pginternal" href="#lnote-baa247" id="lnum-baa247">♦</a>
 With his new bride and England’s dear-bought queen.</div>
<div class="dverse">And Humphrey with the peers be fall’n at jars:</div>
<div class="dverse">Then will I raise aloft the milk-white rose,</div>
<div class="dverse"><span class="lnum">250</span>
 With whose sweet smell the air shall be perfumed;</div>
<div class="dverse"><a class="lnum pginternal" href="#lnote-baa251" id="lnum-baa251">♦</a>
 And in my standard bear the arms of York,</div>
<div class="dverse">To grapple with the house of Lancaster;</div>
<div class="dverse">And, force perforce, I’ll make him yield the crown,</div>
<div class="dverse">Whose bookish rule hath pull’d fair England down.
 <span class="sd-verseend">[<i>Exit.</i></span></div>

<div class="section">
<h4 class="h4main"><span class="dnavigate">bab</span>
<span class="smcaps">S<span>CENE</span></span> II. <i>The</i>
<span class="smcaps">D<span>UKE</span></span> <span class="smmaj">OF</span>
<span class="smcaps">G<span>LOUCESTER’S</span></span> <i>house</i>.</h4>

<div class="sd-schg"><i>Enter</i>
<span class="smcaps">D<span>UKE</span></span>
 <span class="smcaps">H<span>UMPHREY</span></span> <i>and his wife</i>
 <span class="smcaps">E<span>LEANOR</span>.</span></div></div>

<div class="dverse1"><a class="lnum pginternal" href="#lnote-bab001" id="lnum-bab001">♦</a>
 <span class="sd-cn">Duch.</span>
  Why droops my lord, like over-ripen’d corn,</div>
<div class="dverse"><a class="lnum pginternal" href="#lnote-bab002" id="lnum-bab002">♦</a>
 Hanging the head at Ceres’ plenteous load?</div>
<div class="dverse">Why doth the great Duke Humphrey knit his brows,</div>
<div class="dverse">As frowning at the favours of the world?</div>
<div class="dverse"><span class="lnum">5</span>
 Why are thine eyes fix’d to the sullen earth,</div>
<div class="dverse">Gazing on that which seems to dim thy sight?</div>
<div class="dverse">What seest thou there? King Henry’s diadem,</div>
<div class="dverse">Enchased with all the honours of the world?</div>
<div class="dverse">If so, gaze on, and grovel on thy face,</div>
<div class="dverse"><span class="lnum">10</span>
 Until thy head be circled with the same.</div>
<div class="dverse">Put forth thy hand, reach at the glorious gold.</div>
<div class="dverse">What, is’t too short? I’ll lengthen it with mine;</div>
<div class="dverse">And, having both together heaved it up,</div>
<div class="dverse">We’ll both together lift our heads to heaven,</div>
<div class="dverse"><span class="lnum">15</span> And never more abase our sight so low</div>
<div class="dverse">As to vouchsafe one glance unto the ground.</div>

<div class="dverse1"><span class="sd-cn">Glou.</span>
 O Nell, sweet Nell, if thou dost love thy lord,</div>
<div class="dverse">Banish the canker of ambitious thoughts.</div>
<div class="dverse">And may that thought, when I imagine ill</div>
<div class="dverse"><span class="lnum">20</span> Against my king and nephew, virtuous Henry,</div>
<div class="dverse">Be my last breathing in this mortal world!</div>
<div class="dverse"><a class="lnum pginternal" href="#lnote-bab022" id="lnum-bab022">♦</a>
 My troublous dream this night doth make me sad.</div>

<div class="dverse1"><span class="sd-cn">Duch.</span>
 What dream’d my lord? tell me, and I’ll requite it</div>
<div class="dverse">With sweet rehearsal of my morning’s dream.</div>

<div class="dverse1"><a class="lnum pginternal" href="#lnote-bab025" id="lnum-bab025">25</a>
 <span class="sd-cn">Glou.</span>
  Methought this staff, mine office-badge in court,</div>
<div class="dverse">Was broke in twain; by whom I have forgot,</div>
<div class="dverse">But, as I think, it was by the cardinal;</div>
<div class="dverse">And on the pieces of the broken wand</div>
<div class="dverse">Were placed the heads of Edmund Duke of Somerset,</div>
<div class="dverse"><span class="lnum">30</span> And William de la Pole, first duke of Suffolk.</div>
<div class="dverse"><a class="lnum pginternal" href="#lnote-bab031" id="lnum-bab031">♦</a>
 This was my dream: what it doth bode, God knows.</div>

<div class="dverse1"><span class="sd-cn">Duch.</span>
 Tut, this was nothing but an argument</div>
<div class="dverse">That he that breaks a stick of Gloucester’s grove</div>
<div class="dverse">Shall lose his head for his presumption.</div>
<div class="dverse"><span class="lnum">35</span> But list to me, my Humphrey, my sweet duke:</div>
<div class="dverse">Methought I sat in seat of majesty</div>
<div class="dverse">In the cathedral church of Westminster,</div>
<div class="dverse"><a class="lnum pginternal" href="#lnote-bab038" id="lnum-bab038">♦</a>
 And in that chair where kings and queens are crown’d;</div>
<div class="dverse"><a class="lnum pginternal" href="#lnote-bab039" id="lnum-bab039">♦</a>
 Where Henry and dame Margaret kneel’d to me</div>
<div class="dverse"><span class="lnum">40</span> And on my head did set the diadem.</div>

<div class="dverse1"><span class="sd-cn">Glou.</span>
 Nay, Eleanor, then must I chide outright:</div>
<div class="dverse"><a class="lnum pginternal" href="#lnote-bab042" id="lnum-bab042">♦</a>
 Presumptuous dame, ill-nurtured Eleanor,</div>
<div class="dverse">Art thou not second woman in the realm,</div>
<div class="dverse">And the protector’s wife, beloved of him?</div>
<div class="dverse"><span class="lnum">45</span> Hast thou not worldly pleasure at command,</div>
<div class="dverse">Above the reach or compass of thy thought?</div>
<div class="dverse">And wilt thou still be hammering treachery,</div>
<div class="dverse">To tumble down thy husband and thyself</div>
<div class="dverse">From top of honour to disgrace’s feet?</div>
<div class="dverse"><span class="lnum">50</span> Away from me, and let me hear no more!</div>

<div class="dverse1"><span class="sd-cn">Duch.</span>
 What, what, my lord! are you so choleric</div>
<div class="dverse">With Eleanor, for telling but her dream?</div>
<div class="dverse">Next time I’ll keep my dreams unto myself,</div>
<div class="dverse">And not be check’d.</div>

<div class="dverse1"><span class="lnum">55</span>
 <span class="sd-cn">Glou.</span>
  Nay, be not angry; I am pleased again.</div>

<div class="sd-entry"><i>Enter</i> Messenger.</div>

<div class="dverse1"><span class="sd-cn">Mess.</span>
 My lord protector, ’tis his highness’ pleasure</div>
<div class="dverse"><a class="lnum pginternal" href="#lnote-bab057" id="lnum-bab057">♦</a>
 You do prepare to ride unto Saint Alban’s,</div>
<div class="dverse"><a class="lnum pginternal" href="#lnote-bab058" id="lnum-bab058">♦</a>
 Where as the king and queen do mean to hawk.</div>

<div class="dverse1"><a class="lnum pginternal" href="#lnote-bab059" id="lnum-bab059">♦</a>
 <span class="sd-cn">Glou.</span>
  I go. Come, Nell, thou wilt ride with us?</div>

<div class="dverse1"><a class="lnum pginternal" href="#lnote-bab060" id="lnum-bab060">60</a>
 <span class="sd-cn">Duch.</span>
 Yes, my good lord, I’ll follow presently.
<span class="sd-verseend">[<i>Exeunt Gloucester and Messenger.</i></span></div>
<div class="dverse">Follow I must; I cannot go before,</div>
<div class="dverse">While Gloucester bears this base and humble mind.</div>
<div class="dverse">Were I a man, a duke, and next of blood,</div>
<div class="dverse">I would remove these tedious stumbling-blocks</div>
<div class="dverse"><span class="lnum">65</span> And smooth my way upon their headless necks;</div>
<div class="dverse">And, being a woman, I will not be slack</div>
<div class="dverse">To play my part in Fortune’s pageant.</div>
<div class="dverse"><a class="lnum pginternal" href="#lnote-bab068" id="lnum-bab068">♦</a>
 Where are you there? Sir John! nay, fear not, man,</div>
<div class="dverse"><a class="lnum pginternal" href="#lnote-bab069" id="lnum-bab069">♦</a>
 We are alone; here’s none but thee and I.</div>

<div class="sd-entry"><i>Enter</i> <span class="smcaps">H<span>UME</span>.</span></div>

<div class="dverse1"><span class="lnum">70</span>
 <span class="sd-cn">Hume.</span>
  Jesus preserve your royal majesty!</div>

<div class="dverse1"><a class="lnum pginternal" href="#lnote-bab071" id="lnum-bab071">♦</a>
 <span class="sd-cn">Duch.</span>
  What say’st thou? majesty! I am but grace.</div>

<div class="dverse1"><span class="sd-cn">Hume.</span>
 But, by the grace of God, and Hume’s advice,</div>
<div class="dverse">Your grace’s title shall be multiplied.</div>

<div class="dverse1"><span class="sd-cn">Duch.</span>
 What say’st thou, man? hast thou as yet conferr’d</div>
<div class="dverse"><a class="lnum pginternal" href="#lnote-bab075" id="lnum-bab075">75</a>
 With Margery Jourdain, the cunning witch,</div>
<div class="dverse">With Roger Bolingbroke, the conjurer?</div>
<div class="dverse">And will they undertake to do me good?</div>

<div class="dverse1"><span class="sd-cn">Hume.</span>
 This they have promised, to show your highness</div>
<div class="dverse">A spirit raised from depth of under-ground,</div>
<div class="dverse"><span class="lnum">80</span> That shall make answer to such questions</div>
<div class="dverse">As by your grace shall be propounded him.</div>

<div class="dverse1"><span class="sd-cn">Duch.</span>
 It is enough; I’ll think upon the questions:</div>
<div class="dverse">When from Saint Alban’s we do make return,</div>
<div class="dverse">We’ll see these things effected to the full.</div>
<div class="dverse"><span class="lnum">85</span> Here, Hume, take this reward; make merry, man,</div>
<div class="dverse">With thy confederates in this weighty cause. <span class="sd-verseend">[<i>Exit.</i></span></div>

<div class="dverse1"><span class="sd-cn">Hume.</span>
 Hume must make merry with the duchess’ gold;</div>
<div class="dverse">Marry, and shall. But, how now, Sir John Hume!</div>
<div class="dverse"><a class="lnum pginternal" href="#lnote-bab089" id="lnum-bab089">♦</a>
 Seal up your lips, and give no words but mum:</div>
<div class="dverse"><span class="lnum">90</span> The business asketh silent secrecy.</div>
<div class="dverse">Dame Eleanor gives gold to bring the witch:</div>
<div class="dverse">Gold cannot come amiss, were she a devil.</div>
<div class="dverse">Yet have I gold flies from another coast;</div>
<div class="dverse">I dare not say, from the rich cardinal</div>
<div class="dverse"><span class="lnum">95</span> And from the great and new-made Duke of Suffolk,</div>
<div class="dverse">Yet I do find it so; for, to be plain,</div>
<div class="dverse"><a class="lnum pginternal" href="#lnote-bab097" id="lnum-bab097">♦</a>
 They, knowing Dame Eleanor’s aspiring humour,</div>
<div class="dverse">Have hired me to undermine the duchess</div>
<div class="dverse">And buz these conjurations in her brain.</div>
<div class="dverse"><span class="lnum">100</span> They say ‘A crafty knave does need no broker;’</div>
<div class="dverse"><a class="lnum pginternal" href="#lnote-bab101" id="lnum-bab101">♦</a>
 Yet am I Suffolk and the cardinal’s broker.</div>
<div class="dverse">Hume, if you take not heed, you shall go near</div>
<div class="dverse">To call them both a pair of crafty knaves.</div>
<div class="dverse">Well, so it stands; and thus, I fear, at last</div>
<div class="dverse"><a class="lnum pginternal" href="#lnote-bab105" id="lnum-bab105">105</a>
 Hume’s knavery will be the duchess’ wreck,</div>
<div class="dverse">And her attainture will be Humphrey’s fall:</div>
<div class="dverse">Sort how it will, I shall have gold for all. <span class="sd-verseend">[<i>Exit.</i></span></div>

<div class="section">
<h4 class="h4main"><span class="dnavigate">bac</span>
<span class="smcaps">S<span>CENE</span></span> III. <i>The palace</i>.</h4>

<div class="sd-schg"><i>Enter three or four Petitioners,</i> <span class="smcaps">P<span>ETER</span>,</span>
<i>the Armourer’s man, being one</i>.</div></div>

<div class="dprose1"><a class="lnum pginternal" href="#lnote-bac001" id="lnum-bac001">♦</a>
 <span class="sd-cn">First Petit.</span>
My masters, let’s stand close: my lord protector will come this way by and by, and then we may <a class="lnum pginternal" href="#lnote-bac003" id="lnum-bac003">♦</a>
deliver our supplications in the quill.</div>

<div class="dprose1"><span class="sd-cn">Sec. Petit.</span>
 Marry, the Lord protect him, for he’s a <span class="lnum">5</span> good man! Jesu bless him!</div>

<div class="sd-entry"><i>Enter</i> <span class="smcaps">S<span>UFFOLK</span></span> <i>and</i> <span class="smcaps">Q<span>UEEN</span>.</span></div>

<div class="dprose1"><a class="lnum pginternal" href="#lnote-bac006" id="lnum-bac006">♦</a>
<span class="sd-cn">Peter.</span>
Here a’ comes, methinks, and the queen with him. I’ll be the first, sure.</div>

<div class="dprose1"><span class="sd-cn">Sec. Petit.</span>
 Come back, fool; this is the Duke of Suffolk, and not my lord protector.</div>

<div class="dprose1"><span class="lnum">10</span>
 <span class="sd-cn">Suf.</span>  How now, fellow! wouldst any thing with me?</div>

<div class="dprose1"><span class="sd-cn">First Petit.</span>
 I pray, my lord, pardon me; I took ye for my lord protector.</div>

<div class="dprose1"><a class="lnum pginternal" href="#lnote-bac013" id="lnum-bac013">♦</a>
 <span class="sd-cn">Queen.</span>
 <span class="sd-inline">[<i>Reading</i>]</span>
‘To my Lord Protector!’ Are your supplications to his lordship? Let me see them: what is
<span class="lnum">15</span> thine?</div>

<div class="dprose1"><a class="lnum pginternal" href="#lnote-bac016" id="lnum-bac016">♦</a>
<span class="sd-cn">First Petit.</span>
Mine is, an’t please your grace, against John Goodman, my lord cardinal’s man, for keeping my house, and lands, and wife and all, from me.</div>

<div class="dprose1"><span class="sd-cn">Suf.</span>
Thy wife too! that’s some wrong, indeed. <a class="lnum pginternal" href="#lnote-bac020" id="lnum-bac020">20</a>
What’s yours? What’s here! <span class="sd-inline">[<i>Reads</i>]</span>
‘Against the Duke <a class="lnum pginternal" href="#lnote-bac021" id="lnum-bac021">♦</a>
of Suffolk, for enclosing the commons of Melford.’ How now, sir knave!</div>

<div class="dprose1"><span class="sd-cn">Sec. Petit.</span>
Alas, sir, I am but a poor petitioner of our whole township.</div>

<div class="dprose1"><a class="lnum pginternal" href="#lnote-bac025" id="lnum-bac025">25</a>
<span class="sd-cn">Peter</span>
<span class="sd-inline">[<i>giving his petition</i>].</span>
Against my master, Thomas Horner, for saying that the Duke of York was rightful heir to the crown.</div>

<div class="dprose1"><a class="lnum pginternal" href="#lnote-bac028" id="lnum-bac028">♦</a>
<span class="sd-cn">Queen.</span>
What say’st thou? did the Duke of York say he was rightful heir to the crown?</div>

<div class="dprose1"><a class="lnum pginternal" href="#lnote-bac030" id="lnum-bac030">30</a>
<span class="sd-cn">Peter.</span>
That my master was? no, forsooth: my master said that he was, and that the king was an usurper.</div>

<div class="dprose1"><a class="lnum pginternal" href="#lnote-bac032" id="lnum-bac032">♦</a>
<span class="sd-cn">Suf.</span>
Who is there? <span class="sd-inline">[<i>Enter Servant.</i>]</span>
Take this fellow in, and send for his master with a pursuivant presently: <a class="lnum pginternal" href="#lnote-bac034" id="lnum-bac034">♦</a>
we’ll hear more of your matter before the king. <span class="sd-proseend">[<i>Exit Servant with Peter.</i></span>
</div>

<div class="dverse1"><span class="lnum">35</span>
 <span class="sd-cn">Queen.</span>
And as for you, that love to be protected</div>
<div class="dverse">Under the wings of our protector’s grace,</div>
<div class="dverse"><a class="lnum pginternal" href="#lnote-bac037" id="lnum-bac037">♦</a>
Begin your suits anew, and sue to him. <span class="sd-verseend">[<i>Tears the supplications.</i></span></div>
<div class="dverse">Away, base cullions! Suffolk, let them go.</div>

<div class="dverse1"><a class="lnum pginternal" href="#lnote-bac039" id="lnum-bac039">♦</a>
 <span class="sd-cn">All.</span>
Come, let’s be gone. <span class="sd-verseend">[<i>Exeunt.</i></span></div>

<div class="dverse1"><span class="lnum">40</span>
 <span class="sd-cn">Queen.</span>
  My Lord of Suffolk, say, is this the guise,</div>
<div class="dverse"><a class="lnum pginternal" href="#lnote-bac041" id="lnum-bac041">♦</a>
 Is this the fashion in the court of England?</div>
<div class="dverse">Is this the government of Britain’s isle,</div>
<div class="dverse">And this the royalty of Albion’s king?</div>
<div class="dverse">What, shall King Henry be a pupil still</div>
<div class="dverse"><span class="lnum">45</span> Under the surly Gloucester’s governance?</div>
<div class="dverse">Am I a queen in title and in style,</div>
<div class="dverse">And must be made a subject to a duke?</div>
<div class="dverse">I tell thee, Pole, when in the city Tours</div>
<div class="dverse"><a class="lnum pginternal" href="#lnote-bac049" id="lnum-bac049">♦</a>
 Thou ran’st a tilt in honour of my love</div>
<div class="dverse"><span class="lnum">50</span> And stolest away the ladies’ hearts of France,</div>
<div class="dverse">I thought King Henry had resembled thee</div>
<div class="dverse">In courage, courtship and proportion:</div>
<div class="dverse">But all his mind is bent to holiness,</div>
<div class="dverse">To number Ave-Maries on his beads;</div>
<div class="dverse"><span class="lnum">55</span> His champions are the prophets and apostles,</div>
<div class="dverse">His weapons holy saws of sacred writ,</div>
<div class="dverse">His study is his tilt-yard, and his loves</div>
<div class="dverse"><a class="lnum pginternal" href="#lnote-bac058" id="lnum-bac058">♦</a>
 Are brazen images of canonized saints.</div>
<div class="dverse"><a class="lnum pginternal" href="#lnote-bac059" id="lnum-bac059">♦</a>
 I would the college of the cardinals</div>
<div class="dverse"><span class="lnum">60</span> Would choose him pope and carry him to Rome,</div>
<div class="dverse">And set the triple crown upon his head:</div>
<div class="dverse">That were a state fit for his holiness.</div>

<div class="dverse1"><a class="lnum pginternal" href="#lnote-bac063" id="lnum-bac063">♦</a>
 <span class="sd-cn">Suf.</span>
  Madam, be patient: as I was cause</div>
<div class="dverse">Your highness came to England, so will I</div>
<div class="dverse"><span class="lnum">65</span> In England work your grace’s full content.</div>

<div class="dverse1"><a class="lnum pginternal" href="#lnote-bac066" id="lnum-bac066">♦</a>
 <span class="sd-cn">Queen.</span>
  Beside the haughty protector, have we Beaufort</div>
<div class="dverse">The imperious churchman, Somerset, Buckingham,</div>
<div class="dverse">And grumbling York; and not the least of these</div>
<div class="dverse">But can do more in England than the king.</div>

<div class="dverse1"><span class="lnum">70</span>
 <span class="sd-cn">Suf.</span>
  And he of these that can do most of all</div>
<div class="dverse">Cannot do more in England than the Nevils:</div>
<div class="dverse">Salisbury and Warwick are no simple peers.</div>

<div class="dverse1"><span class="sd-cn">Queen.</span>
 Not all these lords do vex me half so much</div>
<div class="dverse">As that proud dame, the lord protector’s wife.</div>
<div class="dverse"><a class="lnum pginternal" href="#lnote-bac075" id="lnum-bac075">75</a>
 She sweeps it through the court with troops of ladies,</div>
<div class="dverse">More like an empress than duke Humphrey’s wife:</div>
<div class="dverse">Strangers in court do take her for the queen:</div>
<div class="dverse">She bears a duke’s revenues on her back,</div>
<div class="dverse"><a class="lnum pginternal" href="#lnote-bac079" id="lnum-bac079">♦</a>
 And in her heart she scorns our poverty:</div>
<div class="dverse"><span class="lnum">80</span> Shall I not live to be avenged on her?</div>
<div class="dverse">Contemptuous base-born callet as she is,</div>
<div class="dverse">She vaunted ’mongst her minions t’other day,</div>
<div class="dverse">The very train of her worst wearing gown</div>
<div class="dverse">Was better worth than all my father’s lands,</div>
<div class="dverse"><span class="lnum">85</span> Till Suffolk gave two dukedoms for his daughter.</div>

<div class="dverse1"><span class="sd-cn">Suf.</span>
 Madam, myself have limed a bush for her,</div>
<div class="dverse">And placed a quire of such enticing birds,</div>
<div class="dverse"><a class="lnum pginternal" href="#lnote-bac088" id="lnum-bac088">♦</a>
 That she will light to listen to the lays,</div>
<div class="dverse">And never mount to trouble you again.</div>
<div class="dverse"><span class="lnum">90</span> So, let her rest: and, madam, list to me;</div>
<div class="dverse">For I am bold to counsel you in this.</div>
<div class="dverse"><a class="lnum pginternal" href="#lnote-bac092" id="lnum-bac092">♦</a>
 Although we fancy not the cardinal,</div>
<div class="dverse">Yet must we join with him and with the lords,</div>
<div class="dverse">Till we have brought Duke Humphrey in disgrace.</div>
<div class="dverse"><span class="lnum">95</span> As for the Duke of York, this late complaint</div>
<div class="dverse">Will make but little for his benefit.</div>
<div class="dverse"><a class="lnum pginternal" href="#lnote-bac097" id="lnum-bac097">♦</a>
 So, one by one, we’ll weed them all at last,</div>
<div class="dverse"><a class="lnum pginternal" href="#lnote-bac098" id="lnum-bac098">♦</a>
 And you yourself shall steer the happy helm.</div>

<div class="sd-entry"><i>Sound a Sennet. Enter the</i>
<span class="smcaps">K<span>ING</span>,</span>
<span class="smcaps">D<span>UKE</span></span> <span class="smcaps">H<span>UMPHREY</span></span> of Gloucester, <span class="smcaps">C<span>ARDINAL</span></span>
<span class="smcaps">B<span>EAUFORT</span>,</span>
<span class="smcaps">B<span>UCKINGHAM</span>,</span>
<span class="smcaps">Y<span>ORK</span>,</span><span class="smcaps">S<span>OMERSET</span>,</span> <span class="smcaps">S<span>ALISBURY</span>,</span> <span class="smcaps">W<span>ARWICK</span>,</span> <i>and the</i>
<span class="smcaps">D<span>UCHESS</span></span>
<span class="smmaj">OF</span> <span class="smcaps">G<span>LOUCESTER</span>.</span></div>

<div class="dverse1"><a class="lnum pginternal" href="#lnote-bac099" id="lnum-bac099">♦</a>
 <span class="sd-cn">King.</span>
  For my part, noble lords, I care not which;</div>
<div class="dverse"><span class="lnum">100</span> Or Somerset or York, all’s one to me.</div>

<div class="dverse1"><span class="sd-cn">York.</span>
 If York have ill demean’d himself in France,</div>
<div class="dverse"><a class="lnum pginternal" href="#lnote-bac102" id="lnum-bac102">♦</a>
 Then let him be denay’d the regentship.</div>

<div class="dverse1"><span class="sd-cn">Som.</span>
 If Somerset be unworthy of the place,</div>
<div class="dverse">Let York be regent; I will yield to him.</div>

<div class="dverse1"><span class="lnum">105</span>
 <span class="sd-cn">War.</span>
  Whether your grace be worthy, yea or no,</div>
<div class="dverse">Dispute not that: York is the worthier.</div>

<div class="dverse1"><span class="sd-cn">Car.</span>
 Ambitious Warwick, let thy betters speak.</div>

<div class="dverse1"><a class="lnum pginternal" href="#lnote-bac108" id="lnum-bac108">♦</a>
 <span class="sd-cn">War.</span>
  The cardinal’s not my better in the field.</div>

<div class="dverse1"><span class="sd-cn">Buck.</span>
 All in this presence are thy betters, Warwick.</div>

<div class="dverse1"><span class="lnum">110</span>
 <span class="sd-cn">War.</span>
  Warwick may live to be the best of all.</div>

<div class="dverse1"><span class="sd-cn">Sal.</span>
 Peace, son! and show some reason, Buckingham,</div>
<div class="dverse">Why Somerset should be preferred in this.</div>

<div class="dverse1"><span class="sd-cn">Queen.</span>
 Because the king, forsooth, will have it so.</div>

<div class="dverse1"><span class="sd-cn">Glou.</span>
 Madam, the king is old enough himself</div>
<div class="dverse"><a class="lnum pginternal" href="#lnote-bac115" id="lnum-bac115">115</a>
 To give his censure: these are no women’s matters.</div>

<div class="dverse1"><span class="sd-cn">Queen.</span>
 If he be old enough, what needs your grace</div>
<div class="dverse">To be protector of his excellence?</div>

<div class="dverse1"><span class="sd-cn">Glou.</span>
 Madam, I am protector of the realm;</div>
<div class="dverse">And, at his pleasure, will resign my place.</div>

<div class="dverse1"><span class="lnum">120</span>
 <span class="sd-cn">Suf.</span>
  Resign it then and leave thine insolence.</div>
<div class="dverse">Since thou wert king—as who is king but thou?—</div>
<div class="dverse"><a class="lnum pginternal" href="#lnote-bac122" id="lnum-bac122">♦</a>
 The commonwealth hath daily run to wreck;</div>
<div class="dverse">The Dauphin hath prevail’d beyond the seas;</div>
<div class="dverse">And all the peers and nobles of the realm</div>
<div class="dverse"><span class="lnum">125</span> Have been as bondmen to thy sovereignty.</div>

<div class="dverse1"><span class="sd-cn">Car.</span>
 The commons hast thou rack’d; the clergy’s bags</div>
<div class="dverse">Are lank and lean with thy extortions.</div>

<div class="dverse1"><span class="sd-cn">Som.</span>
 Thy sumptuous buildings and thy wife’s attire</div>
<div class="dverse"><a class="lnum pginternal" href="#lnote-bac129" id="lnum-bac129">♦</a>
 Have cost a mass of public treasury.</div>

<div class="dverse1"><span class="lnum">130</span>
 <span class="sd-cn">Buck.</span>
  Thy cruelty in execution</div>
<div class="dverse">Upon offenders hath exceeded law</div>
<div class="dverse">And left thee to the mercy of the law.</div>

<div class="dverse1"><span class="sd-cn">Queen.</span>
 Thy sale of offices and towns in France,</div>
<div class="dverse">If they were known, as the suspect is great,</div>
<div class="dverse"><a class="lnum pginternal" href="#lnote-bac135" id="lnum-bac135">135</a>
 Would make thee quickly hop without thy head.
 <span class="sd-verseend">[<i>Exit Gloucester. The Queen drops her fan.</i></span></div>
<div class="dverse">Give me my fan: what, minion! can ye not? <span class="sd-verseend">[<i>She gives the Duchess a box on the ear.</i></span></div>
<div class="dverse">I cry you mercy, madam; was it you?</div>

<div class="dverse1"><span class="sd-cn">Duch.</span>
 Was’t I! yea, I it was, proud Frenchwoman:</div>
<div class="dverse">Could I come near your beauty with my nails,</div>
<div class="dverse"><a class="lnum pginternal" href="#lnote-bac140" id="lnum-bac140">140</a>
 I’ld set my ten commandments in your face.</div>

<div class="dverse1"><span class="sd-cn">King.</span>
 Sweet aunt, be quiet; ’twas against her will.</div>

<div class="dverse1"><span class="sd-cn">Duch.</span>
 Against her will! good king, look to’t in time;</div>
<div class="dverse">She’ll hamper thee, and dandle thee like a baby:</div>
<div class="dverse"><a class="lnum pginternal" href="#lnote-bac144" id="lnum-bac144">♦</a>
 Though in this place most master wear no breeches,</div>
<div class="dverse"><span class="lnum">145</span>
 She shall not strike Dame Eleanor unrevenged.
 <span class="sd-verseend">[<i>Exit.</i></span></div>

<div class="dverse1"><a class="lnum pginternal" href="#lnote-bac146" id="lnum-bac146">♦</a>
 <span class="sd-cn">Buck.</span>
 Lord cardinal, I will follow Eleanor,</div>
<div class="dverse">And listen after Humphrey, how he proceeds:</div>
<div class="dverse"><a class="lnum pginternal" href="#lnote-bac148" id="lnum-bac148">♦</a>
 She’s tickled now; her fume needs no spurs,</div>
<div class="dverse"><a class="lnum pginternal" href="#lnote-bac149" id="lnum-bac149">♦</a>
 She’ll gallop far enough to her destruction.
 <span class="sd-verseend">[<i>Exit.</i></span></div>

<div class="sd-entry"><i>Re-enter</i> <span class="smcaps">G<span>LOUCESTER</span>.</span></div>

<div class="dverse1"><a class="lnum pginternal" href="#lnote-bac150" id="lnum-bac150">150</a>
 <span class="sd-cn">Glou.</span>
  Now, lords, my choler being over-blown</div>
<div class="dverse">With walking once about the quadrangle,</div>
<div class="dverse">I come to talk of commonwealth affairs.</div>
<div class="dverse">As for your spiteful false objections,</div>
<div class="dverse">Prove them, and I lie open to the law:</div>
<div class="dverse"><a class="lnum pginternal" href="#lnote-bac155" id="lnum-bac155">155</a>
 But God in mercy so deal with my soul,</div>
<div class="dverse">As I in duty love my king and country!</div>
<div class="dverse">But, to the matter that we have in hand:</div>
<div class="dverse">I say, my sovereign, York is meetest man</div>
<div class="dverse">To be your regent in the realm of France.</div>

<div class="dverse1"><span class="lnum">160</span>
 <span class="sd-cn">Suf.</span>
  Before we make election, give me leave</div>
<div class="dverse">To show some reason, of no little force,</div>
<div class="dverse">That York is most unmeet of any man.</div>

<div class="dverse1"><span class="sd-cn">York.</span>
 I’ll tell thee, Suffolk, why I am unmeet:</div>
<div class="dverse">First, for I cannot flatter thee in pride;</div>
<div class="dverse"><span class="lnum">165</span> Next, if I be appointed for the place,</div>
<div class="dverse"><a class="lnum pginternal" href="#lnote-bac166" id="lnum-bac166">♦</a>
 My Lord of Somerset will keep me here,</div>
<div class="dverse">Without discharge, money, or furniture,</div>
<div class="dverse">Till France be won into the Dauphin’s hands:</div>
<div class="dverse">Last time, I danced attendance on his will</div>
<div class="dverse"><span class="lnum">170</span> Till Paris was besieged, famish’d, and lost.</div>

<div class="dverse1"><span class="sd-cn">War.</span>
 That can I witness; and a fouler fact</div>
<div class="dverse">Did never traitor in the land commit.</div>

<div class="dverse1"><span class="sd-cn">Suf.</span>
 Peace, headstrong Warwick!</div>

<div class="dverse1"><a class="lnum pginternal" href="#lnote-bac174" id="lnum-bac174">♦</a>
 <span class="sd-cn">War.</span>
  Image of pride, why should I hold my peace?</div>

<div class="sd-entry"><i>Enter</i> <span class="smcaps">H<span>ORNER</span>,</span> <i>the Armourer, and his man</i>
<span class="smcaps">P<span>ETER</span>,</span> <i>guarded</i>.</div>

<div class="dverse1"><span class="lnum">175</span>
 <span class="sd-cn">Suf.</span>
  Because here is a man accused of treason:</div>
<div class="dverse">Pray God the Duke of York excuse himself!</div>

<div class="dverse1"><span class="sd-cn">York.</span>
 Doth any one accuse York for a traitor?</div>

<div class="dverse1"><span class="sd-cn">King.</span>
 What mean’st thou, Suffolk; tell me, what are these?</div>

<div class="dverse1"><span class="sd-cn">Suf.</span>
 Please it your majesty, this is the man</div>
<div class="dverse"><span class="lnum">180</span> That doth accuse his master of high treason:</div>
<div class="dverse">His words were these: that Richard Duke of York</div>
<div class="dverse">Was rightful heir unto the English crown</div>
<div class="dverse">And that your majesty was an usurper.</div>

<div class="dverse1"><span class="sd-cn">King.</span>
 Say, man, were these thy words?</div>

<div class="dprose1"><a class="lnum pginternal" href="#lnote-bac185" id="lnum-bac185">185</a>
<span class="sd-cn">Hor.</span>
An’t shall please your majesty, I never said nor thought any such matter: God is my witness, I am falsely accused by the villain.</div>

<div class="dprose1"><span class="sd-cn">Pet.</span>
By these ten bones, my lords, he did speak them to me in the garret one night, as we were scouring my <span class="lnum">190</span>
Lord of York’s armour.</div>

<div class="dverse1"><span class="sd-cn">York.</span>
 Base dunghill villain and mechanical,</div>
<div class="dverse">I’ll have thy head for this thy traitor’s speech.</div>
<div class="dverse">I do beseech your royal majesty,</div>
<div class="dverse">Let him have all the rigour of the law.</div>

<div class="dprose1"><span class="lnum">195</span>
 <span class="sd-cn">Hor.</span>
 Alas, my lord, hang me, if ever I spake the words. My accuser is my ’prentice; and when I did correct him for his fault the other day, he did vow upon his knees he would be even with me: I have good witness of this; therefore I beseech your majesty, do not cast away an <span class="lnum">200</span> honest man for a villain’s accusation. </div>

<div class="dverse1"><span class="sd-cn">King.</span>
 Uncle, what shall we say to this in law?</div>

<div class="dverse1"><a class="lnum pginternal" href="#lnote-bac202" id="lnum-bac202">♦</a>
 <span class="sd-cn">Glou.</span>
  This doom, my lord, if I may judge:</div>
<div class="dverse">Let Somerset be regent o’er the French,</div>
<div class="dverse">Because in York this breeds suspicion:</div>
<div class="dverse"><span class="lnum">205</span> And let these have a day appointed them</div>
<div class="dverse">For single combat in convenient place,</div>
<div class="dverse">For he hath witness of his servant’s malice:</div>
<div class="dverse"><a class="lnum pginternal" href="#lnote-bac208" id="lnum-bac208">♦</a>
 This is the law, and this Duke Humphrey’s doom.</div>

<div class="dverse1"><span class="sd-cn">Som.</span>
 I humbly thank your royal majesty.</div>

<div class="dverse1"><span class="lnum">210</span>
 <span class="sd-cn">Hor.</span>
  And I accept the combat willingly.</div>

<div class="dprose1"><span class="sd-cn">Pet.</span>
 Alas, my lord, I cannot fight; for God’s sake, pity <a class="lnum pginternal" href="#lnote-bac212" id="lnum-bac212">♦</a>
 my case. The spite of man prevaileth against me. O Lord, have mercy upon me! I shall never be able to fight a blow. O Lord, my heart!</div>

<div class="dprose1"><span class="lnum">215</span>
 <span class="sd-cn">Glou.</span>  Sirrah, or you must fight, or else be hang’d.</div>

<div class="dprose1"><a class="lnum pginternal" href="#lnote-bac216" id="lnum-bac216">♦</a>
 <span class="sd-cn">King.</span>
 Away with them to prison; and the day of combat shall be the last of the
 next month. Come, Somerset, we’ll see thee sent away.
 <span class="sd-proseend">[<i>Flourish. Exeunt.</i></span></div>

<div class="section">
<h4 class="h4main" id="lnum-sc4"><span class="dnavigate">bad</span>
<span class="smcaps">S<span>CENE</span></span> IV. <span class="smcaps">G<span>LOUCESTER’S</span></span> <i>garden</i>.</h4>

<div class="sd-schg"><i>Enter</i> <span class="smcaps">M<span>ARGERY</span></span> <span class="smcaps">J<span>OURDAIN</span>,</span> <span class="smcaps">H<span>UME</span>,</span> <span class="smcaps">S<span>OUTHWELL</span>,</span> <i>and</i> <span class="smcaps">B<span>OLINGBROKE</span>.</span></div></div>

<div class="dprose1"><a class="lnum pginternal" href="#lnote-bad001" id="lnum-bad001">♦</a>
 <span class="sd-cn">Hume.</span>
 Come, my masters; the duchess, I tell you, expects performance of your promises.</div>

<div class="dprose1"><span class="sd-cn">Boling.</span>
 Master Hume, we are therefore provided: will her
 ladyship behold and hear our exorcisms?</div>

<div class="dprose1"><a class="lnum pginternal" href="#lnote-bad005" id="lnum-bad005">5</a>
<span class="sd-cn">Hume.</span>
Ay, what else? fear you not her courage.</div>

<div class="dprose1"><span class="sd-cn">Boling.</span>
 I have heard her reported to be a woman of an invincible spirit:
 but it shall be convenient, Master Hume, that you be by her aloft,
 while we be busy below; and so, I pray you, go, in God’s name, and leave us.
 <span class="sd-inline">[<i>Exit Hume.</i>]</span>
 <a class="lnum pginternal" href="#lnote-bad010" id="lnum-bad010">10</a>
 Mother Jourdain, be you prostrate and grovel on the earth;
 <a class="lnum pginternal" href="#lnote-bad011" id="lnum-bad011">♦</a>
 John Southwell, read you; and let us to our work.</div>

<div class="sd-entry"><i>Enter</i> Duchess <i>aloft</i>, <span class="smcaps">H<span>UME</span></span> <i>following</i>.</div>

<div class="dprose1"><a class="lnum pginternal" href="#lnote-bad012" id="lnum-bad012">♦</a>
<span class="sd-cn">Duch.</span>
Well said, my masters; and welcome all. To this gear the sooner the better.</div>

<div class="dverse1"><span class="sd-cn">Boling.</span>
 Patience, good lady; wizards know their times:</div>
<div class="dverse"><a class="lnum pginternal" href="#lnote-bad015" id="lnum-bad015">15</a>
 Deep night, dark night, the silent of the night,</div>
<div class="dverse">The time of night when Troy was set on fire;</div>
<div class="dverse">The time when screech-owls cry and ban-dogs howl</div>
<div class="dverse"><a class="lnum pginternal" href="#lnote-bad018" id="lnum-bad018">♦</a>
 And spirits walk and ghosts break up their graves,</div>
<div class="dverse">That time best fits the work we have in hand.</div>
<div class="dverse"><span class="lnum">20</span> Madam, sit you and fear not: whom we raise,</div>
<div class="dverse"><a class="lnum pginternal" href="#lnote-bad021" id="lnum-bad021">♦</a>
 We will make fast within a hallow’d verge.
 <span class="sd-verseend">[<i>Here they do the ceremonies belonging, and make the circle;
 Bolingbroke or Southwell reads</i>, Conjuro te, &amp;c. <i>It thunders and lightens
 terribly; then the Spirit riseth.</i></span></div>

<div class="dverse1"><a class="lnum pginternal" href="#lnote-bad022" id="lnum-bad022">♦</a>
 <span class="sd-cn">Spir.</span>
Adsum.</div>

<div class="dverse1"><a class="lnum pginternal" href="#lnote-bad023" id="lnum-bad023">♦</a>
 <span class="sd-cn">M. Jourd.</span>
  Asmath,</div>
<div class="dverse">By the eternal God, whose name and power</div>
<div class="dverse"><a class="lnum pginternal" href="#lnote-bad025" id="lnum-bad025">25</a>
 Thou tremblest at, answer that I shall ask;</div>
<div class="dverse">For, till thou speak, thou shalt not pass from hence.</div>

<div class="dverse1"><a class="lnum pginternal" href="#lnote-bad027" id="lnum-bad027">♦</a>
 <span class="sd-cn">Spir.</span>
  Ask what thou wilt. That I had said and done!</div>

<div class="dverse1"><a class="lnum pginternal" href="#lnote-bad028" id="lnum-bad028">♦</a>
 <span class="sd-cn">Boling.</span>
 ‘First of the king: what shall of him become?’
 <span class="sd-verseend">[<i>Reading out of a paper.</i></span></div>

<div class="dverse1"><span class="sd-cn">Spir.</span>
 The duke yet lives that Henry shall depose;</div>
<div class="dverse"><a class="lnum pginternal" href="#lnote-bad030" id="lnum-bad030">30</a>
 But him outlive, and die a violent death.
 <span class="sd-verseend">[<i>As the Spirit speaks, Southwell writes the answer.</i></span></div>

<div class="dverse1"><a class="lnum pginternal" href="#lnote-bad031" id="lnum-bad031">♦</a>
 <span class="sd-cn">Boling.</span>
  ‘What fates await the Duke of Suffolk?’</div>

<div class="dverse1"><span class="sd-cn">Spir.</span>
 By water shall he die, and take his end.</div>

<div class="dverse1"><span class="sd-cn">Boling.</span>
 ‘What shall befall the Duke of Somerset?’</div>

<div class="dverse1"><span class="sd-cn">Spir.</span>
 Let him shun castles;</div>
<div class="dverse"><a class="lnum pginternal" href="#lnote-bad035" id="lnum-bad035">35</a>
 Safer shall he be upon the sandy plains</div>
<div class="dverse"><a class="lnum pginternal" href="#lnote-bad036" id="lnum-bad036">♦</a>
 Than where castles mounted stand.</div>
<div class="dverse">Have done, for more I hardly can endure.</div>

<div class="dverse1"><span class="sd-cn">Boling.</span>
 Descend to darkness and the burning lake!</div>
<div class="dverse"><a class="lnum pginternal" href="#lnote-bad039" id="lnum-bad039">♦</a>
 False fiend, avoid!
 <span class="sd-verseend">[<i>Thunder and lightning. Exit Spirit.</i></span></div>

<div class="sd-entry"><i>Enter the</i> <span class="smcaps">D<span>UKE</span></span> <span class="smmaj">OF</span>
<span class="smcaps">Y<span>ORK</span></span> <i>and the</i> <span class="smcaps">D<span>UKE</span></span> <span class="smmaj">OF</span>
<span class="smcaps">B<span>UCKINGHAM</span></span> <i>with their</i> Guard <i>and break in</i>.</div>

<div class="dverse1"><span class="lnum">40</span>
 <span class="sd-cn">York.</span>
  Lay hands upon these traitors and their trash.</div>
<div class="dverse">Beldam, I think we watch’d you at an inch.</div>
<div class="dverse"><a class="lnum pginternal" href="#lnote-bad042" id="lnum-bad042">♦</a>
 What, madam, are you there? the king and commonweal</div>
<div class="dverse"><a class="lnum pginternal" href="#lnote-bad043" id="lnum-bad043">♦</a>
 Are deeply indebted for this piece of pains:</div>
<div class="dverse">My lord protector will, I doubt it not,</div>
<div class="dverse"><span class="lnum">45</span> See you well guerdon’d for these good deserts.</div>

<div class="dverse1"><span class="sd-cn">Duch.</span>
 Not half so bad as thine to England’s king,</div>
<div class="dverse"><a class="lnum pginternal" href="#lnote-bad047" id="lnum-bad047">♦</a>
 Injurious duke, that threatest where’s no cause.</div>

<div class="dverse1"><a class="lnum pginternal" href="#lnote-bad048" id="lnum-bad048">♦</a>
 <span class="sd-cn">Buck.</span>
  True, madam, none at all: what call you this?</div>
<div class="dverse">Away with them! let them be clapp’d up close,</div>
<div class="dverse"><a class="lnum pginternal" href="#lnote-bad050" id="lnum-bad050">50</a>
 And kept asunder. You, madam, shall with us.</div>
<div class="dverse"><a class="lnum pginternal" href="#lnote-bad051" id="lnum-bad051">♦</a>
 Stafford, take her to thee.
 <span class="sd-verseend">[<i>Exeunt above Duchess and Hume, guarded.</i></span></div>
<div class="dverse"><a class="lnum pginternal" href="#lnote-bad052" id="lnum-bad052">♦</a>
 We’ll see your trinkets here all forthcoming.</div>
<div class="dverse"><a class="lnum pginternal" href="#lnote-bad053" id="lnum-bad053">♦</a>
 All, away!
 <span class="sd-verseend">[<i>Exeunt guard with Jourdain, Southwell, &amp;c.</i></span></div>

<div class="dverse1"><a class="lnum pginternal" href="#lnote-bad054" id="lnum-bad054">♦</a>
 <span class="sd-cn">York.</span>
  Lord Buckingham, methinks, you watch’d her well:</div>
<div class="dverse"><a class="lnum pginternal" href="#lnote-bad055" id="lnum-bad055">55</a>
 A pretty plot, well chosen to build upon!</div>
<div class="dverse">Now, pray, my lord, let’s see the devil’s writ.</div>
<div class="dverse">What have we here?
 <span class="sd-verseend">[<i>Reads.</i></span></div>
<div class="dverse">‘The duke yet lives, that Henry shall depose;</div>
<div class="dverse">But him outlive, and die a violent death.’</div>
<div class="dverse"><span class="lnum">60</span> Why, this is just</div>
<div class="dverse"><a class="lnum pginternal" href="#lnote-bad061" id="lnum-bad061">♦</a>
 ‘Aio te, Æacida, Romanos vincere posse.’</div>
<div class="dverse">Well, to the rest:</div>
<div class="dverse">‘Tell me what fate awaits the Duke of Suffolk?</div>
<div class="dverse">By water shall he die, and take his end.</div>
<div class="dverse"><a class="lnum pginternal" href="#lnote-bad065" id="lnum-bad065">65</a>
 What shall betide the Duke of Somerset?</div>
<div class="dverse">Let him shun castles;</div>
<div class="dverse">Safer shall he be upon the sandy plains</div>
<div class="dverse">Than where castles mounted stand.’</div>
<div class="dverse"><a class="lnum pginternal" href="#lnote-bad069" id="lnum-bad069">♦</a>
 Come, come, my lords;</div>
<div class="dverse"><a class="lnum pginternal" href="#lnote-bad070" id="lnum-bad070">70</a>
 These oracles are hardly attain’d,</div>
<div class="dverse">And hardly understood.</div>
<div class="dverse">The king is now in progress towards Saint Alban’s,</div>
<div class="dverse">With him the husband of this lovely lady:</div>
<div class="dverse"><a class="lnum pginternal" href="#lnote-bad074" id="lnum-bad074">♦</a>
 Thither go these news, as fast as horse can carry them:</div>
<div class="dverse"><span class="lnum">75</span> A sorry breakfast for my lord protector.</div>

<div class="dverse1"><span class="sd-cn">Buck.</span>
 Your grace shall give me leave, my Lord of York,</div>
<div class="dverse">To be the post, in hope of his reward.</div>

<div class="dverse1"><a class="lnum pginternal" href="#lnote-bad078" id="lnum-bad078">♦</a>
 <span class="sd-cn">York.</span>
  At your pleasure, my good lord. Who’s within there, ho!</div>

<div class="sd-entry"><i>Enter a</i> Servingman.</div>

<div class="dverse">Invite my Lords of Salisbury and Warwick</div>
<div class="dverse"><span class="lnum">80</span> To sup with me to-morrow night. Away! <span class="sd-verseend">[<i>Exeunt.</i></span></div>

<div class="section">
<h3 class="h3main">ACT II.</h3>

<h4 class="h4main"><span class="dnavigate">bba</span>
<span class="smcaps">S<span>CENE</span></span> I. <i>Saint Alban’s</i>.</h4>

<div class="sd-schg"><i>Enter the</i> <span class="smcaps">K<span>ING</span>,</span> <span class="smcaps">Q<span>UEEN</span>,</span> <span class="smcaps">G<span>LOUCESTER</span>,</span> <span class="smcaps">C<span>ARDINAL</span>,</span> <i>and</i> <span class="smcaps">S<span>UFFOLK</span>,</span> <i>with</i> Falconers
<i>halloing</i>.</div></div>

<div class="dverse1"><a class="lnum pginternal" href="#lnote-bba001" id="lnum-bba001">♦</a>
 <span class="sd-cn">Queen.</span>
  Believe me, lords, for flying at the brook,</div>
<div class="dverse">I saw not better sport these seven years’ day:</div>
<div class="dverse">Yet, by your leave, the wind was very high;</div>
<div class="dverse">And, ten to one, old Joan had not gone out.</div>

<div class="dverse1"><span class="lnum">5</span>
 <span class="sd-cn">King.</span>
  But what a point, my lord, your falcon made,</div>
<div class="dverse">And what a pitch she flew above the rest!</div>
<div class="dverse">To see how God in all his creatures works!</div>
<div class="dverse">Yea, man and birds are fain of climbing high.</div>

<div class="dverse1"><a class="lnum pginternal" href="#lnote-bba009" id="lnum-bba009">♦</a>
 <span class="sd-cn">Suf.</span>
  No marvel, an it like your majesty,</div>
<div class="dverse"><span class="lnum">10</span> My lord protector’s hawks do tower so well;</div>
<div class="dverse">They know their master loves to be aloft</div>
<div class="dverse">And bears his thoughts above his falcon’s pitch.</div>

<div class="dverse1"><span class="sd-cn">Glou.</span>
 My lord, ’tis but a base ignoble mind</div>
<div class="dverse">That mounts no higher than a bird can soar.</div>

<div class="dverse1"><a class="lnum pginternal" href="#lnote-bba015" id="lnum-bba015">15</a>
 <span class="sd-cn">Car.</span>
  I thought as much; he would be above the clouds.</div>

<div class="dverse1"><span class="sd-cn">Glou.</span>
 Ay, my lord cardinal? how think you by that?</div>
<div class="dverse">Were it not good your grace could fly to heaven?</div>

<div class="dverse1"><span class="sd-cn">King.</span>
 The treasury of everlasting joy.</div>

<div class="dverse1"><span class="sd-cn">Car.</span>
 Thy heaven is on earth; thine eyes and thoughts</div>
<div class="dverse"><a class="lnum pginternal" href="#lnote-bba020" id="lnum-bba020">20</a>
 Beat on a crown, the treasure of thy heart;</div>
<div class="dverse">Pernicious protector, dangerous peer,</div>
<div class="dverse">That smooth’st it so with king and commonweal!</div>

<div class="dverse1"><a class="lnum pginternal" href="#lnote-bba023" id="lnum-bba023">♦</a>
 <span class="sd-cn">Glou.</span>
  What, cardinal, is your priesthood grown peremptory?</div>
<div class="dverse"><a class="lnum pginternal" href="#lnote-bba024" id="lnum-bba024">♦</a>
 Tantæne animis cœlestibus iræ?</div>
<div class="dverse"><a class="lnum pginternal" href="#lnote-bba025" id="lnum-bba025">25</a>
 Churchmen so hot? good uncle, hide such malice;</div>
<div class="dverse"><a class="lnum pginternal" href="#lnote-bba026" id="lnum-bba026">♦</a>
 With such holiness can you do it?</div>

<div class="dverse1"><span class="sd-cn">Suf.</span>
 No malice, sir; no more than well becomes</div>
<div class="dverse">So good a quarrel and so bad a peer.</div>

<div class="dverse1"><span class="sd-cn">Glou.</span>
 As who, my lord?</div>

<div class="dverse1"><a class="lnum pginternal" href="#lnote-bba029" id="lnum-bba029">♦</a>
 <span class="sd-cn">Suf.</span>
 <span class="i09"> </span> Why, as you, my lord,</div>
<div class="dverse"><a class="lnum pginternal" href="#lnote-bba030" id="lnum-bba030">30</a>
 An’t like your lordly lord-protectorship.</div>

<div class="dverse1"><span class="sd-cn">Glou.</span>
 Why, Suffolk, England knows thine insolence.</div>

<div class="dverse1"><span class="sd-cn">Queen.</span>
 And thy ambition, Gloucester.</div>

<div class="dverse1"><a class="lnum pginternal" href="#lnote-bba033" id="lnum-bba033">♦</a>
 <span class="sd-cn">King.</span>
  I prithee, peace, good queen,</div>
<div class="dverse"><a class="lnum pginternal" href="#lnote-bba034" id="lnum-bba034">♦</a>
 And whet not on these furious peers;</div>
<div class="dverse"><span class="lnum">35</span> For blessed are the peacemakers on earth.</div>

<div class="dverse1"><span class="sd-cn">Car.</span>
 Let me be blessed for the peace I make,</div>
<div class="dverse">Against this proud protector, with my sword!</div>

<div class="dverse1"><a class="lnum pginternal" href="#lnote-bba038" id="lnum-bba038">♦</a>
 <span class="sd-cn">Glou.</span>
 <span class="sd-inline">[<i>Aside to Car.</i>]</span>
 Faith, holy uncle, would ’twere come to that!</div>

<div class="dverse1"><span class="sd-cn">Car.</span>
 <span class="sd-inline">[<i>Aside to Glou.</i>]</span>
 Marry, when thou darest.</div>

<div class="dverse1"><a class="lnum pginternal" href="#lnote-bba040" id="lnum-bba040">40</a>
 <span class="sd-cn">Glou.</span>
 <span class="sd-inline">[<i>Aside to Car.</i>]</span>
 Make up no factious numbers for the matter;</div>
<div class="dverse">In thine own person answer thy abuse.</div>

<div class="dverse1"><a class="lnum pginternal" href="#lnote-bba042" id="lnum-bba042">♦</a>
 <span class="sd-cn">Car.</span>
 <span class="sd-inline">[<i>Aside to Glou.</i>]</span>
 Ay, where thou darest not peep: an if thou darest,</div>
<div class="dverse">This evening, on the east side of the grove.</div>

<div class="dverse1"><span class="sd-cn">King.</span>
 How now, my lords!</div>

<div class="dverse1"><span class="sd-cn">Car.</span>
 <span class="i09"> </span>  Believe me, cousin Gloucester,</div>
<div class="dverse"><span class="lnum">45</span> Had not your man put up the fowl so suddenly,</div>
<div class="dverse"><a class="lnum pginternal" href="#lnote-bba046" id="lnum-bba046">♦</a>
 We had had more sport. <span class="sd-inline">[<i>Aside to Glou.</i>]</span> Come with thy two-hand sword.</div>

<div class="dverse1"><a class="lnum pginternal" href="#lnote-bba047" id="lnum-bba047">♦</a>
 <span class="sd-cn">Glou.</span>
  True, uncle.</div>

<div class="dverse1"><a class="lnum pginternal" href="#lnote-bba048" id="lnum-bba048">♦</a>
 <span class="sd-cn">Car.</span>
 <span class="sd-inline">[<i>Aside to Glou.</i>]</span>
 Are ye advised? the east side of the grove?</div>

<div class="dverse1"><span class="sd-cn">Glou.</span>
 <span class="sd-inline">[<i>Aside to Car.</i>]</span>
 Cardinal, I am with you.</div>

<div class="dverse1"><span class="sd-cn">King.</span>
 <span class="i09"> </span>
 Why, how now, uncle Gloucester!</div>

<div class="dverse1"><span class="lnum">50</span>
 <span class="sd-cn">Glou.</span>
  Talking of hawking; nothing else, my lord.</div>
<div class="dverse"><a class="lnum pginternal" href="#lnote-bba051" id="lnum-bba051">♦</a>
 <span class="sd-inline">[<i>Aside to Car.</i>]</span>
  Now, by God’s mother, priest, I’ll shave your crown for this.</div>
<div class="dverse">Or all my fence shall fail.</div>

<div class="dverse1"><a class="lnum pginternal" href="#lnote-bba053" id="lnum-bba053">♦</a>
 <span class="sd-cn">Car.</span>
 <span class="sd-inline">[<i>Aside to Glou.</i>]</span> Medice, teipsum—</div>
<div class="dverse">Protector, see to’t well, protect yourself.</div>

<div class="dverse1"><a class="lnum pginternal" href="#lnote-bba055" id="lnum-bba055">55</a>
 <span class="sd-cn">King.</span>
  The winds grow high; so do your stomachs, lords.</div>
<div class="dverse">How irksome is this music to my heart!</div>
<div class="dverse">When such strings jar, what hope of harmony?</div>
<div class="dverse">I pray, my lords, let me compound this strife.</div>

<div class="sd-entry"><i>Enter a</i> Townsman <i>of Saint Alban’s crying</i>
 ‘A miracle!’</div>

<div class="dverse1"><a class="lnum pginternal" href="#lnote-bba059" id="lnum-bba059">♦</a>
 <span class="sd-cn">Glou.</span>
  What means this noise?</div>
<div class="dverse"><span class="lnum">60</span> Fellow, what miracle dost thou proclaim?</div>

<div class="dverse1"><a class="lnum pginternal" href="#lnote-bba061" id="lnum-bba061">♦</a>
 <span class="sd-cn">Towns.</span>
  A miracle! a miracle!</div>

<div class="dverse1"><a class="lnum pginternal" href="#lnote-bba062" id="lnum-bba062">♦</a>
 <span class="sd-cn">Suf.</span>
  Come to the king and tell him what miracle.</div>

<div class="dverse1"><span class="sd-cn">Towns.</span>
 Forsooth, a blind man at Saint Alban’s shrine,</div>
<div class="dverse">Within this half-hour, hath received his sight;</div>
<div class="dverse"><span class="lnum">65</span> A man that ne’er saw in his life before.</div>

<div class="dverse1"><span class="sd-cn">King.</span>
 Now, God be praised, that to believing souls</div>
<div class="dverse"><a class="lnum pginternal" href="#lnote-bba067" id="lnum-bba067">♦</a>
 Gives light in darkness, comfort in despair!</div>

<div class="sd-entry"><i>Enter the</i> Mayor <i>of Saint Alban’s and his brethren, bearing</i> <span class="smcaps">S<span>IMPCOX</span>,</span> <i>between two in a chair</i>, <span class="smcaps">S<span>IMPCOX’S</span></span> Wife <i>following</i>.</div>

<div class="dverse1"><a class="lnum pginternal" href="#lnote-bba068" id="lnum-bba068">♦</a>
 <span class="sd-cn">Car.</span>
  Here comes the townsmen on procession,</div>
<div class="dverse"><a class="lnum pginternal" href="#lnote-bba069" id="lnum-bba069">♦</a>
 To present your highness with the man.</div>

<div class="dverse1"><span class="lnum">70</span>
 <span class="sd-cn">King.</span>
  Great is his comfort in this earthly vale,</div>
<div class="dverse"><a class="lnum pginternal" href="#lnote-bba071" id="lnum-bba071">♦</a>
 Although by his sight his sin be multiplied.</div>

<div class="dverse1"><span class="sd-cn">Glou.</span>
 Stand by, my masters: bring him near the king;</div>
<div class="dverse">His highness’ pleasure is to talk with him.</div>

<div class="dverse1"><span class="sd-cn">King.</span>
 Good fellow, tell us here the circumstance,</div>
<div class="dverse"><span class="lnum">75</span> That we for thee may glorify the Lord.</div>
<div class="dverse">What, hast thou been long blind and now restored?</div>

<div class="dverse1"><a class="lnum pginternal" href="#lnote-bba077" id="lnum-bba077">♦</a>
 <span class="sd-cn">Simp.</span>
  Born blind, an’t please your grace.</div>

<div class="dverse1"><span class="sd-cn">Wife.</span>
 Ay, indeed, was he.</div>

<div class="dverse1"><span class="sd-cn">Suf.</span>
 What woman is this?</div>

<div class="dverse1"><span class="lnum">80</span>
 <span class="sd-cn">Wife.</span>
  His wife, an’t like your worship.</div>

<div class="dverse1"><a class="lnum pginternal" href="#lnote-bba081" id="lnum-bba081">♦</a>
 <span class="sd-cn">Glou.</span>
  Hadst thou been his mother, thou couldst have better told.</div>

<div class="dverse1"><span class="sd-cn">King.</span>
 Where wert thou born?</div>

<div class="dverse1"><a class="lnum pginternal" href="#lnote-bba083" id="lnum-bba083">♦</a>
 <span class="sd-cn">Simp.</span>
  At Berwick in the north, an’t like your grace.</div>

<div class="dverse1"><a class="lnum pginternal" href="#lnote-bba084" id="lnum-bba084">♦</a>
 <span class="sd-cn">King.</span>
  Poor soul, God’s goodness hath been great to thee:</div>
<div class="dverse"><a class="lnum pginternal" href="#lnote-bba085" id="lnum-bba085">85</a>
 Let never day nor night unhallow’d pass,</div>
<div class="dverse">But still remember what the Lord hath done.</div>

<div class="dverse1"><span class="sd-cn">Queen.</span>
 Tell me, good fellow, camest thou here by chance,</div>
<div class="dverse">Or of devotion, to this holy shrine?</div>

<div class="dverse1"><span class="sd-cn">Simp.</span>
 God knows, of pure devotion; being call’d</div>
<div class="dverse"><span class="lnum">90</span> A hundred times and oftener, in my sleep,</div>
<div class="dverse"><a class="lnum pginternal" href="#lnote-bba091" id="lnum-bba091">♦</a>
 By good Saint Alban; who said, ‘Simpcox, come,</div>
<div class="dverse"><a class="lnum pginternal" href="#lnote-bba092" id="lnum-bba092">♦</a>
 Come, offer at my shrine, and I will help thee.’</div>

<div class="dverse1"><a class="lnum pginternal" href="#lnote-bba093" id="lnum-bba093">♦</a>
 <span class="sd-cn">Wife.</span>
  Most true, forsooth; and many time and oft</div>
<div class="dverse">Myself have heard a voice to call him so.</div>

<div class="dverse1"><span class="sd-cn">Car.</span>
 What, art thou lame?</div>

<div class="dverse1"><span class="lnum">95</span>
 <span class="sd-cn">Simp.</span>
 <span class="i10"> </span> Ay, God Almighty help me!</div>

<div class="dverse1"><span class="sd-cn">Suf.</span>
 How earnest thou so?</div>

<div class="dverse1"><a class="lnum pginternal" href="#lnote-bba096" id="lnum-bba096">♦</a>
 <span class="sd-cn">Simp.</span>
 <span class="i10"> </span> A fall off of a tree.</div>

<div class="dverse1"><span class="sd-cn">Wife.</span>
 A plum-tree, master.</div>

<div class="dverse1"><span class="sd-cn">Glou.</span>
 <span class="i09"> </span> How long hast thou been blind?</div>

<div class="dverse1"><span class="sd-cn">Simp.</span>
 O, born so, master.</div>

<div class="dverse1"><span class="sd-cn">Glou.</span>
 <span class="i09"> </span> What, and wouldst climb a tree?</div>

<div class="dverse1"><a class="lnum pginternal" href="#lnote-bba099" id="lnum-bba099">♦</a>
 <span class="sd-cn">Simp.</span>
  But that in all my life, when I was a youth.</div>

<div class="dverse1"><span class="lnum">100</span>
 <span class="sd-cn">Wife.</span>
  Too true; and bought his climbing very dear.</div>

<div class="dverse1"><span class="sd-cn">Glou.</span>
 Mass, thou lovedst plums well, that wouldst venture so.</div>

<div class="dverse1"><a class="lnum pginternal" href="#lnote-bba102" id="lnum-bba102">♦</a>
 <span class="sd-cn">Simp.</span>
  Alas, good master, my wife desired some damsons,</div>
<div class="dverse">And made me climb, with danger of my life.</div>

<div class="dverse1"><span class="sd-cn">Glou.</span>
 A subtle knave! but yet it shall not serve.</div>
<div class="dverse"><a class="lnum pginternal" href="#lnote-bba105" id="lnum-bba105">105</a>
 Let me see thine eyes: wink now: now open them:</div>
<div class="dverse">In my opinion yet thou see’st not well.</div>

<div class="dverse1"><a class="lnum pginternal" href="#lnote-bba107" id="lnum-bba107">♦</a>
 <span class="sd-cn">Simp.</span>
  Yes, master, clear as day, I thank God and</div>
<div class="dverse"><a class="lnum pginternal" href="#lnote-bba108" id="lnum-bba108">♦</a>
 Saint Alban.</div>

<div class="dverse1"><span class="sd-cn">Glou.</span>
 Say’st thou me so? What colour is this cloak of?</div>

<div class="dverse1"><span class="lnum">110</span>
 <span class="sd-cn">Simp.</span>
  Red, master; red as blood.</div>

<div class="dverse1"><span class="sd-cn">Glou.</span>
 Why, that’s well said. What colour is my gown of?</div>

<div class="dverse1"><span class="sd-cn">Simp.</span>
 Black, forsooth: coal-black as jet.</div>

<div class="dverse1"><span class="sd-cn">King.</span>
 Why, then, thou know’st what colour jet is of?</div>

<div class="dverse1"><a class="lnum pginternal" href="#lnote-bba114" id="lnum-bba114">♦</a>
 <span class="sd-cn">Suf.</span>
  And yet, I think, jet did he never see.</div>

<div class="dverse1"><span class="lnum">115</span>
 <span class="sd-cn">Glou.</span>
  But cloaks and gowns, before this day, a many.</div>

<div class="dverse1"><span class="sd-cn">Wife.</span>
 Never, before this day, in all his life.</div>

<div class="dverse1"><span class="sd-cn">Glou.</span>
 Tell me, sirrah, what’s my name?</div>

<div class="dverse1"><span class="sd-cn">Simp.</span>
 Alas, master, I know not.</div>

<div class="dverse1"><span class="sd-cn">Glou.</span>
 What’s his name?</div>

<div class="dverse1"><span class="lnum">120</span>
 <span class="sd-cn">Simp.</span>
  I know not.</div>

<div class="dverse1"><span class="sd-cn">Glou.</span>
 Nor his?</div>

<div class="dverse1"><span class="sd-cn">Simp.</span>
 No, indeed, master.</div>

<div class="dverse1"><span class="sd-cn">Glou.</span>
 What’s thine own name?</div>

<div class="dverse1"><a class="lnum pginternal" href="#lnote-bba124" id="lnum-bba124">♦</a>
 <span class="sd-cn">Simp.</span>
  Saunder Simpcox, an if it please you, master.</div>

<div class="dprose1"><a class="lnum pginternal" href="#lnote-bba125" id="lnum-bba125">125</a>
<span class="sd-cn">Glou.</span>
Then, Saunder, sit there, the lyingest knave in Christendom. If thou hadst been born blind, thou mightst <a class="lnum pginternal" href="#lnote-bba127" id="lnum-bba127">♦</a>
as well have known all our names as thus to name the several colours we do wear. Sight may distinguish of colours, <a class="lnum pginternal" href="#lnote-bba129" id="lnum-bba129">♦</a>
but suddenly to nominate them all, it is impossible. My
 <a class="lnum pginternal" href="#lnote-bba130" id="lnum-bba130">130</a>
lords, Saint Alban here hath done a miracle; and would
 <a class="lnum pginternal" href="#lnote-bba131" id="lnum-bba131">♦</a>
ye not think his cunning to be great, that could restore this <a class="lnum pginternal" href="#lnote-bba132" id="lnum-bba132">♦</a>
cripple to his legs again?</div>

<div class="dprose1"><span class="sd-cn">Simp.</span>
 O master, that you could!</div>

<div class="dprose1"><span class="lnum">135</span>
 <span class="sd-cn">Glou.</span>
My masters of Saint Albans, have you not beadles in your town, and things called whips?</div>

<div class="dprose1"><a class="lnum pginternal" href="#lnote-bba136" id="lnum-bba136">♦</a>
<span class="sd-cn">May.</span>
Yes, my lord, if it please your grace.</div>

<div class="dprose1"><span class="sd-cn">Glou.</span>
 Then send for one presently.</div>

<div class="dprose1"><a class="lnum pginternal" href="#lnote-bba138" id="lnum-bba138">♦</a>
 <span class="sd-cn">May.</span>
 Sirrah, go fetch the beadle hither straight.
 <span class="sd-proseend">[<i>Exit an Attendant.</i></span></div>

<div class="dprose1"><a class="lnum pginternal" href="#lnote-bba139" id="lnum-bba139">♦</a>
<span class="sd-cn">Glou.</span>
Now fetch me a stool hither by and by. Now, <span class="lnum">140</span>
sirrah, if you mean to save yourself from whipping, leap me over this stool and run away.</div>

<div class="dprose1"><span class="sd-cn">Simp.</span>
Alas, master, I am not able to stand alone: You go about to torture me in vain.</div>

<div class="sd-entry"><i>Enter a</i> Beadle <i>with whips</i>.</div>

<div class="dprose1"><span class="sd-cn">Glou.</span>
Well, sir, we must have you find your legs. <span class="lnum">145</span>
Sirrah beadle, whip him till he leap over that same stool.</div>

<div class="dprose1"><span class="sd-cn">Bead.</span>
I will, my lord. Come on, sirrah; off with your doublet quickly.</div>

<div class="dprose1"><span class="sd-cn">Simp.</span>
Alas, master, what shall I do? I am not able to stand. <span class="sd-proseend">[<i>After the Beadle hath hit him once, he leaps over the stool and runs away; and they follow and cry</i>, ‘A miracle!’</span></div>

<div class="dverse1"><a class="lnum pginternal" href="#lnote-bba150" id="lnum-bba150">150</a>
 <span class="sd-cn">King.</span>
O God, seest Thou this, and bearest so long?</div>

<div class="dverse1"><span class="sd-cn">Queen.</span>
 It made me laugh to see the villain run.</div>

<div class="dverse1"><a class="lnum pginternal" href="#lnote-bba152" id="lnum-bba152">♦</a>
 <span class="sd-cn">Glou.</span>
 Follow the knave; and take this drab away.</div>

<div class="dverse1"><a class="lnum pginternal" href="#lnote-bba153" id="lnum-bba153">♦</a>
 <span class="sd-cn">Wife.</span>
  Alas, sir, we did it for pure need.</div>

<div class="dprose1"><a class="lnum pginternal" href="#lnote-bba154" id="lnum-bba154">♦</a>
<span class="sd-cn">Glou.</span>
Let them be whipped through every market-town, <a class="lnum pginternal" href="#lnote-bba155" id="lnum-bba155">155</a>
till they come to Berwick, from whence they came. <span class="sd-proseend">[<i>Exeunt Wife, Beadle, Mayor, &amp;c.</i></span></div>

<div class="dverse1"><a class="lnum pginternal" href="#lnote-bba156" id="lnum-bba156">♦</a>
 <span class="sd-cn">Car.</span>
  Duke Humphrey has done a miracle to-day.</div>

<div class="dverse1"><span class="sd-cn">Suf.</span>
 True; made the lame to leap and fly away.</div>

<div class="dverse1"><span class="sd-cn">Glou.</span>
 But you have done more miracles than I;</div>
<div class="dverse"><a class="lnum pginternal" href="#lnote-bba159" id="lnum-bba159">♦</a>
 You made in a day, my lord, whole towns to fly.</div>

<div class="sd-entry"><i>Enter</i>
<span class="smcaps">B<span>UCKINGHAM</span>.</span></div>

<div class="dverse1"><a class="lnum pginternal" href="#lnote-bba160" id="lnum-bba160">160</a>
 <span class="sd-cn">King.</span>
  What tidings with our cousin Buckingham?</div>

<div class="dverse1"><span class="sd-cn">Buck.</span>
 Such as my heart doth tremble to unfold.</div>
<div class="dverse">A sort of naughty persons, lewdly bent,</div>
<div class="dverse">Under the countenance and confederacy</div>
<div class="dverse">Of Lady Eleanor, the protector’s wife,</div>
<div class="dverse"><span class="lnum">165</span> The ringleader and head of all this rout,</div>
<div class="dverse">Have practised dangerously against your state,</div>
<div class="dverse">Dealing with witches and with conjurers:</div>
<div class="dverse">Whom we have apprehended in the fact;</div>
<div class="dverse">Raising up wicked spirits from under ground,</div>
<div class="dverse"><span class="lnum">170</span> Demanding of King Henry’s life and death,</div>
<div class="dverse">And other of your highness’ privy-council;</div>
<div class="dverse">As more at large your grace shall understand.</div>

<div class="dverse1"><a class="lnum pginternal" href="#lnote-bba173" id="lnum-bba173">♦</a>
 <span class="sd-cn">Car.</span>
 <span class="sd-inline">[<i>Aside to Glou.</i>]</span> And so, my lord protector, by this means</div>
<div class="dverse">Your lady is forthcoming yet at London.</div>
<div class="dverse"><span class="lnum">175</span> This news, I think, hath turn’d your weapon’s edge;</div>
<div class="dverse">’Tis like, my lord, you will not keep your hour.</div>

<div class="dverse1"><span class="sd-cn">Glou.</span>
 Ambitious churchman, leave to afflict my heart:</div>
<div class="dverse">Sorrow and grief have vanquish’d all my powers;</div>
<div class="dverse"><a class="lnum pginternal" href="#lnote-bba179" id="lnum-bba179">♦</a>
 And, vanquish’d as I am, I yield to thee,</div>
<div class="dverse"><span class="lnum">180</span> Or to the meanest groom.</div>

<div class="dverse1"><span class="sd-cn">King.</span>
 O God, what mischiefs work the wicked ones,</div>
<div class="dverse"><a class="lnum pginternal" href="#lnote-bba182" id="lnum-bba182">♦</a>
 Heaping confusion on their own heads thereby!</div>

<div class="dverse1"><span class="sd-cn">Queen.</span>
 Gloucester, see here the tainture of thy nest,</div>
<div class="dverse">And look thyself be faultless, thou wert best.</div>

<div class="dverse1"><span class="lnum">185</span>
 <span class="sd-cn">Glou.</span>
  Madam, for myself, to heaven I do appeal,</div>
<div class="dverse"><a class="lnum pginternal" href="#lnote-bba186" id="lnum-bba186">♦</a>
 How I have loved my king and commonweal:</div>
<div class="dverse">And, for my wife, I know not how it stands;</div>
<div class="dverse">Sorry I am to hear what I have heard:</div>
<div class="dverse">Noble she is, but if she have forgot</div>
<div class="dverse"><span class="lnum">190</span> Honour and virtue and conversed with such</div>
<div class="dverse">As, like to pitch, defile nobility,</div>
<div class="dverse">I banish her my bed and company</div>
<div class="dverse">And give her as a prey to law and shame,</div>
<div class="dverse">That hath dishonour’d Gloucester’s honest name.</div>

<div class="dverse1"><span class="lnum">195</span>
 <span class="sd-cn">King.</span>
  Well, for this night we will repose us here:</div>
<div class="dverse">To-morrow toward London back again,</div>
<div class="dverse">To look into this business thoroughly</div>
<div class="dverse">And call these foul offenders to their answers</div>
<div class="dverse"><a class="lnum pginternal" href="#lnote-bba199" id="lnum-bba199">♦</a>
 And poise the cause in justice’ equal scales,</div>
<div class="dverse"><a class="lnum pginternal" href="#lnote-bba200" id="lnum-bba200">200</a>
 Whose beam stands sure, whose rightful cause prevails.
<span class="sd-verseend">[<i>Flourish. Exeunt.</i></span></div>

<div class="section">
<h4 class="h4main"><span class="dnavigate">bbb</span> <span class="smcaps">S<span>CENE</span></span> II. <i>London.</i> <i>The</i> <span class="smcaps">D<span>UKE</span></span> <span class="smmaj">OF</span>
<span class="smcaps">Y<span>ORK’S</span></span> <i>garden</i>.</h4>

<div class="sd-schg"><i>Enter</i> <span class="smcaps">Y<span>ORK</span>,</span> <span class="smcaps">S<span>ALISBURY</span>,</span> <i>and</i> <span class="smcaps">W<span>ARWICK</span>.</span></div></div>

<div class="dverse1"><span class="sd-cn">York.</span>
 Now, my good Lords of Salisbury and Warwick,</div>
<div class="dverse">Our simple supper ended, give me leave</div>
<div class="dverse">In this close walk to satisfy myself,</div>
<div class="dverse">In craving your opinion of my title,</div>
<div class="dverse"><span class="lnum">5</span> Which is infallible, to England’s crown.</div>

<div class="dverse1"><a class="lnum pginternal" href="#lnote-bbb006" id="lnum-bbb006">♦</a>
 <span class="sd-cn">Sal.</span>
  My lord, I long to hear it at full.</div>

<div class="dverse1"><a class="lnum pginternal" href="#lnote-bbb007" id="lnum-bbb007">♦</a>
 <span class="sd-cn">War.</span>
  Sweet York, begin: and if thy claim be good,</div>
<div class="dverse">The Nevils are thy subjects to command.</div>

<div class="dverse1"><span class="sd-cn">York.</span>
 Then thus:</div>
<div class="dverse"><span class="lnum">10</span> Edward the Third, my lords, had seven sons:</div>
<div class="dverse">The first, Edward the Black Prince, Prince of Wales;</div>
<div class="dverse">The second, William of Hatfield, and the third,</div>
<div class="dverse">Lionel Duke of Clarence; next to whom</div>
<div class="dverse">Was John of Gaunt, the Duke of Lancaster;</div>
<div class="dverse"><a class="lnum pginternal" href="#lnote-bbb015" id="lnum-bbb015">15</a>
 The fifth was Edmund Langley, Duke of York;</div>
<div class="dverse"><a class="lnum pginternal" href="#lnote-bbb016" id="lnum-bbb016">♦</a>
 The sixth was Thomas of Woodstock, Duke of Gloucester;</div>
<div class="dverse">William of Windsor was the seventh and last.</div>
<div class="dverse">Edward the Black Prince died before his father</div>
<div class="dverse">And left behind him Richard, his only son,</div>
<div class="dverse"><a class="lnum pginternal" href="#lnote-bbb020" id="lnum-bbb020">20</a>
 Who after Edward the Third’s death reign’d as king;</div>
<div class="dverse">Till Henry Bolingbroke, Duke of Lancaster,</div>
<div class="dverse">The eldest son and heir of John of Gaunt,</div>
<div class="dverse">Crown’d by the name of Henry the Fourth,</div>
<div class="dverse">Seized on the realm, deposed the rightful king,</div>
<div class="dverse"><span class="lnum">25</span> Sent his poor queen to France, from whence she came,</div>
<div class="dverse"><a class="lnum pginternal" href="#lnote-bbb026" id="lnum-bbb026">♦</a>
 And him to Pomfret; where, as all you know,</div>
<div class="dverse"><a class="lnum pginternal" href="#lnote-bbb027" id="lnum-bbb027">♦</a>
 Harmless Richard was murder’d traitorously.</div>

<div class="dverse1"><a class="lnum pginternal" href="#lnote-bbb028" id="lnum-bbb028">♦</a>
 <span class="sd-cn">War.</span>
  Father, the duke hath told the truth;</div>
<div class="dverse">Thus got the house of Lancaster the crown.</div>

<div class="dverse1"><span class="lnum">30</span>
 <span class="sd-cn">York.</span>
  Which now they hold by force and not by right;</div>
<div class="dverse">For Richard, the first son’s heir, being dead,</div>
<div class="dverse">The issue of the next son should have reign’d.</div>

<div class="dverse1"><span class="sd-cn">Sal.</span>
 But William of Hatfield died without an heir.</div>

<div class="dverse1"><a class="lnum pginternal" href="#lnote-bbb034" id="lnum-bbb034">♦</a>
 <span class="sd-cn">York.</span>
  The third son, Duke of Clarence, from whose line</div>
<div class="dverse"><a class="lnum pginternal" href="#lnote-bbb035" id="lnum-bbb035">35</a>
 I claim the crown, had issue, Philippe, a daughter,</div>
<div class="dverse">Who married Edmund Mortimer, Earl of March:</div>
<div class="dverse">Edmund had issue, Roger Earl of March;</div>
<div class="dverse">Roger had issue, Edmund, Anne and Eleanor.</div>

<div class="dverse1"><span class="sd-cn">Sal.</span>
 This Edmund, in the reign of Bolingbroke,</div>
<div class="dverse"><span class="lnum">40</span> As I have read, laid claim unto the crown;</div>
<div class="dverse">And, but for Owen Glendower, had been king,</div>
<div class="dverse">Who kept him in captivity till he died.</div>
<div class="dverse">But to the rest.</div>

<div class="dverse1"><a class="lnum pginternal" href="#lnote-bbb043" id="lnum-bbb043">♦</a>
 <span class="sd-cn">York.</span>
 <span class="i05"> </span> His eldest sister, Anne,</div>
<div class="dverse">My mother, being heir unto the crown,</div>
<div class="dverse"><span class="lnum" id="lnum-bbb045">45</span>
 Married Richard Earl of Cambridge; who was son</div>
<div class="dverse">To Edmund Langley, Edward the Third’s fifth son.</div>
<div class="dverse">By her I claim the kingdom: she was heir</div>
<div class="dverse">To Roger Earl of March, who was the son</div>
<div class="dverse">Of Edmund Mortimer, who married Philippe,</div>
<div class="dverse"><span class="lnum">50</span> Sole daughter unto Lionel Duke of Clarence:</div>
<div class="dverse"><a class="lnum pginternal" href="#lnote-bbb051" id="lnum-bbb051">♦</a>
 So, if the issue of the elder son</div>
<div class="dverse">Succeed before the younger, I am king.</div>

<div class="dverse1"><a class="lnum pginternal" href="#lnote-bbb053" id="lnum-bbb053">♦</a>
 <span class="sd-cn">War.</span>
  What plain proceeding is more plain than this?</div>
<div class="dverse">Henry doth claim the crown from John of Gaunt,</div>
<div class="dverse"><a class="lnum pginternal" href="#lnote-bbb055" id="lnum-bbb055">55</a>
 The fourth son; York claims it from the third.</div>
<div class="dverse"><a class="lnum pginternal" href="#lnote-bbb056" id="lnum-bbb056">♦</a>
 Till Lionel’s issue fails, his should not reign:</div>
<div class="dverse"><a class="lnum pginternal" href="#lnote-bbb057" id="lnum-bbb057">♦</a>
 It fails not yet, but flourishes in thee</div>
<div class="dverse">And in thy sons, fair slips of such a stock.</div>
<div class="dverse">Then, father Salisbury, kneel we together;</div>
<div class="dverse"><span class="lnum">60</span> And in this private plot be we the first</div>
<div class="dverse">That shall salute our rightful sovereign</div>
<div class="dverse">With honour of his birthright to the crown.</div>

<div class="dverse1"><span class="sd-cn">Both.</span>
 Long live our sovereign Richard, England’s king!</div>

<div class="dverse1"><a class="lnum pginternal" href="#lnote-bbb064" id="lnum-bbb064">♦</a>
 <span class="sd-cn">York.</span>
  We thank you, lords. But I am not your king</div>
<div class="dverse"><span class="lnum">65</span> Till I be crown’d and that my sword be stain’d</div>
<div class="dverse">With heart-blood of the house of Lancaster;</div>
<div class="dverse">And that’s not suddenly to be perform’d,</div>
<div class="dverse">But with advice and silent secrecy.</div>
<div class="dverse">Do you as I do in these dangerous days:</div>
<div class="dverse"><span class="lnum">70</span> Wink at the Duke of Suffolk’s insolence,</div>
<div class="dverse">At Beaufort’s pride, at Somerset’s ambition,</div>
<div class="dverse">At Buckingham and all the crew of them,</div>
<div class="dverse">Till they have snared the shepherd of the flock,</div>
<div class="dverse">That virtuous prince, the good Duke Humphrey:</div>
<div class="dverse"><span class="lnum">75</span> ’Tis that they seek, and they in seeking that</div>
<div class="dverse">Shall find their deaths, if York can prophesy.</div>

<div class="dverse1"><a class="lnum pginternal" href="#lnote-bbb077" id="lnum-bbb077">♦</a>
 <span class="sd-cn">Sal.</span>
  My lord, break we off; we know your mind at full.</div>

<div class="dverse1"><span class="sd-cn">War.</span>
 My heart assures me that the Earl of Warwick</div>
<div class="dverse">Shall one day make the Duke of York a king.</div>

<div class="dverse1"><span class="lnum">80</span>
 <span class="sd-cn">York.</span>
  And, Nevil, this I do assure myself:</div>
<div class="dverse">Richard shall live to make the Earl of Warwick</div>
<div class="dverse">The greatest man in England but the king. <span class="sd-verseend">[<i>Exeunt.</i></span></div>

<div class="section">
<h4 class="h4main"><span class="dnavigate">bbc</span> <span class="smcaps">S<span>CENE</span></span> III. <i>A hall of
justice</i>.</h4>

<div class="sd-schg"><i>Sound trumpets. Enter the King,
the</i> <span class="smcaps">Q<span>UEEN</span>,</span>
<span class="smcaps">G<span>LOUCESTER</span>,</span>
<span class="smcaps">Y<span>ORK</span>,</span> <span class="smcaps">S<span>UFFOLK</span>,</span> <i>and</i>
<span class="smcaps">S<span>ALISBURY</span>;</span>
<i>the</i> <span class="smcaps">D<span>UCHESS</span></span>
<span class="smmaj">OF</span> <span class="smcaps">G<span>LOUCESTER</span>,</span> <span class="smcaps">M<span>ARGERY</span></span> <span class="smcaps">J<span>OURDAIN</span>,</span> <span class="smcaps">S<span>OUTHWELL</span>,</span> <span class="smcaps">H<span>UME</span>,</span> <i>and</i> <span class="smcaps">B<span>OLINGBROKE</span>,</span> <i>under guard</i>.</div></div>

<div class="dverse1"><a class="lnum pginternal" href="#lnote-bbc001" id="lnum-bbc001">♦</a>
 <span class="sd-cn">King.</span>
  Stand forth, Dame Eleanor Cobham, Gloucester’s wife:</div>
<div class="dverse">In sight of God and us, your guilt is great:</div>
<div class="dverse"><a class="lnum pginternal" href="#lnote-bbc003" id="lnum-bbc003">♦</a>
 Receive the sentence of the law for sins</div>
<div class="dverse">Such as by God’s book are adjudged to death.</div>
<div class="dverse"><span class="lnum">5</span> You four, from hence to prison back again;</div>
<div class="dverse">From thence unto the place of execution:</div>
<div class="dverse">The witch in Smithfield shall be burn’d to ashes,</div>
<div class="dverse">And you three shall be strangled on the gallows.</div>
<div class="dverse">You, madam, for you are more nobly born,</div>
<div class="dverse"><span class="lnum">10</span> Despoiled of your honour in your life,</div>
<div class="dverse">Shall, after three days’ open penance done,</div>
<div class="dverse">Live in your country here in banishment,</div>
<div class="dverse">With Sir John Stanley, in the Isle of Man.</div>

<div class="dverse1"><a class="lnum pginternal" href="#lnote-bbc014" id="lnum-bbc014">♦</a>
 <span class="sd-cn">Duch.</span>
  Welcome is banishment; welcome were my death.</div>

<div class="dverse1"><span class="lnum">15</span>
 <span class="sd-cn">Glou.</span>
  Eleanor, the law, thou see’st, hath judged thee:</div>
<div class="dverse"><a class="lnum pginternal" href="#lnote-bbc016" id="lnum-bbc016">♦</a>
 I cannot justify whom the law condemns.
<span class="sd-verseend">[<i>Exeunt Duchess and other prisoners, guarded.</i></span></div>
<div class="dverse">Mine eyes are full of tears, my heart of grief.</div>
<div class="dverse">Ah, Humphrey, this dishonour in thine age</div>
<div class="dverse">Will bring thy head with sorrow to the ground!</div>
<div class="dverse"><a class="lnum pginternal" href="#lnote-bbc020" id="lnum-bbc020">20</a>
 I beseech your majesty, give me leave to go;</div>
<div class="dverse"><a class="lnum pginternal" href="#lnote-bbc021" id="lnum-bbc021">♦</a>
 Sorrow would solace and mine age would ease.</div>

<div class="dverse1"><a class="lnum pginternal" href="#lnote-bbc022" id="lnum-bbc022">♦</a>
 <span class="sd-cn">King.</span>
  Stay, Humphrey Duke of Gloucester: ere thou go,</div>
<div class="dverse">Give up thy staff: Henry will to himself</div>
<div class="dverse">Protector be; and God shall be my hope,</div>
<div class="dverse"><span class="lnum">25</span> My stay, my guide and lanthorn to my feet:</div>
<div class="dverse">And go in peace, Humphrey, no less beloved</div>
<div class="dverse">Than when thou wert protector to thy king.</div>

<div class="dverse1"><span class="sd-cn">Queen.</span>
 I see no reason why a king of years</div>
<div class="dverse"><a class="lnum pginternal" href="#lnote-bbc029" id="lnum-bbc029">♦</a>
 Should be to be protected like a child.</div>
<div class="dverse"><a class="lnum pginternal" href="#lnote-bbc030" id="lnum-bbc030">30</a>
 God and King Henry govern England’s realm.</div>
<div class="dverse"><a class="lnum pginternal" href="#lnote-bbc031" id="lnum-bbc031">♦</a>
 Give up your staff, sir, and the king his realm.</div>

<div class="dverse1"><a class="lnum pginternal" href="#lnote-bbc032" id="lnum-bbc032">♦</a>
 <span class="sd-cn">Glou.</span>
  My staff? here, noble Henry, is my staff:</div>
<div class="dverse">As willingly do I the same resign</div>
<div class="dverse">As e’er thy father Henry made it mine;</div>
<div class="dverse"><a class="lnum pginternal" href="#lnote-bbc035" id="lnum-bbc035">35</a>
 And even as willingly at thy feet I leave it</div>
<div class="dverse">As others would ambitiously receive it.</div>
<div class="dverse">Farewell, good king: when I am dead and gone,</div>
<div class="dverse">May honourable peace attend thy throne! <span class="sd-verseend">[<i>Exit.</i></span></div>

<div class="dverse1"><span class="sd-cn">Queen.</span>
 Why, now is Henry king, and Margaret queen;</div>
<div class="dverse"><span class="lnum">40</span> And Humphrey Duke of Gloucester scarce himself,</div>
<div class="dverse">That bears so shrewd a maim; two pulls at once;</div>
<div class="dverse"><a class="lnum pginternal" href="#lnote-bbc042" id="lnum-bbc042">♦</a>
 His lady banish’d, and a limb lopp’d off.</div>
<div class="dverse">This staff of honour raught, there let it stand</div>
<div class="dverse"><a class="lnum pginternal" href="#lnote-bbc044" id="lnum-bbc044">♦</a>
 Where it best fits to be, in Henry’s hand.</div>
<div class="dverse"><i>Suf.</i><span class="lnum">45</span>
 Thus droops this lofty pine and hangs his sprays;</div>
<div class="dverse"><a class="lnum pginternal" href="#lnote-bbc046" id="lnum-bbc046">♦</a>
 Thus Eleanor’s pride dies in her youngest days.</div>

<div class="dverse1"><span class="sd-cn">York.</span>
 Lords, let him go. Please it your majesty,</div>
<div class="dverse">This is the day appointed for the combat;</div>
<div class="dverse">And ready are the appellant and defendant,</div>
<div class="dverse"><a class="lnum pginternal" href="#lnote-bbc050" id="lnum-bbc050">50</a>
 The armourer and his man, to enter the lists,</div>
<div class="dverse">So please your highness to behold the fight.</div>

<div class="dverse1"><span class="sd-cn">Queen.</span>
 Ay, good my lord; for purposely therefore</div>
<div class="dverse">Left I the court, to see this quarrel tried.</div>

<div class="dverse1"><a class="lnum pginternal" href="#lnote-bbc054" id="lnum-bbc054">♦</a>
 <span class="sd-cn">King.</span>
  O’ God’s name, see the lists and all things fit:</div>
<div class="dverse"><a class="lnum pginternal" href="#lnote-bbc055" id="lnum-bbc055">55</a>
 Here let them end it; and God defend the right!</div>

<div class="dverse1"><span class="sd-cn">York.</span>
 I never saw a fellow worse bested,</div>
<div class="dverse">Or more afraid to fight, than is the appellant,</div>
<div class="dverse"><a class="lnum pginternal" href="#lnote-bbc058" id="lnum-bbc058">♦</a>
 The servant of this armourer, my lords.</div>

<div class="sd-entry"><i>Enter at one door</i>, <span class="smcaps">H<span>ORNER</span>,</span> <i>the Armourer, and his</i>
Neighbours, <i>drinking to him so much that he is drunk; and he enters with a drum before him and his staff with a sand-bag fastened to it; and at the other door</i> <span class="smcaps">P<span>ETER</span>,</span>
<i>his man, with a drum and sand-bag, and</i> ’Prentices <i>drinking to him</i>.</div>

<div class="dprose1"><a class="lnum pginternal" href="#lnote-bbc059" id="lnum-bbc059">♦</a>
 <span class="sd-cn">First Neigh.</span>
Here, neighbour Horner, I drink to you <span class="lnum">60</span>
in a cup of sack: and fear not, neighbour, you shall do well enough.</div>

<div class="dprose1"><span class="sd-cn">Sec. Neigh.</span>
And here, neighbour, here’s a cup of charneco.</div>

<div class="dprose1"><span class="sd-cn">Third Neigh.</span>
And here’s a pot of good double beer, <span class="lnum">65</span> neighbour: drink, and fear not your man.</div>

<div class="dprose1"><span class="sd-cn">Hor.</span>
Let it come, i’ faith, and I’ll pledge you all; and a fig for Peter!</div>

<div class="dprose1"><span class="sd-cn">First ’Pren.</span>
Here, Peter, I drink to thee: and be not afraid.</div>

<div class="dprose1"><span class="lnum">70</span>
 <span class="sd-cn">Sec. ’Pren.</span>
Be merry, Peter, and fear not thy master: <a class="lnum pginternal" href="#lnote-bbc071" id="lnum-bbc071">♦</a>
fight for credit of the ’prentices.</div>

<div class="dprose1"><span class="sd-cn">Peter.</span>
I thank you all: drink, and pray for me, I pray you; for I think I have taken my last draught in this world. <a class="lnum pginternal" href="#lnote-bbc074" id="lnum-bbc074">♦</a>
Here, Robin, an if I die, I give thee my apron: and, Will, <span class="lnum">75</span>
thou shalt have my hammer: and here, Tom, take all the money that I have. O Lord bless me! I pray God! for I am never able to deal with my master, he hath learnt so <a class="lnum pginternal" href="#lnote-bbc078" id="lnum-bbc078">♦</a>
much fence already.</div>

<div class="dprose1"><a class="lnum pginternal" href="#lnote-bbc079" id="lnum-bbc079">♦</a>
 <span class="sd-cn">Sal.</span>
Come, leave your drinking, and fall to blows. <span class="lnum">80</span> Sirrah, what’s thy name?</div>

<div class="dprose1"><span class="sd-cn">Peter.</span>
 Peter, forsooth.</div>

<div class="dprose1"><span class="sd-cn">Sal.</span>
 Peter! what more?</div>

<div class="dprose1"><span class="sd-cn">Peter.</span>
 Thump.</div>

<div class="dprose1"><span class="sd-cn">Sal.</span>
 Thump! then see thou thump thy master well.</div>

<div class="dprose1"><span class="lnum">85</span>
 <span class="sd-cn">Hor.</span>
Masters, I am come hither, as it were, upon my man’s instigation, to prove him a knave and myself an honest <a class="lnum pginternal" href="#lnote-bbc087" id="lnum-bbc087">♦</a>
man: and touching the Duke of York, I will take my death, I never meant him any ill, nor the king, nor the queen: and <a class="lnum pginternal" href="#lnote-bbc089" id="lnum-bbc089">♦</a>
therefore, Peter, have at thee with a downright blow!</div>

<div class="dprose1"><span class="lnum">90</span>
 <span class="sd-cn">York.</span>
Dispatch: this knave’s tongue begins to double. <a class="lnum pginternal" href="#lnote-bbc091" id="lnum-bbc091">♦</a>
Sound, trumpets, alarum to the combatants! <span class="sd-proseend">[<i>Alarum. They fight, and Peter strikes him down.</i></span></div>

<div class="dprose1"><a class="lnum pginternal" href="#lnote-bbc092" id="lnum-bbc092">♦</a>
 <span class="sd-cn">Hor.</span>
Hold, Peter, hold! I confess, I confess treason. <span class="sd-proseend">[<i>Dies.</i></span></div>

<div class="dprose1"><span class="sd-cn">York.</span>
Take away his weapon. Fellow, thank God, and the good wine in thy master’s way.</div>

<div class="dprose1"><a class="lnum pginternal" href="#lnote-bbc095" id="lnum-bbc095">95</a>
 <span class="sd-cn">Peter.</span>
O God, have I overcome mine enemy in this <a class="lnum pginternal" href="#lnote-bbc096" id="lnum-bbc096">♦</a>
presence? O Peter, thou hast prevailed in right! </div>

<div class="dverse1"><a class="lnum pginternal" href="#lnote-bbc097" id="lnum-bbc097">♦</a>
 <span class="sd-cn">King.</span>
  Go, take hence that traitor from our sight;</div>
<div class="dverse">For by his death we do perceive his guilt:</div>
<div class="dverse">And God in justice hath reveal’d to us</div>
<div class="dverse"><span class="lnum">100</span> The truth and innocence of this poor fellow,</div>
<div class="dverse"><a class="lnum pginternal" href="#lnote-bbc101" id="lnum-bbc101">♦</a>
 Which he had thought to have murder’d wrongfully.</div>
<div class="dverse"><a class="lnum pginternal" href="#lnote-bbc102" id="lnum-bbc102">♦</a> Come, fellow, follow us for thy reward. <span class="sd-verseend">[<i>Sound a flourish. Exeunt.</i></span></div>

<div class="section">
<h4 class="h4main"><span class="dnavigate">bbd</span> <span class="smcaps">S<span>CENE</span></span> IV. <i>A street</i>.</h4>

<div class="sd-schg"><i>Enter</i> <span class="smcaps">G<span>LOUCESTER</span></span> <i>and his Serving-men, in
mourning cloaks</i>.</div></div>

<div class="dverse1"><span class="sd-cn">Glou.</span>
 Thus sometimes hath the brightest day a cloud;</div>
<div class="dverse">And after summer evermore succeeds</div>
<div class="dverse"><a class="lnum pginternal" href="#lnote-bbd003" id="lnum-bbd003">♦</a>
 Barren winter, with his wrathful nipping cold:</div>
<div class="dverse"><a class="lnum pginternal" href="#lnote-bbd004" id="lnum-bbd004">♦</a>
 So cares and joys abound, as seasons fleet.</div>
<div class="dverse">Sirs, what’s o’clock?</div>

<div class="dverse1"><a class="lnum pginternal" href="#lnote-bbd005" id="lnum-bbd005">5</a>
 <span class="sd-cn">Serv.</span>
 <span class="i09"> </span>
 Ten, my lord.</div>

<div class="dverse1"><span class="sd-cn">Glou.</span>
 Ten is the hour that was appointed me</div>
<div class="dverse">To watch the coming of my punish’d duchess:</div>
<div class="dverse">Uneath may she endure the flinty streets,</div>
<div class="dverse">To tread them with her tender-feeling feet.</div>
<div class="dverse"><span class="lnum">10</span> Sweet Nell, ill can thy noble mind abrook</div>
<div class="dverse"><a class="lnum pginternal" href="#lnote-bbd011" id="lnum-bbd011">♦</a>
 The abject people gazing on thy face,</div>
<div class="dverse"><a class="lnum pginternal" href="#lnote-bbd012" id="lnum-bbd012">♦</a>
 With envious looks, laughing at thy shame,</div>
<div class="dverse">That erst did follow thy proud chariot-wheels</div>
<div class="dverse">When thou didst ride in triumph through the streets.</div>
<div class="dverse"><span class="lnum">15</span> But, soft! I think she comes; and I’ll prepare</div>
<div class="dverse"><a class="lnum pginternal" href="#lnote-bbd016" id="lnum-bbd016">♦</a>
 My tear-stain’d eyes to see her miseries.</div>

<div class="sd-entry"><i>Enter the</i> <span class="smcaps">D<span>UCHESS</span></span>
<span class="smmaj">OF</span> <span class="smcaps">G<span>LOUCESTER</span></span> <i>in a white sheet, and a taper burning in her hand; with</i> <span class="smcaps">S<span>IR</span></span>
<span class="smcaps">J<span>OHN</span></span> <span class="smcaps">S<span>TANLEY</span>,</span> <i>the</i> Sheriff, <i>and</i>
Officers.</div>

<div class="dverse1"><span class="sd-cn">Serv.</span>
 So please your grace, we’ll take her from the sheriff.</div>

<div class="dverse1"><span class="sd-cn">Glou.</span>
 No, stir not, for your lives; let her pass by.</div>

<div class="dverse1"><span class="sd-cn">Duch.</span>
 Come you, my lord, to see my open shame?</div>
<div class="dverse"><span class="lnum">20</span> Now thou dost penance too. Look how they gaze!</div>
<div class="dverse">See how the giddy multitude do point,</div>
<div class="dverse">And nod their heads, and throw their eyes on thee!</div>
<div class="dverse">Ah, Gloucester, hide thee from their hateful looks,</div>
<div class="dverse">And, in thy closet pent up, rue my shame,</div>
<div class="dverse"><a class="lnum pginternal" href="#lnote-bbd025" id="lnum-bbd025">25</a>
 And ban thine enemies, both mine and thine!</div>

<div class="dverse1"><span class="sd-cn">Glou.</span>
 Be patient, gentle Nell; forget this grief.</div>

<div class="dverse1"><span class="sd-cn">Duch.</span>
 Ah, Gloucester, teach me to forget myself!</div>
<div class="dverse">For whilst I think I am thy married wife</div>
<div class="dverse">And thou a prince, protector of this land,</div>
<div class="dverse"><span class="lnum">30</span> Methinks I should not thus be led along,</div>
<div class="dverse">Mail’d up in shame, with papers on my back,</div>
<div class="dverse">And follow’d with a rabble that rejoice</div>
<div class="dverse"><a class="lnum pginternal" href="#lnote-bbd033" id="lnum-bbd033">♦</a>
 To see my tears and hear my deep-fet groans.</div>
<div class="dverse">The ruthless flint doth cut my tender feet,</div>
<div class="dverse"><span class="lnum">35</span> And when I start, the envious people laugh</div>
<div class="dverse">And bid me be advised how I tread.</div>
<div class="dverse">Ah, Humphrey, can I bear this shameful yoke?</div>
<div class="dverse">Trow’st thou that e’er I’ll look upon the world,</div>
<div class="dverse"><a class="lnum pginternal" href="#lnote-bbd039" id="lnum-bbd039">♦</a>
 Or count them happy that enjoy the sun?</div>
<div class="dverse"><span class="lnum">40</span> No; dark shall be my light and night my day;</div>
<div class="dverse">To think upon my pomp shall be my hell.</div>
<div class="dverse">Sometime I’ll say, I am Duke Humphrey’s wife,</div>
<div class="dverse">And he a prince and ruler of the land:</div>
<div class="dverse">Yet so he ruled and such a prince he was</div>
<div class="dverse"><a class="lnum pginternal" href="#lnote-bbd045" id="lnum-bbd045">45</a>
 As he stood by whilst I, his forlorn duchess,</div>
<div class="dverse">Was made a wonder and a pointing-stock</div>
<div class="dverse">To every idle rascal follower.</div>
<div class="dverse">But be thou mild and blush not at my shame,</div>
<div class="dverse">Nor stir at nothing till the axe of death</div>
<div class="dverse"><span class="lnum">50</span> Hang over thee, as, sure, it shortly will;</div>
<div class="dverse">For Suffolk—he that can do all in all</div>
<div class="dverse">With her that hateth thee and hates us all—</div>
<div class="dverse">And York and impious Beaufort, that false priest,</div>
<div class="dverse"><a class="lnum pginternal" href="#lnote-bbd054" id="lnum-bbd054">♦</a>
 Have all limed bushes to betray thy wings,</div>
<div class="dverse"><span class="lnum">55</span> And, fly thou how thou canst, they’ll tangle thee:</div>
<div class="dverse">But fear not thou, until thy foot be snared,</div>
<div class="dverse">Nor never seek prevention of thy foes.</div>

<div class="dverse1"><span class="sd-cn">Glou.</span>
 Ah, Nell, forbear! thou aimest all awry;</div>
<div class="dverse">I must offend before I be attainted;</div>
<div class="dverse"><span class="lnum">60</span> And had I twenty times so many foes,</div>
<div class="dverse">And each of them had twenty times their power,</div>
<div class="dverse">All these could not procure me any scathe,</div>
<div class="dverse">So long as I am loyal, true and crimeless.</div>
<div class="dverse">Wouldst have me rescue thee from this reproach?</div>
<div class="dverse"><span class="lnum">65</span> Why, yet thy scandal were not wiped away,</div>
<div class="dverse">But I in danger for the breach of law.</div>
<div class="dverse">Thy greatest help is quiet, gentle Nell:</div>
<div class="dverse">I pray thee, sort thy heart to patience;</div>
<div class="dverse"><a class="lnum pginternal" href="#lnote-bbd069" id="lnum-bbd069">♦</a>
 These few days’ wonder will be quickly worn.</div>

<div class="sd-entry"><i>Enter a</i> Herald.</div>

<div class="dverse1"><a class="lnum pginternal" href="#lnote-bbd070" id="lnum-bbd070">70</a>
 <span class="sd-cn">Her.</span>
  I summon your grace to his majesty’s parliament,</div>
<div class="dverse">Holden at Bury the first of this next month.</div>

<div class="dverse1"><span class="sd-cn">Glou.</span>
 And my consent ne’er ask’d herein before!</div>
<div class="dverse"><a class="lnum pginternal" href="#lnote-bbd073" id="lnum-bbd073">♦</a>
 This is close dealing. Well, I will be there.
 <span class="sd-verseend">[<i>Exit Herald.</i></span></div>
<div class="dverse">My Nell, I take my leave: and, master sheriff,</div>
<div class="dverse"><a class="lnum pginternal" href="#lnote-bbd075" id="lnum-bbd075">75</a>
 Let not her penance exceed the king’s commission.</div>

<div class="dverse1"><a class="lnum pginternal" href="#lnote-bbd076" id="lnum-bbd076">♦</a>
 <span class="sd-cn">Sher.</span>
  An’t please your grace, here my commission stays,</div>
<div class="dverse">And Sir John Stanley is appointed now</div>
<div class="dverse">To take her with him to the Isle of Man.</div>

<div class="dverse1"><a class="lnum pginternal" href="#lnote-bbd079" id="lnum-bbd079">♦</a>
 <span class="sd-cn">Glou.</span>
  Must you, Sir John, protect my lady here?</div>

<div class="dverse1"><span class="lnum">80</span>
 <span class="sd-cn">Stan.</span>
  So am I given in charge, may’t please your grace.</div>

<div class="dverse1"><span class="sd-cn">Glou.</span>
 Entreat her not the worse in that I pray</div>
<div class="dverse">You use her well: the world may laugh again;</div>
<div class="dverse"><a class="lnum pginternal" href="#lnote-bbd083" id="lnum-bbd083">♦</a>
 And I may live to do you kindness if</div>
<div class="dverse">You do it her: and so, Sir John, farewell!</div>

<div class="dverse1"><span class="lnum">85</span>
 <span class="sd-cn">Duch.</span>
  What, gone, my lord, and bid me not farewell!</div>

<div class="dverse1"><a class="lnum pginternal" href="#lnote-bbd086" id="lnum-bbd086">♦</a>
 <span class="sd-cn">Glou.</span>
 Witness my tears, I cannot stay to speak.
 <span class="sd-verseend">[<i>Exeunt Gloucester and Serving-men.</i></span></div>

<div class="dverse1"><a class="lnum pginternal" href="#lnote-bbd087" id="lnum-bbd087">♦</a>
 <span class="sd-cn">Duch.</span>
  Art thou gone too? all comfort go with thee!</div>
<div class="dverse">For none abides with me: my joy is death,—</div>
<div class="dverse"><a class="lnum pginternal" href="#lnote-bbd089" id="lnum-bbd089">♦</a>
 Death, at whose name I oft have been afear’d,</div>
<div class="dverse"><span class="lnum">90</span> Because I wish’d this world’s eternity.</div>
<div class="dverse">Stanley, I prithee, go, and take me hence;</div>
<div class="dverse">I care not whither, for I beg no favour,</div>
<div class="dverse">Only convey me where thou art commanded.</div>

<div class="dverse1"><span class="sd-cn">Stan.</span>
 Why, madam, that is to the Isle of Man;</div>
<div class="dverse"><span class="lnum">95</span> There to be used according to your state.</div>

<div class="dverse1"><span class="sd-cn">Duch.</span>
 That’s bad enough, for I am but reproach:</div>
<div class="dverse">And shall I then be used reproachfully?</div>

<div class="dverse1"><a class="lnum pginternal" href="#lnote-bbd098" id="lnum-bbd098">♦</a>
 <span class="sd-cn">Stan.</span>
  Like to a duchess, and Duke Humphrey’s lady;</div>
<div class="dverse">According to that state you shall be used.</div>

<div class="dverse1"><span class="lnum">100</span>
 <span class="sd-cn">Duch.</span>
  Sheriff, farewell, and better than I fare,</div>
<div class="dverse">Although thou hast been conduct of my shame.</div>

<div class="dverse1"><span class="sd-cn">Sher.</span>
 It is my office; and, madam, pardon me.</div>

<div class="dverse1"><span class="sd-cn">Duch.</span>
 Ay, ay, farewell; thy office is discharged.</div>
<div class="dverse">Come, Stanley, shall we go?</div>

<div class="dverse1"><a class="lnum pginternal" href="#lnote-bbd105" id="lnum-bbd105">105</a>
 <span class="sd-cn">Stan.</span>
  Madam, your penance done, throw off this sheet,</div>
<div class="dverse"><a class="lnum pginternal" href="#lnote-bbd106" id="lnum-bbd106">♦</a>
 And go we to attire you for our journey.</div>

<div class="dverse1"><span class="sd-cn">Duch.</span>
 My shame will not be shifted with my sheet:</div>
<div class="dverse">No, it will hang upon my richest robes</div>
<div class="dverse">And show itself, attire me how I can.</div>
<div class="dverse"><span class="lnum">110</span>
 Go, lead the way; I long to see my prison.
 <span class="sd-verseend">[<i>Exeunt.</i></span></div>

<div class="section">
<h3 class="h3main">ACT III.</h3>

<h4 class="h4main"><span class="dnavigate">bca</span>
<span class="smcaps">S<span>CENE</span></span> I. <i>The Abbey at
Bury St Edmund’s</i>.</h4>

<div class="sd-schg"><i>Sound a Sennet. Enter</i>
<span class="smcaps">K<span>ING</span>,</span> <span class="smcaps">Q<span>UEEN</span>,</span> <span class="smcaps">C<span>ARDINAL</span></span> <span class="smcaps">B<span>EAUFORT</span>,</span> <span class="smcaps">S<span>UFFOLK</span>,</span> <span class="smcaps">Y<span>ORK</span>,</span> <span class="smcaps">B<span>UCKINGHAM</span>,</span> <span class="smcaps">S<span>ALISBURY</span></span> <i>and</i> <span class="smcaps">W<span>ARWICK</span></span> <i>to the Parliament</i>.</div></div>

<div class="dverse1"><a class="lnum pginternal" href="#lnote-bca001" id="lnum-bca001">♦</a>
 <span class="sd-cn">King.</span>
  I muse my Lord of Gloucester is not come:</div>
<div class="dverse">’Tis not his wont to be the hindmost man,</div>
<div class="dverse">Whate’er occasion keeps him from us now:</div>

<div class="dverse1"><a class="lnum pginternal" href="#lnote-bca004" id="lnum-bca004">♦</a>
 <span class="sd-cn">Queen.</span>
  Can you not see? or will ye not observe</div>
<div class="dverse"><span class="lnum">5</span> The strangeness of his alter’d countenance?</div>
<div class="dverse">With what a majesty he bears himself,</div>
<div class="dverse">How insolent of late he is become,</div>
<div class="dverse"><a class="lnum pginternal" href="#lnote-bca008" id="lnum-bca008">♦</a>
 How proud, how peremptory, and unlike himself?</div>
<div class="dverse">We know the time since he was mild and affable,</div>
<div class="dverse"><a class="lnum pginternal" href="#lnote-bca010" id="lnum-bca010">10</a>
 And if we did but glance a far-off look,</div>
<div class="dverse">Immediately he was upon his knee,</div>
<div class="dverse">That all the court admired him for submission:</div>
<div class="dverse">But meet him now, and, be it in the morn,</div>
<div class="dverse">When every one will give the time of day,</div>
<div class="dverse"><span class="lnum">15</span> He knits his brow and shows an angry eye</div>
<div class="dverse">And passeth by with stiff unbowed knee,</div>
<div class="dverse">Disdaining duty that to us belongs.</div>
<div class="dverse">Small curs are not regarded when they grin;</div>
<div class="dverse">But great men tremble when the lion roars;</div>
<div class="dverse"><span class="lnum">20</span> And Humphrey is no little man in England.</div>
<div class="dverse">First note that he is near you in descent,</div>
<div class="dverse">And should you fall, he as the next will mount.</div>
<div class="dverse">Me seemeth then it is no policy,</div>
<div class="dverse">Respecting what a rancorous mind he bears</div>
<div class="dverse"><span class="lnum">25</span> And his advantage following your decease,</div>
<div class="dverse">That he should come about your royal person</div>
<div class="dverse">Or be admitted to your highness’ council.</div>
<div class="dverse"><a class="lnum pginternal" href="#lnote-bca028" id="lnum-bca028">♦</a>
 By flattery hath he won the commons’ hearts,</div>
<div class="dverse">And when he please to make commotion,</div>
<div class="dverse"><span class="lnum">30</span> ’Tis to be fear’d they all will follow him.</div>
<div class="dverse">Now ’tis the spring, and weeds are shallow-rooted;</div>
<div class="dverse">Suffer them now, and they’ll o’ergrow the garden</div>
<div class="dverse">And choke the herbs for want of husbandry.</div>
<div class="dverse">The reverent care I bear unto my lord</div>
<div class="dverse"><a class="lnum pginternal" href="#lnote-bca035" id="lnum-bca035">35</a>
 Made me collect these dangers in the duke.</div>
<div class="dverse">If it be fond, call it a woman’s fear;</div>
<div class="dverse">Which fear if better reasons can supplant,</div>
<div class="dverse">I will subscribe and say I wrong’d the duke.</div>
<div class="dverse"><a class="lnum pginternal" href="#lnote-bca039" id="lnum-bca039">♦</a>
 My lord of Suffolk, Buckingham, and York,</div>
<div class="dverse"><a class="lnum pginternal" href="#lnote-bca040" id="lnum-bca040">40</a>
 Reprove my allegation, if you can;</div>
<div class="dverse">Or else conclude my words effectual.</div>

<div class="dverse1"><span class="sd-cn">Suf.</span>
 Well hath your highness seen into this duke;</div>
<div class="dverse">And, had I first been put to speak my mind,</div>
<div class="dverse">I think I should have told your grace’s tale.</div>
<div class="dverse"><span class="lnum">45</span> The duchess by his subornation,</div>
<div class="dverse"><a class="lnum pginternal" href="#lnote-bca046" id="lnum-bca046">♦</a>
 Upon my life, began her devilish practices:</div>
<div class="dverse">Or, if he were not privy to those faults,</div>
<div class="dverse"><a class="lnum pginternal" href="#lnote-bca048" id="lnum-bca048">♦</a>
 Yet, by reputing of his high descent,</div>
<div class="dverse">As next the king he was successive heir,</div>
<div class="dverse"><span class="lnum">50</span> And such high vaunts of his nobility,</div>
<div class="dverse">Did instigate the bedlam brain-sick duchess</div>
<div class="dverse">By wicked means to frame our sovereign’s fall.</div>
<div class="dverse"><a class="lnum pginternal" href="#lnote-bca053" id="lnum-bca053">♦</a>
 Smooth runs the water where the brook is deep;</div>
<div class="dverse">And in his simple show he harbours treason.</div>
<div class="dverse"><span class="lnum">55</span> The fox barks not when he would steal the lamb.</div>
<div class="dverse">No, no, my sovereign; Gloucester is a man</div>
<div class="dverse">Unsounded yet and full of deep deceit.</div>

<div class="dverse1"><span class="sd-cn">Car.</span>
 Did he not, contrary to form of law,</div>
<div class="dverse">Devise strange deaths for small offences done?</div>

<div class="dverse1"><span class="lnum">60</span>
 <span class="sd-cn">York.</span>
  And did he not, in his protectorship,</div>
<div class="dverse">Levy great sums of money through the realm</div>
<div class="dverse">For soldiers’ pay in France, and never sent it?</div>
<div class="dverse">By means whereof the towns each day revolted.</div>

<div class="dverse1"><span class="sd-cn">Buck.</span>
 Tut, these are petty faults to faults unknown,</div>
<div class="dverse"><span class="lnum">65</span> Which time will bring to light in smooth Duke Humphrey.</div>

<div class="dverse1"><span class="sd-cn">King.</span>
 My lords, at once: the care you have of us,</div>
<div class="dverse">To mow down thorns that would annoy our foot,</div>
<div class="dverse"><a class="lnum pginternal" href="#lnote-bca068" id="lnum-bca068">♦</a>
 Is worthy praise: but, shall I speak my conscience,</div>
<div class="dverse">Our kinsman Gloucester is as innocent</div>
<div class="dverse"><span class="lnum">70</span> From meaning treason to our royal person</div>
<div class="dverse">As is the sucking lamb or harmless dove:</div>
<div class="dverse">The duke is virtuous, mild and too well given</div>
<div class="dverse">To dream on evil or to work my downfall.</div>

<div class="dverse1"><span class="sd-cn">Queen.</span>
 Ah, what’s more dangerous than this fond affiance!</div>
<div class="dverse"><span class="lnum">75</span> Seems he a dove? his feathers are but borrow’d,</div>
<div class="dverse">For he’s disposed as the hateful raven:</div>
<div class="dverse">Is he a lamb? his skin is surely lent him,</div>
<div class="dverse"><a class="lnum pginternal" href="#lnote-bca078" id="lnum-bca078">♦</a>
 For he’s inclined as is the ravenous wolf.</div>
<div class="dverse">Who cannot steal a shape that means deceit?</div>
<div class="dverse"><span class="lnum">80</span> Take heed, my lord; the welfare of us all</div>
<div class="dverse">Hangs on the cutting short that fraudful man.</div>

<div class="sd-entry"><i>Enter</i> <span class="smcaps">S<span>OMERSET</span>.</span></div>

<div class="dverse1"><span class="sd-cn">Som.</span>
 All health unto my gracious sovereign!</div>

<div class="dverse1"><span class="sd-cn">King.</span>
 Welcome, Lord Somerset.  What news from France?</div>

<div class="dverse1"><a class="lnum pginternal" href="#lnote-bca084" id="lnum-bca084">♦</a>
 <span class="sd-cn">Som.</span>
  That all your interest in those territories</div>
<div class="dverse"><span class="lnum">85</span> Is utterly bereft you; all is lost.</div>

<div class="dverse1"><span class="sd-cn">King.</span>
 Cold news, Lord Somerset: but God’s will be done!</div>

<div class="dverse1"><a class="lnum pginternal" href="#lnote-bca087" id="lnum-bca087">♦</a>
 <span class="sd-cn">York.</span>
 <span class="sd-inline">[<i>Aside</i>]</span>
 Cold news for me; for I had hope of France</div>
<div class="dverse"><a class="lnum pginternal" href="#lnote-bca088" id="lnum-bca088">♦</a>
 As firmly as I hope for fertile England.</div>
<div class="dverse">Thus are my blossoms blasted in the bud</div>
<div class="dverse"><span class="lnum">90</span> And caterpillars eat my leaves away;</div>
<div class="dverse">But I will remedy this gear ere long,</div>
<div class="dverse">Or sell my title for a glorious grave.</div>

<div class="sd-entry"><i>Enter</i> <span class="smcaps">G<span>LOUCESTER</span>.</span></div>

<div class="dverse1"><a class="lnum pginternal" href="#lnote-bca093" id="lnum-bca093">♦</a>
 <span class="sd-cn">Glou.</span>
  All happiness unto my lord the king!</div>
<div class="dverse">Pardon, my liege, that I have stay’d so long.</div>

<div class="dverse1"><span class="lnum">95</span>
 <span class="sd-cn">Suf.</span>
  Nay, Gloucester, know that thou art come too soon,</div>
<div class="dverse">Unless thou wert more loyal than thou art:</div>
<div class="dverse">I do arrest thee of high treason here.</div>

<div class="dverse1"><a class="lnum pginternal" href="#lnote-bca098" id="lnum-bca098">♦</a>
 <span class="sd-cn">Glou.</span>
  Well, Suffolk, thou shalt not see me blush</div>
<div class="dverse">Nor change my countenance for this arrest:</div>
<div class="dverse"><span class="lnum">100</span> A heart unspotted is not easily daunted.</div>
<div class="dverse">The purest spring is not so free from mud</div>
<div class="dverse">As I am clear from treason to my sovereign:</div>
<div class="dverse">Who can accuse me? wherein am I guilty?</div>

<div class="dverse1"><a class="lnum pginternal" href="#lnote-bca104" id="lnum-bca104">♦</a>
 <span class="sd-cn">York.</span>
  ’Tis thought, my lord, that you took bribes of France,</div>
<div class="dverse"><span class="lnum">105</span> And, being protector, stayed the soldiers’ pay;</div>
<div class="dverse">By means whereof his highness hath lost France.</div>

<div class="dverse1"><a class="lnum pginternal" href="#lnote-bca107" id="lnum-bca107">♦</a>
 <span class="sd-cn">Glou.</span>
  Is it but thought so? what are they that think it?</div>
<div class="dverse">I never robb’d the soldiers of their pay,</div>
<div class="dverse"><a class="lnum pginternal" href="#lnote-bca109" id="lnum-bca109">♦</a>
 Nor ever had one penny bribe from France.</div>
<div class="dverse"><span class="lnum">110</span> So help me God, as I have watch’d the night,</div>
<div class="dverse">Ay, night by night, in studying good for England!</div>
<div class="dverse">That doit that e’er I wrested from the king,</div>
<div class="dverse">Or any groat I hoarded to my use,</div>
<div class="dverse">Be brought against me at my trial-day!</div>
<div class="dverse"><a class="lnum pginternal" href="#lnote-bca115" id="lnum-bca115">115</a>
 No; many a pound of mine own proper store,</div>
<div class="dverse">Because I would not tax the needy commons,</div>
<div class="dverse"><a class="lnum pginternal" href="#lnote-bca117" id="lnum-bca117">♦</a>
 Have I dispursed to the garrisons,</div>
<div class="dverse">And never ask’d for restitution.</div>

<div class="dverse1"><span class="sd-cn">Car.</span>
 It serves you well, my lord, to say so much.</div>

<div class="dverse1"><span class="lnum">120</span>
 <span class="sd-cn">Glou.</span>
  I say no more than truth, so help me God!</div>

<div class="dverse1"><span class="sd-cn">York.</span>
 In your protectorship you did devise</div>
<div class="dverse">Strange tortures for offenders never heard of,</div>
<div class="dverse">That England was defamed by tyranny.</div>

<div class="dverse1"><a class="lnum pginternal" href="#lnote-bca124" id="lnum-bca124">♦</a>
 <span class="sd-cn">Glou.</span>
  Why, ’tis well known that, whiles I was protector,</div>
<div class="dverse"><span class="lnum">125</span> Pity was all the fault that was in me;</div>
<div class="dverse">For I should melt at an offender’s tears,</div>
<div class="dverse">And lowly words were ransom for their fault.</div>
<div class="dverse">Unless it were a bloody murderer,</div>
<div class="dverse">Or foul felonious thief that fleeced poor passengers,</div>
<div class="dverse"><span class="lnum">130</span> I never gave them condign punishment:</div>
<div class="dverse">Murder indeed, that bloody sin, I tortured</div>
<div class="dverse">Above the felon or what trespass else.</div>

<div class="dverse1"><a class="lnum pginternal" href="#lnote-bca133" id="lnum-bca133">♦</a>
 <span class="sd-cn">Suf.</span>
  My lord, these faults are easy, quickly answered:</div>
<div class="dverse"><a class="lnum pginternal" href="#lnote-bca134" id="lnum-bca134">♦</a>
 But mightier crimes are laid unto your charge,</div>
<div class="dverse"><span class="lnum">135</span> Whereof you cannot easily purge yourself.</div>
<div class="dverse">I do arrest you in his highness’ name;</div>
<div class="dverse"><a class="lnum pginternal" href="#lnote-bca137" id="lnum-bca137">♦</a>
 And here commit you to my lord cardinal</div>
<div class="dverse">To keep, until your further time of trial.</div>

<div class="dverse1"><span class="sd-cn">King.</span>
 My lord of Gloucester, ’tis my special hope</div>
<div class="dverse"><a class="lnum pginternal" href="#lnote-bca140" id="lnum-bca140">140</a>
 That you will clear yourself from all suspect:</div>
<div class="dverse">My conscience tells me you are innocent.</div>

<div class="dverse1"><span class="sd-cn">Glou.</span>
 Ah, gracious lord, these days are dangerous:</div>
<div class="dverse">Virtue is choked with foul ambition</div>
<div class="dverse">And charity chased hence by rancour’s hand;</div>
<div class="dverse"><span class="lnum">145</span> Foul subornation is predominant</div>
<div class="dverse">And equity exiled your highness’ land.</div>
<div class="dverse">I know their complot is to have my life,</div>
<div class="dverse">And if my death might make this island happy</div>
<div class="dverse">And prove the period of their tyranny,</div>
<div class="dverse"><span class="lnum">150</span> I would expend it with all willingness:</div>
<div class="dverse">But mine is made the prologue to their play;</div>
<div class="dverse">For thousands more, that yet suspect no peril,</div>
<div class="dverse">Will not conclude their plotted tragedy.</div>
<div class="dverse">Beaufort’s red sparkling eyes blab his heart’s malice,</div>
<div class="dverse"><span class="lnum">155</span> And Suffolk’s cloudy brow his stormy hate;</div>
<div class="dverse">Sharp Buckingham unburthens with his tongue</div>
<div class="dverse">The envious load that lies upon his heart;</div>
<div class="dverse">And dogged York, that reaches at the moon,</div>
<div class="dverse">Whose overweening arm I have pluck’d back,</div>
<div class="dverse"><span class="lnum">160</span> By false accuse doth level at my life:</div>
<div class="dverse">And you, my sovereign lady, with the rest,</div>
<div class="dverse">Causeless have laid disgraces on my head</div>
<div class="dverse"><a class="lnum pginternal" href="#lnote-bca163" id="lnum-bca163">♦</a>
 And with your best endeavour have stirr’d up</div>
<div class="dverse">My liefest liege to be mine enemy:</div>
<div class="dverse"><span class="lnum">165</span> Ay, all of you have laid your heads together—</div>
<div class="dverse"><a class="lnum pginternal" href="#lnote-bca166" id="lnum-bca166">♦</a>
 Myself had notice of your conventicles—</div>
<div class="dverse"><a class="lnum pginternal" href="#lnote-bca167" id="lnum-bca167">♦</a>
 And all to make away my guiltless life.</div>
<div class="dverse">I shall not want false witness to condemn me,</div>
<div class="dverse"><a class="lnum pginternal" href="#lnote-bca169" id="lnum-bca169">♦</a>
 Nor store of treasons to augment my guilt;</div>
<div class="dverse"><a class="lnum pginternal" href="#lnote-bca170" id="lnum-bca170">170</a>
 The ancient proverb will be well effected:</div>
<div class="dverse">
 ‘A staff is quickly found to beat a dog.’</div>

<div class="dverse1"><a class="lnum pginternal" href="#lnote-bca172" id="lnum-bca172">♦</a>
 <span class="sd-cn">Car.</span>
  My liege, his railing is intolerable:</div>
<div class="dverse">If those that care to keep your royal person</div>
<div class="dverse"><a class="lnum pginternal" href="#lnote-bca174" id="lnum-bca174">♦</a>
 From treason’s secret knife and traitors’ rage</div>
<div class="dverse"><span class="lnum">175</span> Be thus upbraided, chid and rated at,</div>
<div class="dverse">And the offender granted scope of speech,</div>
<div class="dverse">’Twill make them cool in zeal unto your grace.</div>

<div class="dverse1"><span class="sd-cn">Suf.</span>
 Hath he not twit our sovereign lady here</div>
<div class="dverse">With ignominious words, though clerkly couch’d,</div>
<div class="dverse"><span class="lnum">180</span> As if she had suborned some to swear</div>
<div class="dverse">False allegations to o’erthrow his state?</div>

<div class="dverse1"><span class="sd-cn">Queen.</span>
 But I can give the loser leave to chide.</div>

<div class="dverse1"><span class="sd-cn">Glou.</span>
 Far truer spoke than meant: I lose, indeed;</div>
<div class="dverse"><a class="lnum pginternal" href="#lnote-bca184" id="lnum-bca184">♦</a>
 Beshrew the winners, for they play’d me false!</div>
<div class="dverse"><span class="lnum">185</span> And well such losers may have leave to speak.</div>

<div class="dverse1"><span class="sd-cn">Buck.</span>
 He’ll wrest the sense and hold us here all day:</div>
<div class="dverse">Lord cardinal, he is your prisoner.</div>

<div class="dverse1"><a class="lnum pginternal" href="#lnote-bca188" id="lnum-bca188">♦</a>
 <span class="sd-cn">Car.</span>
  Sirs, take away the duke, and guard him sure.</div>

<div class="dverse1"><span class="sd-cn">Glou.</span>
 Ah! thus King Henry throws away his crutch</div>
<div class="dverse"><span class="lnum">190</span> Before his legs be firm to bear his body.</div>
<div class="dverse">Thus is the shepherd beaten from thy side</div>
<div class="dverse">And wolves are gnarling who shall gnaw thee first.</div>
<div class="dverse"><a class="lnum pginternal" href="#lnote-bca193" id="lnum-bca193">♦</a>
 Ah, that my fear were false! ah, that it were!</div>
<div class="dverse"><a class="lnum pginternal" href="#lnote-bca194" id="lnum-bca194">♦</a>
For, good King Henry, thy decay I fear. <span class="sd-verseend">[<i>Exit, guarded.</i></span></div>

<div class="dverse1"><a class="lnum pginternal" href="#lnote-bca195" id="lnum-bca195">195</a>
 <span class="sd-cn">King.</span>
  My lords, what to your wisdoms seemeth best,</div>
<div class="dverse">Do or undo, as if ourself were here.</div>

<div class="dverse1"><span class="sd-cn">Queen.</span>
 What, will your highness leave the parliament?</div>

<div class="dverse1"><span class="sd-cn">King.</span>
 Ay, Margaret; my heart is drown’d with grief,</div>
<div class="dverse">Whose flood begins to flow within mine eyes,</div>
<div class="dverse"><span class="lnum">200</span> My body round engirt with misery,</div>
<div class="dverse">For what’s more miserable than discontent?</div>
<div class="dverse">Ah, uncle Humphrey! in thy face I see</div>
<div class="dverse">The map of honour, truth and loyalty:</div>
<div class="dverse">And yet, good Humphrey, is the hour to come</div>
<div class="dverse"><span class="lnum">205</span> That e’er I proved thee false or fear’d thy faith.</div>
<div class="dverse">What louring star now envies thy estate,</div>
<div class="dverse">That these great lords and Margaret our queen</div>
<div class="dverse">Do seek subversion of thy harmless life?</div>
<div class="dverse"><a class="lnum pginternal" href="#lnote-bca209" id="lnum-bca209">♦</a>
 Thou never didst them wrong nor no man wrong;</div>
<div class="dverse"><span class="lnum">210</span> And as the butcher takes away the calf</div>
<div class="dverse"><a class="lnum pginternal" href="#lnote-bca211" id="lnum-bca211">♦</a>
 And binds the wretch and beats it when it strays,</div>
<div class="dverse">Bearing it to the bloody slaughter-house,</div>
<div class="dverse">Even so remorseless have they borne him hence;</div>
<div class="dverse">And as the dam runs lowing up and down,</div>
<div class="dverse"><span class="lnum">215</span> Looking the way her harmless young one went,</div>
<div class="dverse">And can do nought but wail her darling’s loss,</div>
<div class="dverse"><a class="lnum pginternal" href="#lnote-bca217" id="lnum-bca217">♦</a>
 Even so myself bewails good Gloucester’s case</div>
<div class="dverse"><a class="lnum pginternal" href="#lnote-bca218" id="lnum-bca218">♦</a>
 With sad unhelpful tears, and with dimm’d eyes</div>
<div class="dverse">Look after him and cannot do him good,</div>
<div class="dverse"><span class="lnum">220</span> So mighty are his vowed enemies.</div>
<div class="dverse">His fortunes I will weep and ’twixt each groan</div>
<div class="dverse"><a class="lnum pginternal" href="#lnote-bca222" id="lnum-bca222">♦</a>
 Say ‘Who’s a traitor? Gloucester he is none.’
 <span class="sd-verseend">[<i>Exeunt all but Queen,
 Cardinal Beaufort, Suffolk, and York.
 Somerset remains apart.</i></span></div>

<div class="dverse1"><a class="lnum pginternal" href="#lnote-bca223" id="lnum-bca223">♦</a>
 <span class="sd-cn">Queen.</span>
  Free lords, cold snow melts with the sun’s hot beams.</div>
<div class="dverse">Henry my lord is cold in great affairs,</div>
<div class="dverse"><a class="lnum pginternal" href="#lnote-bca225" id="lnum-bca225">225</a>
 Too full of foolish pity, and Gloucester’s show</div>
<div class="dverse">Beguiles him as the mournful crocodile</div>
<div class="dverse">With sorrow snares relenting passengers,</div>
<div class="dverse"><a class="lnum pginternal" href="#lnote-bca228" id="lnum-bca228">♦</a>
 Or as the snake roll’d in a flowering bank,</div>
<div class="dverse">With shining checker’d slough, doth sting a child</div>
<div class="dverse"><span class="lnum">230</span> That for the beauty thinks it excellent.</div>
<div class="dverse">Believe me, lords, were none more wise than I—</div>
<div class="dverse"><a class="lnum pginternal" href="#lnote-bca232" id="lnum-bca232">♦</a>
 And yet herein I judge mine own wit good—</div>
<div class="dverse">This Gloucester should be quickly rid the world,</div>
<div class="dverse">To rid us from the fear we have of him.</div>

<div class="dverse1"><span class="lnum">235</span>
 <span class="sd-cn">Car.</span>
  That he should die is worthy policy;</div>
<div class="dverse">But yet we want a colour for his death:</div>
<div class="dverse">’Tis meet he be condemn’d by course of law.</div>

<div class="dverse1"><span class="sd-cn">Suf.</span>
 But, in my mind, that were no policy:</div>
<div class="dverse">The king will labour still to save his life,</div>
<div class="dverse"><span class="lnum">240</span> The commons haply rise, to save his life;</div>
<div class="dverse"><a class="lnum pginternal" href="#lnote-bca241" id="lnum-bca241">♦</a>
 And yet we have but trivial argument,</div>
<div class="dverse">More than mistrust, that shows him worthy death.</div>

<div class="dverse1"><span class="sd-cn">York.</span>
 So that, by this, you would not have him die.</div>

<div class="dverse1"><span class="sd-cn">Suf.</span>
 Ah, York, no man alive so fain as I!</div>

<div class="dverse1"><a class="lnum pginternal" href="#lnote-bca245" id="lnum-bca245">245</a>
 <span class="sd-cn">York.</span>
  ’Tis York that hath more reason for his death.</div>
<div class="dverse"><a class="lnum pginternal" href="#lnote-bca246" id="lnum-bca246">♦</a>
 But, my lord cardinal, and you, my lord of Suffolk,</div>
<div class="dverse">Say as you think, and speak it from your souls,</div>
<div class="dverse">Were’t not all one, an empty eagle were set</div>
<div class="dverse"><a class="lnum pginternal" href="#lnote-bca249" id="lnum-bca249">♦</a>
 To guard the chicken from a hungry kite,</div>
<div class="dverse"><span class="lnum">250</span> As place Duke Humphrey for the king’s protector?</div>

<div class="dverse1"><span class="sd-cn">Queen.</span>
 So the poor chicken should be sure of death.</div>

<div class="dverse1"><span class="sd-cn">Suf.</span>
 Madam, ’tis true; and were’t not madness, then,</div>
<div class="dverse">To make the fox surveyor of the fold?</div>
<div class="dverse">Who being accused a crafty murderer,</div>
<div class="dverse"><span class="lnum">255</span> His guilt should be but idly posted over,</div>
<div class="dverse">Because his purpose is not executed.</div>
<div class="dverse">No; let him die, in that he is a fox,</div>
<div class="dverse">By nature proved an enemy to the flock,</div>
<div class="dverse">Before his chaps be stain’d with crimson blood,</div>
<div class="dverse"><a class="lnum pginternal" href="#lnote-bca260" id="lnum-bca260">260</a>
 As Humphrey, proved by reasons, to my liege.</div>
<div class="dverse">And do not stand on quillets how to slay him:</div>
<div class="dverse">Be it by gins, by snares, by subtlety,</div>
<div class="dverse">Sleeping or waking, ’tis no matter how,</div>
<div class="dverse"><a class="lnum pginternal" href="#lnote-bca264" id="lnum-bca264">♦</a>
 So he be dead; for that is good deceit</div>
<div class="dverse"><span class="lnum">265</span> Which mates him first that first intends deceit.</div>

<div class="dverse1"><a class="lnum pginternal" href="#lnote-bca266" id="lnum-bca266">♦</a>
 <span class="sd-cn">Queen.</span>
  Thrice-noble Suffolk, ’tis resolutely spoke.</div>

<div class="dverse1"><span class="sd-cn">Suf.</span>
 Not resolute, except so much were done;</div>
<div class="dverse">For things are often spoke and seldom meant:</div>
<div class="dverse">But that my heart accordeth with my tongue,</div>
<div class="dverse"><span class="lnum">270</span> Seeing the deed is meritorious,</div>
<div class="dverse">And to preserve my sovereign from his foe,</div>
<div class="dverse">Say but the word, and I will be his priest.</div>

<div class="dverse1"><span class="sd-cn">Car.</span>
 But I would have him dead, my Lord of Suffolk,</div>
<div class="dverse">Ere you can take due orders for a priest:</div>
<div class="dverse"><span class="lnum">275</span> Say you consent and censure well the deed,</div>
<div class="dverse">And I’ll provide his executioner,</div>
<div class="dverse">I tender so the safety of my liege.</div>

<div class="dverse1"><span class="sd-cn">Suf.</span>
 Here is my hand, the deed is worthy doing.</div>

<div class="dverse1"><span class="sd-cn">Queen.</span>
 And so say I.</div>

<div class="dverse1"><a class="lnum pginternal" href="#lnote-bca280" id="lnum-bca280">280</a>
 <span class="sd-cn">York.</span>
  And I: and now we three have spoke it,</div>
<div class="dverse">It skills not greatly who impugns our doom.</div>

<div class="sd-entry"><i>Enter a</i> Post.</div>

<div class="dverse1"><a class="lnum pginternal" href="#lnote-bca282" id="lnum-bca282">♦</a>
 <span class="sd-cn">Post.</span>
  Great lords, from Ireland am I come amain,</div>
<div class="dverse">To signify that rebels there are up</div>
<div class="dverse">And put the Englishmen unto the sword:</div>
<div class="dverse"><span class="lnum">285</span> Send succours, lords, and stop the rage betime,</div>
<div class="dverse"><a class="lnum pginternal" href="#lnote-bca286" id="lnum-bca286">♦</a>
 Before the wound do grow uncurable;</div>
<div class="dverse">For, being green, there is great hope of help.</div>

<div class="dverse1"><a class="lnum pginternal" href="#lnote-bca288" id="lnum-bca288">♦</a>
 <span class="sd-cn">Car.</span>
  A breach that craves a quick expedient stop!</div>
<div class="dverse">What counsel give you in this weighty cause?</div>

<div class="dverse1"><a class="lnum pginternal" href="#lnote-bca290" id="lnum-bca290">290</a>
 <span class="sd-cn">York.</span>
  That Somerset be sent as regent thither:</div>
<div class="dverse">’Tis meet that lucky ruler be employ’d;</div>
<div class="dverse">Witness the fortune he hath had in France.</div>

<div class="dverse1"><a class="lnum pginternal" href="#lnote-bca293" id="lnum-bca293">♦</a>
 <span class="sd-cn">Som.</span>
  If York, with all his far-fet policy,</div>
<div class="dverse">Had been the regent there instead of me,</div>
<div class="dverse"><span class="lnum">295</span> He never would have stay’d in France so long.</div>

<div class="dverse1"><span class="sd-cn">York.</span>
 No, not to lose it all, as thou hast done:</div>
<div class="dverse">I rather would have lost my life betimes</div>
<div class="dverse">Than bring a burthen of dishonour home</div>
<div class="dverse">By staying there so long till all were lost.</div>
<div class="dverse"><span class="lnum">300</span> Show me one scar character’d on thy skin:</div>
<div class="dverse"><a class="lnum pginternal" href="#lnote-bca301" id="lnum-bca301">♦</a>
 Men’s flesh preserved so whole do seldom win.</div>

<div class="dverse1"><span class="sd-cn">Queen.</span>
 Nay, then, this spark will prove a raging fire,</div>
<div class="dverse">If wind and fuel be brought to feed it with:</div>
<div class="dverse">No more, good York; sweet Somerset, be still:</div>
<div class="dverse"><span class="lnum">305</span> Thy fortune, York, hadst thou been regent there,</div>
<div class="dverse"><a class="lnum pginternal" href="#lnote-bca306" id="lnum-bca306">♦</a>
 Might happily have proved far worse than his.</div>

<div class="dverse1"><a class="lnum pginternal" href="#lnote-bca307" id="lnum-bca307">♦</a>
 <span class="sd-cn">York.</span>
  What, worse than nought? nay, then, a shame take all!</div>

<div class="dverse1"><span class="sd-cn">Som.</span>
 And, in the number, thee that wishest shame!</div>

<div class="dverse1"><span class="sd-cn">Car.</span>
 My Lord of York, try what your fortune is.</div>
<div class="dverse"><span class="lnum">310</span> The uncivil kernes of Ireland are in arms</div>
<div class="dverse">And temper clay with blood of Englishmen:</div>
<div class="dverse">To Ireland will you lead a band of men,</div>
<div class="dverse"><a class="lnum pginternal" href="#lnote-bca313" id="lnum-bca313">♦</a>
 Collected choicely, from each county some,</div>
<div class="dverse">And try your hap against the Irishmen?</div>

<div class="dverse1"><span class="lnum">315</span>
 <span class="sd-cn">York.</span>
  I will, my lord, so please his majesty.</div>

<div class="dverse1"><span class="sd-cn">Suf.</span>
 Why, our authority is his consent,</div>
<div class="dverse">And what we do establish he confirms:</div>
<div class="dverse">Then, noble York, take thou this task in hand.</div>

<div class="dverse1"><span class="sd-cn">York.</span>
 I am content: provide me soldiers, lords,</div>
<div class="dverse"><span class="lnum">320</span> Whiles I take order for mine own affairs.</div>

<div class="dverse1"><span class="sd-cn">Suf.</span>
 A charge, Lord York, that I will see perform’d.</div>
<div class="dverse">But now return we to the false Duke Humphrey.</div>

<div class="dverse1"><span class="sd-cn">Car.</span>
 No more of him; for I will deal with him</div>
<div class="dverse">That henceforth he shall trouble us no more.</div>
<div class="dverse"><span class="lnum">325</span> And so break off; the day is almost spent:</div>
<div class="dverse"><a class="lnum pginternal" href="#lnote-bca326" id="lnum-bca326">♦</a>
 Lord Suffolk, you and I must talk of that event.</div>

<div class="dverse1"><span class="sd-cn">York.</span>
 My Lord of Suffolk, within fourteen days</div>
<div class="dverse"><a class="lnum pginternal" href="#lnote-bca328" id="lnum-bca328">♦</a>
 At Bristol I expect my soldiers;</div>
<div class="dverse">For there I’ll ship them all for Ireland.</div>

<div class="dverse1"><a class="lnum pginternal" href="#lnote-bca330" id="lnum-bca330">330</a>
 <span class="sd-cn">Suf.</span>
 I’ll see it truly done, my Lord of York.
 <span class="sd-verseend">[<i>Exeunt all but York.</i></span></div>

<div class="dverse1"><a class="lnum pginternal" href="#lnote-bca331" id="lnum-bca331">♦</a>
 <span class="sd-cn">York.</span>
  Now, York, or never, steel thy fearful thoughts,</div>
<div class="dverse">And change misdoubt to resolution:</div>
<div class="dverse"><a class="lnum pginternal" href="#lnote-bca333" id="lnum-bca333">♦</a>
 Be that thou hopest to be, or what thou art</div>
<div class="dverse">Resign to death; it is not worth the enjoying:</div>
<div class="dverse"><span class="lnum">335</span> Let pale-faced fear keep with the mean-born man,</div>
<div class="dverse">And find no harbour in a royal heart.</div>
<div class="dverse">Faster than spring-time showers comes thought on thought,</div>
<div class="dverse">And not a thought but thinks on dignity.</div>
<div class="dverse"><a class="lnum pginternal" href="#lnote-bca339" id="lnum-bca339">♦</a>
 My brain more busy than the labouring spider</div>
<div class="dverse"><span class="lnum">340</span> Weaves tedious snares to trap mine enemies.</div>
<div class="dverse">Well, nobles, well, ’tis politicly done,</div>
<div class="dverse">To send me packing with an host of men:</div>
<div class="dverse">I fear me you but warm the starved snake,</div>
<div class="dverse">Who, cherish’d in your breasts, will sting your hearts.</div>
<div class="dverse"><span class="lnum">345</span> ’Twas men I lack’d and you will give them me:</div>
<div class="dverse">I take it kindly; yet be well assured</div>
<div class="dverse">You put sharp weapons in a madman’s hands.</div>
<div class="dverse"><a class="lnum pginternal" href="#lnote-bca348" id="lnum-bca348">♦</a>
 Whiles I in Ireland nourish a mighty band,</div>
<div class="dverse">I will stir up in England some black storm</div>
<div class="dverse"><span class="lnum">350</span> Shall blow ten thousand souls to heaven or hell;</div>
<div class="dverse">And this fell tempest shall not cease to rage</div>
<div class="dverse">Until the golden circuit on my head,</div>
<div class="dverse">Like to the glorious sun’s transparent beams,</div>
<div class="dverse"><a class="lnum pginternal" href="#lnote-bca354" id="lnum-bca354">♦</a>
 Do calm the fury of this mad-bred flaw.</div>
<div class="dverse"><span class="lnum">355</span> And, for a minister of my intent,</div>
<div class="dverse">I have seduced a headstrong Kentishman,</div>
<div class="dverse"><a class="lnum pginternal" href="#lnote-bca357" id="lnum-bca357">♦</a>
 John Cade of Ashford,</div>
<div class="dverse">To make commotion, as full well he can,</div>
<div class="dverse">Under the title of John Mortimer.</div>
<div class="dverse"><span class="lnum">360</span> In Ireland have I seen this stubborn Cade</div>
<div class="dverse">Oppose himself against a troop of kernes,</div>
<div class="dverse"><a class="lnum pginternal" href="#lnote-bca362" id="lnum-bca362">♦</a>
 And fought so long, till that his thighs with darts</div>
<div class="dverse"><a class="lnum pginternal" href="#lnote-bca363" id="lnum-bca363">♦</a>
 Were almost like a sharp-quill’d porpentine;</div>
<div class="dverse"><a class="lnum pginternal" href="#lnote-bca364" id="lnum-bca364">♦</a>
 And, in the end being rescued, I have seen</div>
<div class="dverse"><span class="lnum">365</span> Him caper upright like a wild Morisco,</div>
<div class="dverse">Shaking the bloody darts as he his bells.</div>
<div class="dverse">Full often, like a shag-hair’d crafty kerne,</div>
<div class="dverse">Hath he conversed with the enemy,</div>
<div class="dverse">And undiscover’d come to me again</div>
<div class="dverse"><span class="lnum">370</span> And given me notice of their villanies.</div>
<div class="dverse">This devil here shall be my substitute;</div>
<div class="dverse">For that John Mortimer, which now is dead,</div>
<div class="dverse">In face, in gait, in speech, he doth resemble:</div>
<div class="dverse">By this I shall perceive the commons’ mind,</div>
<div class="dverse"><span class="lnum">375</span> How they affect the house and claim of York.</div>
<div class="dverse">Say he be taken, rack’d and tortured,</div>
<div class="dverse">I know no pain they can inflict upon him</div>
<div class="dverse"><a class="lnum pginternal" href="#lnote-bca378" id="lnum-bca378">♦</a>
 Will make him say I moved him to those arms.</div>
<div class="dverse">Say that he thrive, as ’tis great like he will,</div>
<div class="dverse"><span class="lnum">380</span> Why, then from Ireland come I with my strength</div>
<div class="dverse">And reap the harvest which that rascal sow’d;</div>
<div class="dverse">For Humphrey being dead, as he shall be,</div>
<div class="dverse"><a class="lnum pginternal" href="#lnote-bca383" id="lnum-bca383">♦</a>
 And Henry put apart, the next for me.
 <span class="sd-verseend">[<i>Exit.</i></span></div>

<div class="section">
<h4 class="h4main"><span class="dnavigate">bcb</span> <span class="smcaps">S<span>CENE</span></span> II. <i>Bury St Edmund’s. A room
of state</i>.</h4>

<div class="sd-schg"><i>Enter certain</i> Murderers, <i>hastily</i>.</div></div>

<div class="dverse1"><a class="lnum pginternal" href="#lnote-bcb001" id="lnum-bcb001">♦</a>
 <span class="sd-cn">First Mur.</span>
  Run to my Lord of Suffolk; let him know</div>
<div class="dverse">We have dispatch’d the duke, as he commanded.</div>

<div class="dverse1"><span class="sd-cn">Sec. Mur.</span>
 O that it were to do! What have we done?</div>
<div class="dverse"><a class="lnum pginternal" href="#lnote-bcb004" id="lnum-bcb004">♦</a>
 Didst ever hear a man so penitent?</div>

<div class="sd-entry"><i>Enter</i> <span class="smcaps">S<span>UFFOLK</span>.</span></div>

<div class="dverse1"><a class="lnum pginternal" href="#lnote-bcb005" id="lnum-bcb005">5</a>
 <span class="sd-cn">First Mur.</span>
  Here comes my lord.</div>

<div class="dverse1"><span class="sd-cn">Suf.</span>
 Now, sirs, have you dispatch’d this thing?</div>

<div class="dverse1"><span class="sd-cn">First Mur.</span>
 Ay, my good lord, he’s dead.</div>

<div class="dverse1"><span class="sd-cn">Suf.</span>
 Why, that’s well said. Go, get you to my house;</div>
<div class="dverse">I will reward you for this venturous deed.</div>
<div class="dverse"><span class="lnum">10</span> The king and all the peers are here at hand.</div>
<div class="dverse"><a class="lnum pginternal" href="#lnote-bcb011" id="lnum-bcb011">♦</a>
 Have you laid fair the bed? Is all things well,</div>
<div class="dverse">According as I gave directions?</div>

<div class="dverse1"><a class="lnum pginternal" href="#lnote-bcb013" id="lnum-bcb013">♦</a>
 <span class="sd-cn">First Mur.</span>
  ’Tis, my good lord.</div>

<div class="dverse1"><a class="lnum pginternal" href="#lnote-bcb014" id="lnum-bcb014">♦</a>
 <span class="sd-cn">Suf.</span>
Away! be gone. <span class="sd-verseend">[<i>Exeunt Murderers.</i></span></div>

<div class="sd-entry"><i>Sound trumpets. Enter the</i>
<span class="smcaps">K<span>ING</span>,</span> <i>the</i>
<span class="smcaps">Q<span>UEEN</span>,</span> <span class="smcaps">C<span>ARDINAL</span></span> <span class="smcaps">B<span>EAUFORT</span>,</span> <span class="smcaps">S<span>OMERSET</span>,</span> <i>with Attendants</i>. </div>

<div class="dverse1"><span class="lnum">15</span>
 <span class="sd-cn">King.</span>
  Go, call our uncle to our presence straight;</div>
<div class="dverse">Say we intend to try his grace to-day,</div>
<div class="dverse">If he be guilty, as ’tis published.</div>

<div class="dverse1"><span class="sd-cn">Suf.</span>
 I’ll call him presently, my noble lord. <span class="sd-verseend">[<i>Exit.</i></span></div>

<div class="dverse1"><span class="sd-cn">King.</span>
 Lords, take your places; and, I pray you all,</div>
<div class="dverse"><span class="lnum">20</span> Proceed no straiter ’gainst our uncle Gloucester</div>
<div class="dverse">Than from true evidence of good esteem</div>
<div class="dverse">He be approved in practice culpable.</div>

<div class="dverse1"><span class="sd-cn">Queen.</span>
 God forbid any malice should prevail,</div>
<div class="dverse">That faultless may condemn a nobleman!</div>
<div class="dverse"><span class="lnum">25</span> Pray God he may acquit him of suspicion!</div>

<div class="dverse1"><a class="lnum pginternal" href="#lnote-bcb026" id="lnum-bcb026">♦</a>
 <span class="sd-cn">King.</span>
  I thank thee, Nell; these words content me much.</div>

<div class="sd-entry"><i>Re-enter</i> <span class="smcaps">S<span>UFFOLK</span>.</span></div>

<div class="dverse">How now! why look’st thou pale? why tremblest thou?</div>
<div class="dverse">Where is our uncle? what’s the matter, Suffolk?</div>

<div class="dverse1"><span class="sd-cn">Suf.</span>
 Dead in his bed, my lord; Gloucester is dead.</div>

<div class="dverse1"><span class="lnum">30</span>
 <span class="sd-cn">Queen.</span>
  Marry, God forfend!</div>

<div class="dverse1"><span class="sd-cn">Car.</span>
 God’s secret judgement: I did dream to-night</div>
<div class="dverse"><a class="lnum pginternal" href="#lnote-bcb032" id="lnum-bcb032">♦</a>
 The duke was dumb and could not speak a word.
 <span class="sd-verseend">[<i>The King swoons.</i></span></div>

<div class="dverse1"><span class="sd-cn">Queen.</span>
 How fares my lord? Help, lords! the king is dead.</div>

<div class="dverse1"><span class="sd-cn">Som.</span>
 Rear up his body; wring him by the nose.</div>

<div class="dverse1"><span class="lnum">35</span>
 <span class="sd-cn">Queen.</span>
  Run, go, help, help! O Henry, ope thine eyes!</div>

<div class="dverse1"><span class="sd-cn">Suf.</span>
 He doth revive again: madam, be patient.</div>

<div class="dverse1"><span class="sd-cn">King.</span>
 O heavenly God!</div>

<div class="dverse1"><span class="sd-cn">Queen.</span>
 <span class="i09"> </span> How fares my gracious lord?</div>

<div class="dverse1"><a class="lnum pginternal" href="#lnote-bcb038" id="lnum-bcb038">♦</a>
 <span class="sd-cn">Suf.</span>
  Comfort, my sovereign! gracious Henry, comfort!</div>

<div class="dverse1"><span class="sd-cn">King.</span>
 What, doth my Lord of Suffolk comfort me?</div>
<div class="dverse"><span class="lnum">40</span> Came he right now to sing a raven’s note,</div>
<div class="dverse"><a class="lnum pginternal" href="#lnote-bcb041" id="lnum-bcb041">♦</a>
 Whose dismal tune bereft my vital powers;</div>
<div class="dverse">And thinks he that the chirping of a wren,</div>
<div class="dverse">By crying comfort from a hollow breast,</div>
<div class="dverse">Can chase away the first-conceived sound?</div>
<div class="dverse"><span class="lnum">45</span> Hide not thy poison with such sugar’d words;</div>
<div class="dverse">Lay not thy hands on me; forbear, I say;</div>
<div class="dverse">Their touch affrights me as a serpent’s sting.</div>
<div class="dverse">Thou baleful messenger, out of my sight!</div>
<div class="dverse">Upon thy eye-balls murderous tyranny</div>
<div class="dverse"><span class="lnum">50</span> Sits in grim majesty, to fright the world.</div>
<div class="dverse">Look not upon me, for thine eyes are wounding:</div>
<div class="dverse">Yet do not go away: come, basilisk,</div>
<div class="dverse">And kill the innocent gazer with thy sight;</div>
<div class="dverse">For in the shade of death I shall find joy;</div>
<div class="dverse"><span class="lnum">55</span> In life but double death, now Gloucester’s dead.</div>

<div class="dverse1"><span class="sd-cn">Queen.</span>
 Why do you rate my Lord of Suffolk thus?</div>
<div class="dverse">Although the duke was enemy to him,</div>
<div class="dverse">Yet he most Christian-like laments his death:</div>
<div class="dverse">And for myself, foe as he was to me,</div>
<div class="dverse"><span class="lnum">60</span> Might liquid tears or heart-offending groans</div>
<div class="dverse">Or blood-consuming sighs recall his life,</div>
<div class="dverse">I would be blind with weeping, sick with groans,</div>
<div class="dverse"><a class="lnum pginternal" href="#lnote-bcb063" id="lnum-bcb063">♦</a>
 Look pale as primrose with blood-drinking sighs,</div>
<div class="dverse">And all to have the noble duke alive.</div>
<div class="dverse"><span class="lnum">65</span> What know I how the world may deem of me?</div>
<div class="dverse">For it is known we were but hollow friends:</div>
<div class="dverse">It may be judged I made the duke away;</div>
<div class="dverse">So shall my name with slander’s tongue be wounded,</div>
<div class="dverse"><a class="lnum pginternal" href="#lnote-bcb069" id="lnum-bcb069">♦</a>
 And princes’ courts be fill’d with my reproach.</div>
<div class="dverse"><a class="lnum pginternal" href="#lnote-bcb070" id="lnum-bcb070">70</a>
 This get I by his death: ay me, unhappy!</div>
<div class="dverse">To be a queen, and crown’d with infamy!</div>

<div class="dverse1"><span class="sd-cn">King.</span>
 Ah, woe is me for Gloucester, wretched man!</div>

<div class="dverse1"><span class="sd-cn">Queen.</span>
 Be woe for me, more wretched than he is.</div>
<div class="dverse">What, dost thou turn away and hide thy face?</div>
<div class="dverse"><span class="lnum">75</span> I am no loathsome leper; look on me.</div>
<div class="dverse"><a class="lnum pginternal" href="#lnote-bcb076" id="lnum-bcb076">♦</a>
 What! art thou, like the adder, waxen deaf?</div>
<div class="dverse">Be poisonous too and kill thy forlorn queen.</div>
<div class="dverse"><a class="lnum pginternal" href="#lnote-bcb078" id="lnum-bcb078">♦</a>
 Is all thy comfort shut in Gloucester’s tomb?</div>
<div class="dverse"><a class="lnum pginternal" href="#lnote-bcb079" id="lnum-bcb079">♦</a>
 Why, then, dame Eleanor was ne’er thy joy.</div>
<div class="dverse"><a class="lnum pginternal" href="#lnote-bcb080" id="lnum-bcb080">80</a>
 Erect his statua and worship it,</div>
<div class="dverse">And make my image but an alehouse sign.</div>
<div class="dverse">Was I for this nigh wreck’d upon the sea</div>
<div class="dverse"><a class="lnum pginternal" href="#lnote-bcb083" id="lnum-bcb083">♦</a>
 And twice by awkward wind from England’s bank</div>
<div class="dverse">Drove back again unto my native clime?</div>
<div class="dverse"><a class="lnum pginternal" href="#lnote-bcb085" id="lnum-bcb085">85</a>
 What boded this, but well forewarning wind</div>
<div class="dverse">Did seem to say ‘Seek not a scorpion’s nest,</div>
<div class="dverse"><a class="lnum pginternal" href="#lnote-bcb087" id="lnum-bcb087">♦</a>
 Nor set no footing on this unkind shore?’</div>
<div class="dverse"><a class="lnum pginternal" href="#lnote-bcb088" id="lnum-bcb088">♦</a>
 What did I then, but cursed the gentle gusts</div>
<div class="dverse"><a class="lnum pginternal" href="#lnote-bcb089" id="lnum-bcb089">♦</a>
 And he that loosed them forth their brazen caves;</div>
<div class="dverse"><span class="lnum">90</span> And bid them blow towards England’s blessed shore,</div>
<div class="dverse">Or turn our stern upon a dreadful rock?</div>
<div class="dverse">Yet Æolus would not be a murderer,</div>
<div class="dverse"><a class="lnum pginternal" href="#lnote-bcb093" id="lnum-bcb093">♦</a>
 But left that hateful office unto thee:</div>
<div class="dverse"><a class="lnum pginternal" href="#lnote-bcb094" id="lnum-bcb094">♦</a>
 The pretty-vaulting sea refused to drown me,</div>
<div class="dverse"><span class="lnum">95</span> Knowing that thou wouldst have me drown’d on shore,</div>
<div class="dverse">With tears as salt as sea, through thy unkindness:</div>
<div class="dverse"><a class="lnum pginternal" href="#lnote-bcb097" id="lnum-bcb097">♦</a>
 The splitting rocks cower’d in the sinking sands</div>
<div class="dverse">And would not dash me with their ragged sides,</div>
<div class="dverse">Because thy flinty heart, more hard than they,</div>
<div class="dverse"><span class="lnum">100</span> Might in thy palace perish Eleanor.</div>
<div class="dverse"><a class="lnum pginternal" href="#lnote-bcb101" id="lnum-bcb101">♦</a>
 As far as I could ken thy chalky cliffs,</div>
<div class="dverse">When from thy shore the tempest beat us back,</div>
<div class="dverse">I stood upon the hatches in the storm,</div>
<div class="dverse">And when the dusky sky began to rob</div>
<div class="dverse"><a class="lnum pginternal" href="#lnote-bcb105" id="lnum-bcb105">105</a>
 My earnest-gaping sight of thy land’s view,</div>
<div class="dverse">I took a costly jewel from my neck—</div>
<div class="dverse">A heart it was, bound in with diamonds—</div>
<div class="dverse">And threw it towards thy land: the sea received it,</div>
<div class="dverse">And so I wish’d thy body might my heart:</div>
<div class="dverse"><span class="lnum">110</span> And even with this I lost fair England’s view</div>
<div class="dverse">And bid mine eyes be packing with my heart</div>
<div class="dverse">And call’d them blind and dusky spectacles,</div>
<div class="dverse">For losing ken of Albion’s wished coast.</div>
<div class="dverse">How often have I tempted Suffolk’s tongue,</div>
<div class="dverse"><span class="lnum">115</span> The agent of thy foul inconstancy,</div>
<div class="dverse"><a class="lnum pginternal" href="#lnote-bcb116" id="lnum-bcb116">♦</a>
 To sit and witch me, as Ascanius did</div>
<div class="dverse">When he to madding Dido would unfold</div>
<div class="dverse">His father’s acts commenced in burning Troy!</div>
<div class="dverse"><a class="lnum pginternal" href="#lnote-bcb119" id="lnum-bcb119">♦</a>
 Am I not witch’d like her? or thou not false like him?</div>
<div class="dverse"><a class="lnum pginternal" href="#lnote-bcb120" id="lnum-bcb120">120</a>
 Ay me, I can no more! die, Eleanor!</div>
<div class="dverse"><a class="lnum pginternal" href="#lnote-bcb121" id="lnum-bcb121">♦</a>
 For Henry weeps that thou dost live so long.</div>

<div class="sd-entry"><i>Noise within. Enter</i> <span class="smcaps">W<span>ARWICK</span>,</span> <span class="smcaps">S<span>ALISBURY</span></span> <i>and many</i> Commons.</div>

<div class="dverse1"><span class="sd-cn">War.</span>
 It is reported, mighty sovereign,</div>
<div class="dverse">That good Duke Humphrey traitorously is murder’d</div>
<div class="dverse"><a class="lnum pginternal" href="#lnote-bcb124" id="lnum-bcb124">♦</a>
 By Suffolk and the Cardinal Beaufort’s means.</div>
<div class="dverse"><span class="lnum">125</span> The commons, like an angry hive of bees</div>
<div class="dverse">That want their leader, scatter up and down</div>
<div class="dverse"><a class="lnum pginternal" href="#lnote-bcb127" id="lnum-bcb127">♦</a>
 And care not who they sting in his revenge.</div>
<div class="dverse">Myself have calm’d their spleenful mutiny,</div>
<div class="dverse">Until they hear the order of his death.</div>

<div class="dverse1"><span class="lnum">130</span>
 <span class="sd-cn">King.</span>
  That he is dead, good Warwick, ’tis too true;</div>
<div class="dverse">But how he died God knows, not Henry:</div>
<div class="dverse">Enter his chamber, view his breathless corpse,</div>
<div class="dverse">And comment then upon his sudden death.</div>

<div class="dverse1"><a class="lnum pginternal" href="#lnote-bcb134" id="lnum-bcb134">♦</a>
 <span class="sd-cn">War.</span>
  That shall I do, my liege. Stay, Salisbury,</div>
<div class="dverse"><a class="lnum pginternal" href="#lnote-bcb135" id="lnum-bcb135">135</a>
With the rude multitude till I return. <span class="sd-verseend">[<i>Exit.</i></span></div>

<div class="dverse1"><span class="sd-cn">King.</span>
 O Thou that judgest all things, stay my thoughts,</div>
<div class="dverse">My thoughts, that labour to persuade my soul</div>
<div class="dverse">Some violent hands were laid on Humphrey’s life!</div>
<div class="dverse">If my suspect be false, forgive me, God,</div>
<div class="dverse"><span class="lnum">140</span> For judgement only doth belong to thee.</div>
<div class="dverse">Fain would I go to chafe his paly lips</div>
<div class="dverse"><a class="lnum pginternal" href="#lnote-bcb142" id="lnum-bcb142">♦</a>
 With twenty thousand kisses and to drain</div>
<div class="dverse">Upon his face an ocean of salt tears,</div>
<div class="dverse">To tell my love unto his dumb deaf trunk</div>
<div class="dverse"><span class="lnum">145</span> And with my fingers feel his hand unfeeling:</div>
<div class="dverse">But all in vain are these mean obsequies;</div>
<div class="dverse"><a class="lnum pginternal" href="#lnote-bcb147" id="lnum-bcb147">♦</a>
 And to survey his dead and earthy image,</div>
<div class="dverse"><a class="lnum pginternal" href="#lnote-bcb148" id="lnum-bcb148">♦</a>
 What were it but to make my sorrow greater?</div>

<div class="sd-entry"><i>Re-enter</i> <span class="smcaps">W<span>ARWICK</span></span> <i>and others, bearing</i> <span class="smcaps">G<span>LOUCESTER’S</span></span> <i>body on a bed</i>.</div>

<div class="dverse1"><span class="sd-cn">War.</span>
 Come hither, gracious sovereign, view this body.</div>

<div class="dverse1"><span class="lnum">150</span>
 <span class="sd-cn">King.</span>
  That is to see how deep my grave is made;</div>
<div class="dverse">For with his soul fled all my worldly solace,</div>
<div class="dverse"><a class="lnum pginternal" href="#lnote-bcb152" id="lnum-bcb152">♦</a>
 For seeing him I see my life in death.</div>

<div class="dverse1"><span class="sd-cn">War.</span>
 As surely as my soul intends to live</div>
<div class="dverse">With that dread King that took our state upon him</div>
<div class="dverse"><span class="lnum">155</span> To free us from his father’s wrathful curse,</div>
<div class="dverse">I do believe that violent hands were laid</div>
<div class="dverse">Upon the life of this thrice-famed duke.</div>

<div class="dverse1"><span class="sd-cn">Suf.</span>
 A dreadful oath, sworn with a solemn tongue!</div>
<div class="dverse"><a class="lnum pginternal" href="#lnote-bcb159" id="lnum-bcb159">♦</a>
 What instance gives Lord Warwick for his vow?</div>

<div class="dverse1"><span class="lnum">160</span>
 <span class="sd-cn">War.</span>
  See how the blood is settled in his face.</div>
<div class="dverse"><a class="lnum pginternal" href="#lnote-bcb161" id="lnum-bcb161">♦</a>
 Oft have I seen a timely-parted ghost,</div>
<div class="dverse"><a class="lnum pginternal" href="#lnote-bcb162" id="lnum-bcb162">♦</a>
 Of ashy semblance, meagre, pale and bloodless,</div>
<div class="dverse">Being all descended to the labouring heart;</div>
<div class="dverse">Who, in the conflict that it holds with death,</div>
<div class="dverse"><span class="lnum">165</span> Attracts the same for aidance ’gainst the enemy;</div>
<div class="dverse">Which with the heart there cools and ne’er returneth</div>
<div class="dverse">To blush and beautify the cheek again.</div>
<div class="dverse">But see, his face is black and full of blood,</div>
<div class="dverse">His eye-balls further out than when he lived,</div>
<div class="dverse"><span class="lnum">170</span> Staring full ghastly like a strangled man;</div>
<div class="dverse"><a class="lnum pginternal" href="#lnote-bcb171" id="lnum-bcb171">♦</a>
 His hair uprear’d, his nostrils stretch’d with struggling;</div>
<div class="dverse">His hands abroad display’d, as one that grasp’d</div>
<div class="dverse">And tugg’d for life and was by strength subdued:</div>
<div class="dverse"><a class="lnum pginternal" href="#lnote-bcb174" id="lnum-bcb174">♦</a>
 Look, on the sheets his hair, you see, is sticking;</div>
<div class="dverse"><a class="lnum pginternal" href="#lnote-bcb175" id="lnum-bcb175">175</a>
 His well-proportion’d beard made rough and rugged,</div>
<div class="dverse">Like to the summer’s corn by tempest lodged.</div>
<div class="dverse"><a class="lnum pginternal" href="#lnote-bcb177" id="lnum-bcb177">♦</a>
 It cannot be but he was murder’d here;</div>
<div class="dverse">The least of all these signs were probable.</div>

<div class="dverse1"><a class="lnum pginternal" href="#lnote-bcb179" id="lnum-bcb179">♦</a>
 <span class="sd-cn">Suf.</span>
  Why, Warwick, who should do the duke to death?</div>
<div class="dverse"><span class="lnum">180</span> Myself and Beaufort had him in protection;</div>
<div class="dverse"><a class="lnum pginternal" href="#lnote-bcb181" id="lnum-bcb181">♦</a>
 And we, I hope, sir, are no murderers.</div>

<div class="dverse1"><a class="lnum pginternal" href="#lnote-bcb182" id="lnum-bcb182">♦</a>
 <span class="sd-cn">War.</span>
  But both of you were vow’d Duke Humphrey’s foes,</div>
<div class="dverse">And you, forsooth, had the good duke to keep:</div>
<div class="dverse">’Tis like you would not feast him like a friend;</div>
<div class="dverse"><span class="lnum">185</span> And ’tis well seen he found an enemy.</div>

<div class="dverse1"><a class="lnum pginternal" href="#lnote-bcb186" id="lnum-bcb186">♦</a>
 <span class="sd-cn">Queen.</span>
  Then you, belike, suspect these noblemen</div>
<div class="dverse">As guilty of Duke Humphrey’s timeless death.</div>

<div class="dverse1"><span class="sd-cn">War.</span>
 Who finds the heifer dead and bleeding fresh</div>
<div class="dverse">And sees fast by a butcher with an axe,</div>
<div class="dverse"><span class="lnum">190</span> But will suspect ’twas he that made the slaughter?</div>
<div class="dverse">Who finds the partridge in the puttock’s nest,</div>
<div class="dverse">But may imagine how the bird was dead,</div>
<div class="dverse">Although the kite soar with unbloodied beak?</div>
<div class="dverse">Even so suspicious is this tragedy.</div>

<div class="dverse1"><a class="lnum pginternal" href="#lnote-bcb195" id="lnum-bcb195">195</a>
 <span class="sd-cn">Queen.</span>
  Are you the butcher, Suffolk? Where’s your knife?</div>
<div class="dverse">Is Beaufort term’d a kite? Where are his talons?</div>

<div class="dverse1"><span class="sd-cn">Suf.</span>
 I wear no knife to slaughter sleeping men;</div>
<div class="dverse">But here’s a vengeful sword, rusted with ease,</div>
<div class="dverse">That shall be scoured in his rancorous heart</div>
<div class="dverse"><span class="lnum">200</span> That slanders me with murder’s crimson badge.</div>
<div class="dverse">Say, if thou darest, proud Lord of Warwickshire,</div>
<div class="dverse"><a class="lnum pginternal" href="#lnote-bcb202" id="lnum-bcb202">♦</a>
 That I am faulty in Duke Humphrey’s death.
 <span class="sd-verseend">[<i>Exeunt Cardinal, Somerset, and others.</i></span></div>

<div class="dverse1"><span class="sd-cn">War.</span>
 What dares not Warwick, if false Suffolk dare him?</div>

<div class="dverse1"><a class="lnum pginternal" href="#lnote-bcb204" id="lnum-bcb204">♦</a>
 <span class="sd-cn">Queen.</span>
  He dares not calm his contumelious spirit</div>
<div class="dverse"><span class="lnum">205</span> Nor cease to be an arrogant controller,</div>
<div class="dverse">Though Suffolk dare him twenty thousand times.</div>

<div class="dverse1"><a class="lnum pginternal" href="#lnote-bcb207" id="lnum-bcb207">♦</a>
 <span class="sd-cn">War.</span>
  Madam, be still; with reverence may I say;</div>
<div class="dverse">For every word you speak in his behalf</div>
<div class="dverse">Is slander to your royal dignity.</div>

<div class="dverse1"><span class="lnum">210</span>
 <span class="sd-cn">Suf.</span>
  Blunt-witted lord, ignoble in demeanour!</div>
<div class="dverse">If ever lady wrong’d her lord so much,</div>
<div class="dverse">Thy mother took into her blameful bed</div>
<div class="dverse">Some stern untutor’d churl, and noble stock</div>
<div class="dverse">Was graft with crab-tree slip; whose fruit thou art</div>
<div class="dverse"><span class="lnum">215</span> And never of the Nevils’ noble race.</div>

<div class="dverse1"><span class="sd-cn">War.</span>
 But that the guilt of murder bucklers thee</div>
<div class="dverse">And I should rob the deathsman of his fee,</div>
<div class="dverse">Quitting thee thereby of ten thousand shames,</div>
<div class="dverse">And that my sovereign’s presence makes me mild,</div>
<div class="dverse"><span class="lnum">220</span> I would, false murderous coward, on thy knee</div>
<div class="dverse">Make thee beg pardon for thy passed speech</div>
<div class="dverse">And say it was thy mother that thou meant’st,</div>
<div class="dverse">That thou thyself wast born in bastardy;</div>
<div class="dverse">And after all this fearful homage done,</div>
<div class="dverse"><a class="lnum pginternal" href="#lnote-bcb225" id="lnum-bcb225">225</a>
 Give thee thy hire and send thy soul to hell,</div>
<div class="dverse">Pernicious blood-sucker of sleeping men!</div>

<div class="dverse1"><span class="sd-cn">Suf.</span>
 Thou shalt be waking while I shed thy blood,</div>
<div class="dverse">If from this presence thou darest go with me.</div>

<div class="dverse1"><span class="sd-cn">War.</span>
 Away even now, or I will drag thee hence:</div>
<div class="dverse"><span class="lnum">230</span> Unworthy though thou art, I’ll cope with thee</div>
<div class="dverse"><a class="lnum pginternal" href="#lnote-bcb231" id="lnum-bcb231">♦</a>
 And do some service to Duke Humphrey’s ghost.
 <span class="sd-verseend">[<i>Exeunt Suffolk and Warwick.</i></span></div>

<div class="dverse1"><a class="lnum pginternal" href="#lnote-bcb232" id="lnum-bcb232">♦</a>
 <span class="sd-cn">King.</span>
  What stronger breastplate than a heart untainted!</div>
<div class="dverse">Thrice is he armed that hath his quarrel just,</div>
<div class="dverse">And he but naked, though lock’d up in steel,</div>
<div class="dverse"><span class="lnum">235</span> Whose conscience with injustice is corrupted.
 <span class="sd-verseend">[<i>A noise within.</i></span></div>

<div class="dverse1"><a class="lnum pginternal" href="#lnote-bcb236" id="lnum-bcb236">♦</a>
 <span class="sd-cn">Queen.</span>
  What noise is this?</div>

<div class="sd-entry"><i>Re-enter</i> <span class="smcaps">S<span>UFFOLK</span></span> <i>and</i> <span class="smcaps">W<span>ARWICK</span>,</span> <i>with their weapons drawn</i>. </div>

<div class="dverse1"><a class="lnum pginternal" href="#lnote-bcb237" id="lnum-bcb237">♦</a>
 <span class="sd-cn">King.</span>
  Why, how now, lords! your wrathful weapons drawn</div>
<div class="dverse">Here in our presence! dare you be so bold?</div>
<div class="dverse">Why, what tumultuous clamour have we here?</div>

<div class="dverse1"><span class="lnum">240</span>
 <span class="sd-cn">Suf.</span>
  The traitorous Warwick with the men of Bury</div>
<div class="dverse"><a class="lnum pginternal" href="#lnote-bcb241" id="lnum-bcb241">♦</a>
 Set all upon me, mighty sovereign.</div>

<div class="dverse1"><span class="sd-cn">Sal.</span>
 <span class="sd-inline">[<i>to the Commons, entering</i>]</span>
 Sirs, stand apart; the king shall know your mind.</div>
<div class="dverse">Dread Lord, the commons send you word by me,</div>
<div class="dverse"><a class="lnum pginternal" href="#lnote-bcb244" id="lnum-bcb244">♦</a>
 Unless Lord Suffolk straight be done to death,</div>
<div class="dverse"><span class="lnum">245</span> Or banished fair England’s territories,</div>
<div class="dverse">They will by violence tear him from your palace</div>
<div class="dverse">And torture him with grievous lingering death.</div>
<div class="dverse">They say, by him the good duke Humphrey died;</div>
<div class="dverse">They say, in him they fear your highness’ death;</div>
<div class="dverse"><span class="lnum">250</span> And mere instinct of love and loyalty,</div>
<div class="dverse">Free from a stubborn opposite intent,</div>
<div class="dverse">As being thought to contradict your liking,</div>
<div class="dverse">Makes them thus forward in his banishment.</div>
<div class="dverse">They say, in care of your most royal person,</div>
<div class="dverse"><span class="lnum">255</span> That if your highness should intend to sleep</div>
<div class="dverse">And charge that no man should disturb your rest</div>
<div class="dverse"><a class="lnum pginternal" href="#lnote-bcb257" id="lnum-bcb257">♦</a>
 In pain of your dislike or pain of death,</div>
<div class="dverse"><a class="lnum pginternal" href="#lnote-bcb258" id="lnum-bcb258">♦</a>
 Yet, notwithstanding such a strait edict,</div>
<div class="dverse">Were there a serpent seen, with forked tongue,</div>
<div class="dverse"><span class="lnum">260</span> That slily glided towards your majesty,</div>
<div class="dverse">It were but necessary you were waked,</div>
<div class="dverse"><a class="lnum pginternal" href="#lnote-bcb262" id="lnum-bcb262">♦</a>
 Lest, being suffer’d in that harmful slumber,</div>
<div class="dverse">The mortal worm might make the sleep eternal;</div>
<div class="dverse">And therefore do they cry, though you forbid,</div>
<div class="dverse"><a class="lnum pginternal" href="#lnote-bcb265" id="lnum-bcb265">265</a>
 That they will guard you, whether you will or no,</div>
<div class="dverse">From such fell serpents as false Suffolk is,</div>
<div class="dverse">With whose envenomed and fatal sting,</div>
<div class="dverse">Your loving uncle, twenty times his worth,</div>
<div class="dverse">They say, is shamefully bereft of life.</div>

<div class="dverse1"><span class="lnum">270</span>
 <span class="sd-cn">Commons [within].</span>
  An answer from the king, my Lord of Salisbury!</div>

<div class="dverse1"><span class="sd-cn">Suf.</span>
 ’Tis like the commons, rude unpolish’d hinds,</div>
<div class="dverse">Could send such message to their sovereign:</div>
<div class="dverse">But you, my lord, were glad to be employ’d,</div>
<div class="dverse">To show how quaint an orator you are:</div>
<div class="dverse"><span class="lnum">275</span> But all the honour Salisbury hath won</div>
<div class="dverse">Is, that he was the lord ambassador</div>
<div class="dverse">Sent from a sort of tinkers to the king.</div>

<div class="dverse1"><a class="lnum pginternal" href="#lnote-bcb278" id="lnum-bcb278">♦</a>
 <span class="sd-cn">Commons [within].</span>
  An answer from the king, or we will all break in!</div>

<div class="dverse1"><span class="sd-cn">King.</span>
 Go, Salisbury, and tell them all from me,</div>
<div class="dverse"><span class="lnum">280</span> I thank them for their tender loving care;</div>
<div class="dverse">And had I not been cited so by them,</div>
<div class="dverse">Yet did I purpose as they do entreat;</div>
<div class="dverse">For, sure, my thoughts do hourly prophesy</div>
<div class="dverse">Mischance unto my state by Suffolk’s means:</div>
<div class="dverse"><span class="lnum">285</span> And therefore, by His majesty I swear,</div>
<div class="dverse">Whose far unworthy deputy I am,</div>
<div class="dverse">He shall not breathe infection in this air</div>
<div class="dverse"><a class="lnum pginternal" href="#lnote-bcb288" id="lnum-bcb288">♦</a>
 But three days longer, on the pain of death.
 <span class="sd-verseend">[<i>Exit Salisbury.</i></span></div>

<div class="dverse1"><span class="sd-cn">Queen.</span>
 O Henry, let me plead for gentle Suffolk!</div>

<div class="dverse1"><span class="lnum">290</span>
 <span class="sd-cn">King.</span>
  Ungentle queen, to call him gentle Suffolk!</div>
<div class="dverse">No more, I say: if thou dost plead for him,</div>
<div class="dverse">Thou wilt but add increase unto my wrath.</div>
<div class="dverse">Had I but said, I would have kept my word,</div>
<div class="dverse">But when I swear, it is irrevocable.</div>
<div class="dverse"><span class="lnum">295</span> If, after three days’ space, thou here be’st found</div>
<div class="dverse">On any ground that I am ruler of,</div>
<div class="dverse">The world shall not be ransom for thy life.</div>
<div class="dverse">Come, Warwick, come, good Warwick, go with me;</div>
<div class="dverse"><a class="lnum pginternal" href="#lnote-bcb299" id="lnum-bcb299">♦</a>
 I have great matters to impart to thee.
 <span class="sd-verseend">[<i>Exeunt all but Queen and Suffolk.</i></span></div>

<div class="dverse1"><a class="lnum pginternal" href="#lnote-bcb300" id="lnum-bcb300">300</a>
 <span class="sd-cn">Queen.</span>
  Mischance and sorrow go along with you!</div>
<div class="dverse">Heart’s discontent and sour affliction</div>
<div class="dverse">Be playfellows to keep you company!</div>
<div class="dverse"><a class="lnum pginternal" href="#lnote-bcb303" id="lnum-bcb303">♦</a>
 There’s two of you; the devil make a third!</div>
<div class="dverse">And threefold vengeance tend upon your steps!</div>

<div class="dverse1"><span class="lnum">305</span>
 <span class="sd-cn">Suf.</span>
  Cease, gentle queen, these execrations</div>
<div class="dverse">And let thy Suffolk take his heavy leave.</div>

<div class="dverse1"><a class="lnum pginternal" href="#lnote-bcb307" id="lnum-bcb307">♦</a>
 <span class="sd-cn">Queen.</span>
  Fie, coward woman and soft-hearted wretch!</div>
<div class="dverse"><a class="lnum pginternal" href="#lnote-bcb308" id="lnum-bcb308">♦</a>
 Hast thou not spirit to curse thine enemy?</div>

<div class="dverse1"><span class="sd-cn">Suf.</span>
 A plague upon them! wherefore should I curse them?</div>
<div class="dverse"><span class="lnum">310</span> Would curses kill, as doth the mandrake’s groan,</div>
<div class="dverse"><a class="lnum pginternal" href="#lnote-bcb311" id="lnum-bcb311">♦</a>
 I would invent as bitter-searching terms,</div>
<div class="dverse">As curst, as harsh and horrible to hear,</div>
<div class="dverse">Deliver’d strongly through my fixed teeth,</div>
<div class="dverse">With full as many signs of deadly hate,</div>
<div class="dverse"><span class="lnum">315</span> As lean-faced Envy in her loathsome cave:</div>
<div class="dverse">My tongue should stumble in mine earnest words;</div>
<div class="dverse">Mine eyes should sparkle like the beaten flint;</div>
<div class="dverse"><a class="lnum pginternal" href="#lnote-bcb318" id="lnum-bcb318">♦</a>
 Mine hair be fix’d on end, as one distract;</div>
<div class="dverse">Ay, every joint should seem to curse and ban:</div>
<div class="dverse"><span class="lnum">320</span> And even now my burthen’d heart would break,</div>
<div class="dverse">Should I not curse them. Poison be their drink!</div>
<div class="dverse"><a class="lnum pginternal" href="#lnote-bcb322" id="lnum-bcb322">♦</a>
 Gall, worse than gall, the daintiest that they taste!</div>
<div class="dverse">Their sweetest shade a grove of cypress trees!</div>
<div class="dverse">Their chiefest prospect murdering basilisks!</div>
<div class="dverse"><a class="lnum pginternal" href="#lnote-bcb325" id="lnum-bcb325">325</a>
 Their softest touch as smart as lizards’ stings!</div>
<div class="dverse">Their music frightful as the serpent’s hiss,</div>
<div class="dverse"><a class="lnum pginternal" href="#lnote-bcb327" id="lnum-bcb327">♦</a>
 And boding screech-owls make the concert full!</div>
<div class="dverse"><a class="lnum pginternal" href="#lnote-bcb328" id="lnum-bcb328">♦</a>
 All the foul terrors in dark-seated hell—</div>

<div class="dverse1"><span class="sd-cn">Queen.</span>
 Enough, sweet Suffolk; thou torment’st thyself;</div>
<div class="dverse"><span class="lnum">330</span> And these dread curses, like the sun ’gainst glass,</div>
<div class="dverse"><a class="lnum pginternal" href="#lnote-bcb331" id="lnum-bcb331">♦</a>
 Or like an overcharged gun, recoil,</div>
<div class="dverse"><a class="lnum pginternal" href="#lnote-bcb332" id="lnum-bcb332">♦</a>
 And turn the force of them upon thyself.</div>

<div class="dverse1"><span class="sd-cn">Suf.</span>
 You bade me ban, and will you bid me leave?</div>
<div class="dverse">Now, by the ground that I am banish’d from,</div>
<div class="dverse"><span class="lnum">335</span> Well could I curse away a winter’s night,</div>
<div class="dverse">Though standing naked on a mountain top,</div>
<div class="dverse">Where biting cold would never let grass grow,</div>
<div class="dverse">And think it but a minute spent in sport.</div>

<div class="dverse1"><span class="sd-cn">Queen.</span>
 O, let me entreat thee cease. Give me thy hand,</div>
<div class="dverse"><span class="lnum">340</span> That I may dew it with my mournful tears;</div>
<div class="dverse">Nor let the rain of heaven wet this place,</div>
<div class="dverse"><a class="lnum pginternal" href="#lnote-bcb342" id="lnum-bcb342">♦</a>
 To wash away my woful monuments.</div>
<div class="dverse">O, could this kiss be printed in thy hand,</div>
<div class="dverse"><a class="lnum pginternal" href="#lnote-bcb344" id="lnum-bcb344">♦</a>
 That thou mightst think upon these by the seal,</div>
<div class="dverse"><a class="lnum pginternal" href="#lnote-bcb345" id="lnum-bcb345">345</a>
 Through whom a thousand sighs are breathed for thee!</div>
<div class="dverse">So, get thee gone, that I may know my grief;</div>
<div class="dverse"><a class="lnum pginternal" href="#lnote-bcb347" id="lnum-bcb347">♦</a>
 ’Tis but surmised whiles thou art standing by,</div>
<div class="dverse">As one that surfeits thinking on a want.</div>
<div class="dverse">I will repeal thee, or, be well assured,</div>
<div class="dverse"><span class="lnum">350</span> Adventure to be banished myself:</div>
<div class="dverse">And banished I am, if but from thee.</div>
<div class="dverse">Go; speak not to me; even now be gone.</div>
<div class="dverse">O, go not yet! Even thus two friends condemn’d</div>
<div class="dverse">Embrace and kiss and take ten thousand leaves,</div>
<div class="dverse"><span class="lnum">355</span> Loather a hundred times to part than die.</div>
<div class="dverse">Yet now farewell; and farewell life with thee!</div>

<div class="dverse1"><span class="sd-cn">Suf.</span>
 Thus is poor Suffolk ten times banished;</div>
<div class="dverse">Once by the king, and three times thrice by thee.</div>
<div class="dverse"><a class="lnum pginternal" href="#lnote-bcb359" id="lnum-bcb359">♦</a>
 ’Tis not the land I care for, wert thou thence;</div>
<div class="dverse"><span class="lnum">360</span> A wilderness is populous enough,</div>
<div class="dverse">So Suffolk had thy heavenly company:</div>
<div class="dverse">For where thou art, there is the world itself,</div>
<div class="dverse">With every several pleasure in the world,</div>
<div class="dverse">And where thou art not, desolation.</div>
<div class="dverse"><span class="lnum">365</span> I can no more: live thou to joy thy life;</div>
<div class="dverse"><a class="lnum pginternal" href="#lnote-bcb366" id="lnum-bcb366">♦</a>
 Myself no joy in nought but that thou livest.</div>

<div class="sd-entry"><i>Enter</i>
<span class="smcaps">V<span>AUX</span>.</span></div>

<div class="dverse1"><a class="lnum pginternal" href="#lnote-bcb367" id="lnum-bcb367">♦</a>
 <span class="sd-cn">Queen.</span>
  Whither goes Vaux so fast? what news, I prithee?</div>

<div class="dverse1"><span class="sd-cn">Vaux.</span>
 To signify unto his majesty</div>
<div class="dverse"><a class="lnum pginternal" href="#lnote-bcb369" id="lnum-bcb369">♦</a>
 That Cardinal Beaufort is at point of death;</div>
<div class="dverse"><span class="lnum">370</span> For suddenly a grievous sickness took him,</div>
<div class="dverse">That makes him gasp and stare and catch the air,</div>
<div class="dverse">Blaspheming God and cursing men on earth.</div>
<div class="dverse"><a class="lnum pginternal" href="#lnote-bcb373" id="lnum-bcb373">♦</a>
 Sometime he talks as if Duke Humphrey’s ghost</div>
<div class="dverse">Were by his side; sometime he calls the king</div>
<div class="dverse"><span class="lnum">375</span> And whispers to his pillow as to him</div>
<div class="dverse">The secrets of his overcharged soul:</div>
<div class="dverse">And I am sent to tell his majesty</div>
<div class="dverse">That even now he cries aloud for him.</div>

<div class="dverse1"><a class="lnum pginternal" href="#lnote-bcb379" id="lnum-bcb379">♦</a>
 <span class="sd-cn">Queen.</span>
 Go tell this heavy message to the king.
  <span class="sd-verseend">[<i>Exit Vaux.</i></span></div>
<div class="dverse"><span class="lnum">380</span> Ay me! what is this world! what news are these!</div>
<div class="dverse"><a class="lnum pginternal" href="#lnote-bcb381" id="lnum-bcb381">♦</a>
 But wherefore grieve I at an hour’s poor loss,</div>
<div class="dverse">Omitting Suffolk’s exile, my soul’s treasure?</div>
<div class="dverse">Why only, Suffolk, mourn I not for thee,</div>
<div class="dverse">And with the southern clouds contend in tears,</div>
<div class="dverse"><span class="lnum">385</span> Theirs for the earth’s increase, mine for my sorrows?</div>
<div class="dverse">Now get thee hence: the king, thou know’st, is coming;</div>
<div class="dverse">If thou be found by me, thou art but dead.</div>

<div class="dverse1"><span class="sd-cn">Suf.</span>
 If I depart from thee, I cannot live;</div>
<div class="dverse">And in thy sight to die, what were it else</div>
<div class="dverse"><span class="lnum">390</span> But like a pleasant slumber in thy lap?</div>
<div class="dverse">Here could I breathe my soul into the air,</div>
<div class="dverse">As mild and gentle as the cradle-babe</div>
<div class="dverse"><a class="lnum pginternal" href="#lnote-bcb393" id="lnum-bcb393">♦</a>
 Dying with mother’s dug between its lips:</div>
<div class="dverse">Where, from thy sight, I should be raging mad</div>
<div class="dverse"><span class="lnum">395</span> And cry out for thee to close up mine eyes,</div>
<div class="dverse">To have thee with thy lips to stop my mouth;</div>
<div class="dverse"><a class="lnum pginternal" href="#lnote-bcb397" id="lnum-bcb397">♦</a>
 So shouldst thou either turn my flying soul,</div>
<div class="dverse">Or I should breathe it so into thy body,</div>
<div class="dverse"><a class="lnum pginternal" href="#lnote-bcb399" id="lnum-bcb399">♦</a>
 And then it lived in sweet Elysium.</div>
<div class="dverse"><span class="lnum">400</span> To die by thee were but to die in jest;</div>
<div class="dverse">From thee to die were torture more than death:</div>
<div class="dverse">O, let me stay, befall what may befall!</div>

<div class="dverse1"><a class="lnum pginternal" href="#lnote-bcb403" id="lnum-bcb403">♦</a>
 <span class="sd-cn">Queen.</span>
  Away! though parting be a fretful corrosive,</div>
<div class="dverse">It is applied to a deathful wound.</div>
<div class="dverse"><span class="lnum">405</span> To France, sweet Suffolk: let me hear from thee;</div>
<div class="dverse"><a class="lnum pginternal" href="#lnote-bcb406" id="lnum-bcb406">♦</a>
 For wheresoe’er thou art in this world’s globe,</div>
<div class="dverse">I’ll have an Iris that shall find thee out.</div>

<div class="dverse1"><span class="sd-cn">Suf.</span>
 I go.</div>

<div class="dverse1"><a class="lnum pginternal" href="#lnote-bcb408" id="lnum-bcb408">♦</a>
 <span class="sd-cn">Queen.</span>
 <span class="i02"> </span>
 And take my heart with thee.</div>

<div class="dverse1"><a class="lnum pginternal" href="#lnote-bcb409" id="lnum-bcb409">♦</a>
 <span class="sd-cn">Suf.</span>
  A jewel, lock’d into the wofull’st cask</div>
<div class="dverse"><span class="lnum">410</span> That ever did contain a thing of worth.</div>
<div class="dverse">Even as a splitted bark, so sunder we:</div>
<div class="dverse">This way fall I to death.</div>

<div class="dverse1"><a class="lnum pginternal" href="#lnote-bcb412" id="lnum-bcb412">♦</a>
 <span class="sd-cn">Queen.</span>
<span class="i10"> </span> This way for me.
<span class="sd-verseend">[<i>Exeunt severally.</i></span></div>

<div class="section">
<h4 class="h4main"><span class="dnavigate">bcc</span>
<span class="smcaps">S<span>CENE</span></span> III. <i>A bedchamber</i>.</h4>

<div class="sd-schg"><i>Enter the</i> <span class="smcaps">K<span>ING</span>,</span> <span class="smcaps">S<span>ALISBURY</span>,</span> <span class="smcaps">W<span>ARWICK</span>,</span> <i>to the</i> <span class="smcaps">C<span>ARDINAL</span></span> <i>in bed</i>.</div>
</div>

<div class="dverse1"><a class="lnum pginternal" href="#lnote-bcc001" id="lnum-bcc001">♦</a>
 <span class="sd-cn">King.</span>
  How fares my lord? speak, Beaufort, to thy sovereign.</div>

<div class="dverse1"><span class="sd-cn">Car.</span>
 If thou be’st death, I’ll give thee England’s treasure,</div>
<div class="dverse">Enough to purchase such another island,</div>
<div class="dverse"><a class="lnum pginternal" href="#lnote-bcc004" id="lnum-bcc004">♦</a>
 So thou wilt let me live, and feel no pain.</div>

<div class="dverse1"><span class="lnum">5</span>
 <span class="sd-cn">King.</span>
  Ah, what a sign it is of evil life,</div>
<div class="dverse">Where death’s approach is seen so terrible!</div>

<div class="dverse1"><span class="sd-cn">War.</span>
 Beaufort, it is thy sovereign speaks to thee.</div>

<div class="dverse1"><span class="sd-cn">Car.</span>
 Bring me unto my trial when you will.</div>
<div class="dverse"><a class="lnum pginternal" href="#lnote-bcc009" id="lnum-bcc009">♦</a>
 Died he not in his bed? where should he die?</div>
<div class="dverse"><a class="lnum pginternal" href="#lnote-bcc010" id="lnum-bcc010">10</a>
 Can I make men live, whether they will or no?</div>
<div class="dverse">O, torture me no more! I will confess.</div>
<div class="dverse">Alive again? then show me where he is:</div>
<div class="dverse">I’ll give a thousand pound to look upon him.</div>
<div class="dverse">He hath no eyes, the dust hath blinded them.</div>
<div class="dverse"><span class="lnum">15</span> Comb down his hair; look, look! it stands upright,</div>
<div class="dverse">Like lime-twigs set to catch my winged soul.</div>
<div class="dverse">Give me some drink; and bid the apothecary</div>
<div class="dverse">Bring the strong poison that I bought of him.</div>

<div class="dverse1"><span class="sd-cn">King.</span>
 O thou eternal Mover of the heavens,</div>
<div class="dverse"><span class="lnum">20</span> Look with a gentle eye upon this wretch!</div>
<div class="dverse"><a class="lnum pginternal" href="#lnote-bcc021" id="lnum-bcc021">♦</a>
 O, beat away the busy meddling fiend</div>
<div class="dverse"><a class="lnum pginternal" href="#lnote-bcc022" id="lnum-bcc022">♦</a>
 That lays strong siege unto this wretch’s soul</div>
<div class="dverse">And from his bosom purge this black despair!</div>

<div class="dverse1"><span class="sd-cn">War.</span>
 See, how the pangs of death do make him grin!</div>

<div class="dverse1"><span class="lnum">25</span>
 <span class="sd-cn">Sal.</span>
  Disturb him not; let him pass peaceably.</div>

<div class="dverse1"><a class="lnum pginternal" href="#lnote-bcc026" id="lnum-bcc026">♦</a>
 <span class="sd-cn">King.</span>
  Peace to his soul, if God’s good pleasure be!</div>
<div class="dverse">Lord cardinal, if thou think’st on heaven’s bliss,</div>
<div class="dverse"><a class="lnum pginternal" href="#lnote-bcc028" id="lnum-bcc028">♦</a>
 Hold up thy hand, make signal of thy hope.</div>
<div class="dverse">He dies, and makes no sign. O God, forgive him!</div>

<div class="dverse1"><span class="lnum">30</span>
 <span class="sd-cn">War.</span>
  So bad a death argues a monstrous life.</div>

<div class="dverse1"><span class="sd-cn">King.</span>
 Forbear to judge, for we are sinners all.</div>
<div class="dverse">Close up his eyes and draw the curtain close;</div>
<div class="dverse">And let us all to meditation. <span class="sd-verseend">[<i>Exeunt.</i></span></div>

<div class="section">
<h3 class="h3main">ACT IV.</h3>

<h4 class="h4main"><span class="dnavigate">bda</span>
<span class="smcaps">S<span>CENE</span></span> I. <i>The coast of
Kent</i>.</h4>

<div class="sd-schg"><i>Alarum. Fight at Sea. Ordnance
goes off. Enter a</i> Captain, <i>a</i> Master, <i>a</i> Master’s-Mate,
<span class="smcaps">W<span>ALTER</span></span> <span class="smcaps">W<span>HITMORE</span>,</span> <i>and others; with them</i>
<span class="smcaps">S<span>UFFOLK</span>,</span> <i>and others,
prisoners</i>.</div></div>

<div class="dverse1"><a class="lnum pginternal" href="#lnote-bda001" id="lnum-bda001">♦</a>
 <span class="sd-cn">Cap.</span>
  The gaudy, blabbing and remorseful day</div>
<div class="dverse">Is crept into the bosom of the sea;</div>
<div class="dverse">And now loud-howling wolves arouse the jades</div>
<div class="dverse">That drag the tragic melancholy night;</div>
<div class="dverse"><span class="lnum">5</span> Who, with their drowsy, slow and flagging wings,</div>
<div class="dverse"><a class="lnum pginternal" href="#lnote-bda006" id="lnum-bda006">♦</a>
 Clip dead men’s graves and from their misty jaws</div>
<div class="dverse">Breathe foul contagious darkness in the air.</div>
<div class="dverse">Therefore bring forth the soldiers of our prize;</div>
<div class="dverse">For, whilst our pinnace anchors in the Downs,</div>
<div class="dverse"><span class="lnum">10</span> Here shall they make their ransom on the sand,</div>
<div class="dverse"><a class="lnum pginternal" href="#lnote-bda011" id="lnum-bda011">♦</a>
 Or with their blood stain this discoloured shore.</div>
<div class="dverse">Master, this prisoner freely give I thee;</div>
<div class="dverse">And thou that art his mate, make boot of this;</div>
<div class="dverse"><a class="lnum pginternal" href="#lnote-bda014" id="lnum-bda014">♦</a>
 The other, Walter Whitmore, is thy share.</div>

<div class="dverse1"><span class="lnum">15</span>
 <span class="sd-cn">First Gent.</span>
  What is my ransom, master? let me know.</div>

<div class="dverse1"><span class="sd-cn">Mast.</span>
 A thousand crowns, or else lay down your head.</div>

<div class="dverse1"><a class="lnum pginternal" href="#lnote-bda018" id="lnum-bda018">♦</a>
 <span class="sd-cn">Mate.</span>
  And so much shall you give, or off goes yours.</div>

<div class="dverse1"><span class="sd-cn">Cap.</span>
 What, think you much to pay two thousand crowns,</div>
<div class="dverse">And bear the name and port of gentlemen?</div>
<div class="dverse"><a class="lnum pginternal" href="#lnote-bda020" id="lnum-bda020">20</a>
 Cut both the villains’ throats; for die you shall:</div>
<div class="dverse"><a class="lnum pginternal" href="#lnote-bda021" id="lnum-bda021">♦</a>
 The lives of those which we have lost in fight</div>
<div class="dverse">Be counterpoised with such a petty sum!</div>

<div class="dverse1"><span class="sd-cn">First Gent.</span>
 I’ll give it, sir; and therefore spare my life.</div>

<div class="dverse1"><span class="sd-cn">Sec. Gent.</span>
 And so will I and write home for it straight.</div>

<div class="dverse1"><span class="lnum">25</span>
 <span class="sd-cn">Whit.</span>
  I lost mine eye in laying the prize aboard</div>
<div class="dverse"><a class="lnum pginternal" href="#lnote-bda026" id="lnum-bda026">♦</a>
And therefore to revenge it, shalt thou die; <span class="sd-verseend">[<i>To Suf.</i></span></div>
<div class="dverse">And so should these, if I might have my will.</div>

<div class="dverse1"><span class="sd-cn">Cap.</span>
 Be not so rash; take ransom, let him live.</div>

<div class="dverse1"><a class="lnum pginternal" href="#lnote-bda029" id="lnum-bda029">♦</a>
 <span class="sd-cn">Suf.</span>
  Look on my George; I am a gentleman:</div>
<div class="dverse"><span class="lnum">30</span> Rate me at what thou wilt, thou shalt be paid.</div>

<div class="dverse1"><span class="sd-cn">Whit.</span>
 And so am I; my name is Walter Whitmore.</div>
<div class="dverse"><a class="lnum pginternal" href="#lnote-bda032" id="lnum-bda032">♦</a>
 How now! why start’st thou? what, doth death affright?</div>

<div class="dverse1"><span class="sd-cn">Suf.</span>
 Thy name affrights me, in whose sound is death.</div>
<div class="dverse">A cunning man did calculate my birth</div>
<div class="dverse"><span class="lnum">35</span> And told me that by water I should die:</div>
<div class="dverse">Yet let not this make thee be bloody-minded;</div>
<div class="dverse">Thy name is Gaultier, being rightly sounded.</div>

<div class="dverse1"><span class="sd-cn">Whit.</span>
 Gaultier or Walter, which it is, I care not:</div>
<div class="dverse"><a class="lnum pginternal" href="#lnote-bda039" id="lnum-bda039">♦</a>
 Never yet did base dishonour blur our name,</div>
<div class="dverse"><span class="lnum">40</span> But with our sword we wiped away the blot;</div>
<div class="dverse">Therefore, when merchant-like I sell revenge,</div>
<div class="dverse">Broke be my sword, my arms torn and defaced,</div>
<div class="dverse"><a class="lnum pginternal" href="#lnote-bda043" id="lnum-bda043">♦</a>
 And I proclaim’d a coward through the world!</div>

<div class="dverse1"><span class="sd-cn">Suf.</span>
 Stay, Whitmore; for thy prisoner is a prince,</div>
<div class="dverse"><span class="lnum">45</span> The Duke of Suffolk, William de la Pole.</div>

<div class="dverse1"><a class="lnum pginternal" href="#lnote-bda046" id="lnum-bda046">♦</a>
 <span class="sd-cn">Whit.</span>
  The Duke of Suffolk muffled up in rags!</div>

<div class="dverse1"><span class="sd-cn">Suf.</span>
 Ay, but these rags are no part of the duke:</div>
<div class="dverse"><a class="lnum pginternal" href="#lnote-bda048" id="lnum-bda048">♦</a>
 Jove sometime went disguised, and why not I?</div>

<div class="dverse1"><span class="sd-cn">Cap.</span>
 But Jove was never slain, as thou shalt be.</div>

<div class="dverse1"><a class="lnum pginternal" href="#lnote-bda050" id="lnum-bda050">50</a>
 <span class="sd-cn">Suf.</span>
  Obscure and lowly swain, King Henry’s blood,</div>
<div class="dverse"><a class="lnum pginternal" href="#lnote-bda051" id="lnum-bda051">♦</a>
 The honourable blood of Lancaster,</div>
<div class="dverse"><a class="lnum pginternal" href="#lnote-bda052" id="lnum-bda052">♦</a>
 Must not be shed by such a jaded groom.</div>
<div class="dverse">Hast thou not kiss’d thy hand and held my stirrup?</div>
<div class="dverse"><a class="lnum pginternal" href="#lnote-bda054" id="lnum-bda054">♦</a>
 Bare-headed plodded by my foot-cloth mule</div>
<div class="dverse"><span class="lnum">55</span> And thought thee happy when I shook my head?</div>
<div class="dverse">How often hast thou waited at my cup,</div>
<div class="dverse">Fed from my trencher, kneel’d down at the board,</div>
<div class="dverse">When I have feasted with Queen Margaret?</div>
<div class="dverse">Remember it and let it make thee crest-fall’n,</div>
<div class="dverse"><span class="lnum">60</span> Ay, and allay this thy abortive pride;</div>
<div class="dverse">How in our voiding lobby hast thou stood</div>
<div class="dverse">And duly waited for my coming forth?</div>
<div class="dverse"><a class="lnum pginternal" href="#lnote-bda063" id="lnum-bda063">♦</a>
 This hand of mine hath writ in thy behalf</div>
<div class="dverse">And therefore shall it charm thy riotous tongue.</div>

<div class="dverse1"><a class="lnum pginternal" href="#lnote-bda065" id="lnum-bda065">65</a>
 <span class="sd-cn">Whit.</span>
  Speak, captain, shall I stab the forlorn swain?</div>

<div class="dverse1"><span class="sd-cn">Cap.</span>
 First let my words stab him, as he hath me.</div>

<div class="dverse1"><span class="sd-cn">Suf.</span>
 Base slave, thy words are blunt and so art thou.</div>

<div class="dverse1"><span class="sd-cn">Cap.</span>
 Convey him hence and on our long-boat’s side</div>
<div class="dverse">Strike off his head.</div>

<div class="dverse1"><a class="lnum pginternal" href="#lnote-bda069" id="lnum-bda069">♦</a><span class="sd-cn">Suf.</span>
 <span class="i08"> </span>
 Thou darest not, for thy own.</div>

<div class="dverse1"><span class="sd-cn">Cap.</span>
 Yes, Pole.</div>

<div class="dverse1"><span class="sd-cn">Suf.</span>
 <span class="i06"> </span> Pole!</div>

<div class="dverse1"><a class="lnum pginternal" href="#lnote-bda070" id="lnum-bda070">70</a>
 <span class="sd-cn">Cap.</span>
 <span class="i09"> </span> Pool! Sir Pool! lord!</div>
<div class="dverse"><a class="lnum pginternal" href="#lnote-bda071" id="lnum-bda071">♦</a>
 Ay, kennel, puddle, sink; whose filth and dirt</div>
<div class="dverse">Troubles the silver spring where England drinks.</div>
<div class="dverse">Now will I dam up this thy yawning mouth</div>
<div class="dverse"><a class="lnum pginternal" href="#lnote-bda074" id="lnum-bda074">♦</a>
 For swallowing the treasure of the realm:</div>
<div class="dverse"><span class="lnum">75</span> Thy lips that kiss’d the queen shall sweep the ground;</div>
<div class="dverse">And thou that smiledst at good Duke Humphrey’s death</div>
<div class="dverse"><a class="lnum pginternal" href="#lnote-bda077" id="lnum-bda077">♦</a>
 Against the senseless winds shalt grin in vain,</div>
<div class="dverse">Who in contempt shall hiss at thee again:</div>
<div class="dverse">And wedded be thou to the hags of hell,</div>
<div class="dverse"><span class="lnum">80</span> For daring to affy a mighty lord</div>
<div class="dverse">Unto the daughter of a worthless king,</div>
<div class="dverse"><a class="lnum pginternal" href="#lnote-bda082" id="lnum-bda082">♦</a>
 Having neither subject, wealth, nor diadem.</div>
<div class="dverse">By devilish policy art thou grown great</div>
<div class="dverse"><a class="lnum pginternal" href="#lnote-bda084" id="lnum-bda084">♦</a>
 And, like ambitious Sylla, overgorged</div>
<div class="dverse"><a class="lnum pginternal" href="#lnote-bda085" id="lnum-bda085">85</a>
 With gobbets of thy mother’s bleeding heart.</div>
<div class="dverse">By thee Anjou and Maine were sold to France,</div>
<div class="dverse">The false revolting Normans thorough thee</div>
<div class="dverse">Disdain to call us lord, and Picardy</div>
<div class="dverse">Hath slain their governors, surprised our forts</div>
<div class="dverse"><span class="lnum">90</span> And sent the ragged soldiers wounded home.</div>
<div class="dverse">The princely Warwick, and the Nevils all,</div>
<div class="dverse">Whose dreadful swords were never drawn in vain,</div>
<div class="dverse"><a class="lnum pginternal" href="#lnote-bda093" id="lnum-bda093">♦</a>
 As hating thee, are rising up in arms:</div>
<div class="dverse">And now the house of York, thrust from the crown</div>
<div class="dverse"><span class="lnum">95</span> By shameful murder of a guiltless king</div>
<div class="dverse"><a class="lnum pginternal" href="#lnote-bda096" id="lnum-bda096">♦</a>
 And lofty proud encroaching tyranny,</div>
<div class="dverse">Burns with revenging fire; whose hopeful colours</div>
<div class="dverse"><a class="lnum pginternal" href="#lnote-bda098" id="lnum-bda098">♦</a>
 Advance our half-faced sun, striving to shine,</div>
<div class="dverse">Under the which is writ ‘Invitis nubibus.’</div>
<div class="dverse"><span class="lnum">100</span> The commons here in Kent are up in arms:</div>
<div class="dverse">And, to conclude, reproach and beggary</div>
<div class="dverse"><a class="lnum pginternal" href="#lnote-bda102" id="lnum-bda102">♦</a>
 Is crept into the palace of our king,</div>
<div class="dverse">And all by thee. Away! convey him hence.</div>

<div class="dverse1"><span class="sd-cn">Suf.</span>
 O that I were a god, to shoot forth thunder</div>
<div class="dverse"><span class="lnum">105</span> Upon these paltry, servile, abject drudges!</div>
<div class="dverse">Small things make base men proud: this villain here,</div>
<div class="dverse"><a class="lnum pginternal" href="#lnote-bda107" id="lnum-bda107">♦</a>
 Being captain of a pinnace, threatens more</div>
<div class="dverse"><a class="lnum pginternal" href="#lnote-bda108" id="lnum-bda108">♦</a>
 Than Bargulus the strong Illyrian pirate.</div>
<div class="dverse">Drones suck not eagles’ blood but rob bee-hives:</div>
<div class="dverse"><a class="lnum pginternal" href="#lnote-bda110" id="lnum-bda110">110</a>
 It is impossible that I should die</div>
<div class="dverse">By such a lowly vassal as thyself.</div>
<div class="dverse">Thy words move rage and not remorse in me:</div>
<div class="dverse">I go of message from the queen to France;</div>
<div class="dverse">I charge thee waft me safely cross the Channel.</div>

<div class="dverse1"><a class="lnum pginternal" href="#lnote-bda115" id="lnum-bda115">115</a>
 <span class="sd-cn">Cap.</span>
  Walter,—</div>

<div class="dverse1"><span class="sd-cn">Whit.</span>
 Come, Suffolk, I must waft thee to thy death.</div>

<div class="dverse1"><a class="lnum pginternal" href="#lnote-bda117" id="lnum-bda117">♦</a>
 <span class="sd-cn">Suf.</span>
  Gelidus timor occupat artus: it is thee I fear.</div>

<div class="dverse1"><a class="lnum pginternal" href="#lnote-bda118" id="lnum-bda118">♦</a>
 <span class="sd-cn">Whit.</span>
  Thou shalt have cause to fear before I leave thee.</div>
<div class="dverse">What, are ye daunted now? now will ye stoop?</div>

<div class="dverse1"><span class="lnum">120</span>
 <span class="sd-cn">First Gent.</span>
  My gracious lord, entreat him, speak him fair.</div>

<div class="dverse1"><span class="sd-cn">Suf.</span>
 Suffolk’s imperial tongue is stern and rough,</div>
<div class="dverse">Used to command, untaught to plead for favour.</div>
<div class="dverse">Far be it we should honour such as these</div>
<div class="dverse">With humble suit: no, rather let my head</div>
<div class="dverse"><span class="lnum">125</span> Stoop to the block than these knees bow to any</div>
<div class="dverse">Save to the God of heaven and to my king;</div>
<div class="dverse">And sooner dance upon a bloody pole</div>
<div class="dverse"><a class="lnum pginternal" href="#lnote-bda128" id="lnum-bda128">♦</a>
 Than stand uncover’d to the vulgar groom.</div>
<div class="dverse"><a class="lnum pginternal" href="#lnote-bda129" id="lnum-bda129">♦</a>
 True nobility is exempt from fear:</div>
<div class="dverse"><span class="lnum">130</span> More can I bear than you dare execute.</div>

<div class="dverse1"><span class="sd-cn">Cap.</span>
 Hale him away, and let him talk no more.</div>

<div class="dverse1"><a class="lnum pginternal" href="#lnote-bda132" id="lnum-bda132">♦</a>
 <span class="sd-cn">Suf.</span>
  Come, soldiers, show what cruelty ye can,</div>
<div class="dverse">That this my death may never be forgot!</div>
<div class="dverse">Great men oft die by vile bezonians:</div>
<div class="dverse"><a class="lnum pginternal" href="#lnote-bda135" id="lnum-bda135">135</a>
 A Roman sworder and banditto slave</div>
<div class="dverse"><a class="lnum pginternal" href="#lnote-bda136" id="lnum-bda136">♦</a>
 Murder’d sweet Tully; Brutus’ bastard hand</div>
<div class="dverse"><a class="lnum pginternal" href="#lnote-bda137" id="lnum-bda137">♦</a>
 Stabb’d Julius Cæsar; savage islanders</div>

<div class="dverse"><a class="lnum pginternal" href="#lnote-bda138" id="lnum-bda138">♦</a>
 Pompey the Great; and Suffolk dies by pirates.
 <span class="sd-verseend">[<i>Exeunt Whitmore and others with Suffolk.</i></span></div>

<div class="dverse1"><span class="sd-cn">Cap.</span>
 And as for these whose ransom we have set,</div>
<div class="dverse"><span class="lnum">140</span> It is our pleasure one of them depart:</div>
<div class="dverse"><a class="lnum pginternal" href="#lnote-bda141" id="lnum-bda141">♦</a>
 Therefore come you with us and let him go.
 <span class="sd-verseend">[<i>Exeunt all but the First Gentleman.</i></span></div>

<div class="sd-entry"><i>Re-enter</i> <span class="smcaps">W<span>HITMORE</span></span> <i>with</i> <span class="smcaps">S<span>UFFOLK’S</span></span> <i>body</i>.</div>

<div class="dverse1"><a class="lnum pginternal" href="#lnote-bda142" id="lnum-bda142">♦</a>
 <span class="sd-cn">Whit.</span>
  There let his head and lifeless body lie,</div>
<div class="dverse"><a class="lnum pginternal" href="#lnote-bda143" id="lnum-bda143">♦</a>
Until the queen his mistress bury it. <span class="sd-verseend">[<i>Exit.</i></span></div>

<div class="dverse1"><span class="sd-cn">First Gent.</span>
 O barbarous and bloody spectacle!</div>
<div class="dverse"><span class="lnum">145</span> His body will I bear unto the king:</div>
<div class="dverse">If he revenge it not, yet will his friends;</div>
<div class="dverse"><a class="lnum pginternal" href="#lnote-bda147" id="lnum-bda147">♦</a>
 So will the queen, that living held him dear.
 <span class="sd-verseend">[<i>Exit with the body.</i></span></div>

<div class="section">
<h4 class="h4main"><span class="dnavigate">bdb</span>
<span class="smcaps">S<span>CENE</span></span> II. <i>Blackheath</i>.</h4>

<div class="sd-entry"><i>Enter</i> <span class="smcaps">G<span>EORGE</span></span> <span class="smcaps">B<span>EVIS</span></span> <i>and</i>
<span class="smcaps">J<span>OHN</span></span> <span class="smcaps">H<span>OLLAND</span>.</span></div>
</div>

<div class="dprose1"><a class="lnum pginternal" href="#lnote-bdb001" id="lnum-bdb001">♦</a>
 <span class="sd-cn">Bevis.</span>
Come, and get thee a sword, though made of a lath: they have been up these two days.</div>

<div class="dprose1"><a class="lnum pginternal" href="#lnote-bdb003" id="lnum-bdb003">♦</a>
 <span class="sd-cn">Holl.</span>
They have the more need to sleep now, then.</div>

<div class="dprose1"><span class="sd-cn">Bevis.</span>
I tell thee, Jack Cade the clothier means to <span class="lnum">5</span>
dress the commonwealth, and turn it, and set a new nap upon it.</div>

<div class="dprose1"><a class="lnum pginternal" href="#lnote-bdb007" id="lnum-bdb007">♦</a>
 <span class="sd-cn">Holl.</span>
So he had need, for ’tis threadbare. Well, I say it <a class="lnum pginternal" href="#lnote-bdb008" id="lnum-bdb008">♦</a>
was never merry world in England since gentlemen came up.</div>

<div class="dprose1"><span class="sd-cn">Bevis.</span>
O miserable age! virtue is not regarded in <span class="lnum">10</span> handicrafts-men.</div>

<div class="dprose1"><span class="sd-cn">Holl.</span>
 The nobility think scorn to go in leather aprons.</div>

<div class="dprose1"><span class="sd-cn">Bevis.</span>
 Nay, more, the king’s council are no good workmen.</div>

<div class="dprose1"><span class="sd-cn">Holl.</span>
True; and yet it is said, labour in thy vocation; <a class="lnum pginternal" href="#lnote-bdb015" id="lnum-bdb015">15</a>
which is as much to say as, let the magistrates be labouring men; and therefore should we be magistrates.</div>

<div class="dprose1"><span class="sd-cn">Bevis.</span>
Thou hast hit it; for there’s no better sign of a brave mind than a hard hand.</div>

<div class="dprose1"><span class="sd-cn">Holl.</span>
I see them! I see them! There’s Best’s son, <span class="lnum">20</span> the tanner of Wingham,—</div>

<div class="dprose1"><span class="sd-cn">Bevis.</span>
He shall have the skin of our enemies, to make dog’s-leather of.</div>

<div class="dprose1"><span class="sd-cn">Holl.</span>
 And Dick the butcher,—</div>

<div class="dprose1"><span class="sd-cn">Bevis.</span>
Then is sin struck down like an ox, and iniquity’s <span class="lnum">25</span> throat cut like a calf.</div>

<div class="dprose1"><a class="lnum pginternal" href="#lnote-bdb026" id="lnum-bdb026">♦</a>
 <span class="sd-cn">Holl.</span>  And Smith the weaver,—</div>

<div class="dprose1"><span class="sd-cn">Bevis.</span>
 Argo, their thread of life is spun.</div>

<div class="dprose1"><a class="lnum pginternal" href="#lnote-bdb028" id="lnum-bdb028">♦</a>
 <span class="sd-cn">Holl.</span>
 Come, come, let’s fall in with them.</div>

<div class="sd-entry"><i>Drum. Enter</i> <span class="smcaps">C<span>ADE</span>,</span> <span class="smcaps">D<span>ICK</span></span> Butcher, <span class="smcaps">S<span>MITH</span></span> <i>the Weaver, and a Sawyer, with infinite numbers</i>.</div>

<div class="dprose1"><a class="lnum pginternal" href="#lnote-bdb030" id="lnum-bdb030">30</a>
 <span class="sd-cn">Cade.</span>
We John Cade, so termed of our supposed father,—</div>

<div class="dprose1"><a class="lnum pginternal" href="#lnote-bdb031" id="lnum-bdb031">♦</a>
<span class="sd-cn">Dick.</span>
<span class="sd-inline">[<i>Aside</i>]</span>
Or rather, of stealing a cade of herrings.</div>

<div class="dprose1"><a class="lnum pginternal" href="#lnote-bdb032" id="lnum-bdb032">♦</a>
 <span class="sd-cn">Cade.</span>
For our enemies shall fall before us, inspired <a class="lnum pginternal" href="#lnote-bdb033" id="lnum-bdb033">♦</a>
with the spirit of putting down kings and princes,—Command silence.</div>

<div class="dprose1"><span class="lnum">35</span>
 <span class="sd-cn">Dick.</span>  Silence!</div>

<div class="dprose1"><span class="sd-cn">Cade.</span>
 My father was a Mortimer,—</div>

<div class="dprose1"><span class="sd-cn">Dick.</span>
 <span class="sd-inline">[<i>Aside</i>]</span>
 He was an honest man, and a good bricklayer.</div>

<div class="dprose1"><span class="sd-cn">Cade.</span>
 My mother a Plantagenet,—</div>

<div class="dprose1"><span class="lnum">40</span>
 <span class="sd-cn">Dick.</span>
 <span class="sd-inline">[<i>Aside</i>]</span> I knew her well; she was a midwife. </div>

<div class="dprose1"><span class="sd-cn">Cade.</span>
 My wife descended of the Lacies,—</div>

<div class="dprose1"><span class="sd-cn">Dick.</span>
 <span class="sd-inline">[<i>Aside</i>]</span>
 She was, indeed, a pedler’s daughter, and sold many laces.</div>

<div class="dprose1"><a class="lnum pginternal" href="#lnote-bdb044" id="lnum-bdb044">♦</a>
<span class="sd-cn">Smith.</span>
<span class="sd-inline">[<i>Aside</i>]</span>
But now of late, not able to travel with <span class="lnum">45</span>
her furred pack, she washes bucks here at home.</div>

<div class="dprose1"><span class="sd-cn">Cade.</span>
Therefore am I of an honourable house.</div>

<div class="dprose1"><span class="sd-cn">Dick.</span>
<span class="sd-inline">[<i>Aside</i>]</span>
Ay, by my faith, the field is honourable; and there was he born, under a hedge, for his father had never a house but the cage.</div>

<div class="dprose1"><span class="lnum">50</span>
 <span class="sd-cn">Cade.</span>  Valiant I am.</div>

<div class="dprose1"><span class="sd-cn">Smith.</span>
 <span class="sd-inline">[<i>Aside</i>]</span> A’ must needs; for beggary is valiant.</div>

<div class="dprose1"><span class="sd-cn">Cade.</span>
 I am able to endure much.</div>

<div class="dprose1"><span class="sd-cn">Dick.</span>
 <span class="sd-inline">[<i>Aside</i>]</span> No question of that; for I have seen him whipped three market-days together.</div>

<div class="dprose1"><span class="lnum">55</span>
 <span class="sd-cn">Cade.</span>  I fear neither sword nor fire. </div>

<div class="dprose1"><span class="sd-cn">Smith.</span>
<span class="sd-inline">[<i>Aside</i>]</span>
He need not fear the sword; for his <a class="lnum pginternal" href="#lnote-bdb057" id="lnum-bdb057">♦</a>
coat is of proof.</div>

<div class="dprose1"><span class="sd-cn">Dick.</span>
<span class="sd-inline">[<i>Aside</i>]</span>
But methinks he should stand in fear of fire, being burnt i’ the hand for stealing of sheep.</div>

<div class="dprose1"><span class="lnum">60</span>
 <span class="sd-cn">Cade.</span>
Be brave, then; for your captain is brave, and vows reformation. There shall be in England seven half-penny loaves sold for a penny: the three-hooped pot shall have ten hoops; and I will make it felony to drink small beer: all the realm shall be in common; and in Cheapside <span class="lnum">65</span>
shall my palfry go to grass: and when I am king, as king I <a class="lnum pginternal" href="#lnote-bdb066" id="lnum-bdb066">♦</a>
will be,—</div>

<div class="dprose1"><span class="sd-cn">All.</span>
 God save your majesty!</div>

<div class="dprose1"><span class="sd-cn">Cade.</span>
I thank you, good people: there shall be no <a class="lnum pginternal" href="#lnote-bdb069" id="lnum-bdb069">♦</a>
money; all shall eat and drink on my score; and I will <span class="lnum">70</span>
apparel them all in one livery, that they may agree like brothers and worship me their lord.</div>

<div class="dprose1"><span class="sd-cn">Dick.</span>
 The first thing we do, let’s kill all the lawyers.</div>

<div class="dprose1"><span class="sd-cn">Cade.</span>
Nay, that I mean to do. Is not this a lamentable thing, that of the skin of an innocent lamb should be <a class="lnum pginternal" href="#lnote-bdb075" id="lnum-bdb075">75</a>
made parchment? that parchment, being scribbled o’er, should undo a man? Some say the bee stings: but I say, <a class="lnum pginternal" href="#lnote-bdb077" id="lnum-bdb077">♦</a>
’tis the bee’s wax; for I did but seal once to a thing, and I <a class="lnum pginternal" href="#lnote-bdb078" id="lnum-bdb078">♦</a>
was never mine own man since. How now! who’s there?</div>

<div class="sd-entry"><i>Enter some, bringing forward the</i> Clerk of Chatham.</div>

<div class="dprose1"><a class="lnum pginternal" href="#lnote-bdb079" id="lnum-bdb079">♦</a>
 <span class="sd-cn">Smith.</span>
The clerk of Chatham: he can write and read <span class="lnum">80</span> and cast accompt.</div>

<div class="dprose1"><span class="sd-cn">Cade.</span>
 O monstrous!</div>

<div class="dprose1"><span class="sd-cn">Smith.</span>
 We took him setting of boys’ copies.</div>

<div class="dprose1"><span class="sd-cn">Cade.</span>
 Here’s a villain!</div>

<div class="dprose1"><a class="lnum pginternal" href="#lnote-bdb084" id="lnum-bdb084">♦</a>
 <span class="sd-cn">Smith.</span>
Has a book in his pocket with red letters in’t.</div>

<div class="dprose1"><a class="lnum pginternal" href="#lnote-bdb085" id="lnum-bdb085">85</a>
 <span class="sd-cn">Cade.</span>
Nay, then, he is a conjuror.</div>

<div class="dprose1"><span class="sd-cn">Dick.</span>
Nay, he can make obligations, and write court-hand.</div>

<div class="dprose1"><span class="sd-cn">Cade.</span>
I am sorry for’t: the man is a proper man, of mine honour; unless I find him guilty, he shall not die. <span class="lnum">90</span>
Come hither, sirrah, I must examine thee: what is thy name?</div>

<div class="dprose1"><span class="sd-cn">Clerk.</span>
 Emmanuel.</div>

<div class="dprose1"><span class="sd-cn">Dick.</span>
 They use to write it on the top of letters: ’twill go hard with you.</div>

<div class="dprose1"><span class="lnum">95</span>
 <span class="sd-cn">Cade.</span>  Let me alone. Dost thou use to write thy
<a class="lnum pginternal" href="#lnote-bdb096" id="lnum-bdb096">♦</a>
name? or hast thou a mark to thyself, like an honest plain-dealing man?</div>

<div class="dprose1"><span class="sd-cn">Clerk.</span>
Sir, I thank God, I have been so well brought up that I can write my name.</div>

<div class="dprose1"><a class="lnum pginternal" href="#lnote-bdb100" id="lnum-bdb100">100</a>
 <span class="sd-cn">All.</span>
He hath confessed: away with him! he’s a villain and a traitor.</div>

<div class="dprose1"><span class="sd-cn">Cade.</span>
Away with him, I say! hang him with his pen <a class="lnum pginternal" href="#lnote-bdb103" id="lnum-bdb103">♦</a>
and ink-horn about his neck. <span class="sd-proseend">[<i>Exit one with the Clerk.</i></span></div>

<div class="sd-entry"><i>Enter</i>
<span class="smcaps">M<span>ICHAEL</span>.</span></div>

<div class="dprose1"><a class="lnum pginternal" href="#lnote-bdb104" id="lnum-bdb104">♦</a>
 <span class="sd-cn">Mich.</span>
Where’s our general?</div>

<div class="dprose1"><span class="lnum">105</span>
 <span class="sd-cn">Cade.</span>  Here I am, thou particular fellow.</div>

<div class="dprose1"><span class="sd-cn">Mich.</span>
 Fly, fly, fly! Sir Humphrey Stafford and his brother are hard by, with the king’s forces.</div>

<div class="dprose1"><span class="sd-cn">Cade.</span>
Stand, villain, stand, or I’ll fell thee down. He shall be encountered with a man as good as himself: he is <span class="lnum">110</span>
but a knight, is a’?</div>

<div class="dprose1"><span class="sd-cn">Mich.</span>
 No.</div>

<div class="dprose1"><a class="lnum pginternal" href="#lnote-bdb112" id="lnum-bdb112">♦</a>
 <span class="sd-cn">Cade.</span>
To equal him, I will make myself a knight presently. <a class="lnum pginternal" href="#lnote-bdb113" id="lnum-bdb113">♦</a>
<span class="sd-inline">[<i>Kneels</i>]</span> Rise up Sir John Mortimer. <span class="sd-inline">[<i>Rises</i>]</span> Now <a class="lnum pginternal" href="#lnote-bdb114" id="lnum-bdb114">♦</a>
have at him!</div>

<div class="sd-entry"><i>Enter</i> <span class="smcaps">S<span>IR</span></span> <span class="smcaps">H<span>UMPHREY</span></span> <span class="smcaps">S<span>TAFFORD</span></span> <i>and his Brother, with drum and soldiers</i>.</div>

<div class="dverse1"><a class="lnum pginternal" href="#lnote-bdb115" id="lnum-bdb115">115</a>
 <span class="sd-cn">Staf.</span>
  Rebellious hinds, the filth and scum of Kent,</div>
<div class="dverse">Mark’d for the gallows, lay your weapons down;</div>
<div class="dverse">Home to your cottages, forsake this groom:</div>
<div class="dverse"><a class="lnum pginternal" href="#lnote-bdb118" id="lnum-bdb118">♦</a>
 The king is merciful, if you revolt.</div>

<div class="dverse1"><a class="lnum pginternal" href="#lnote-bdb119" id="lnum-bdb119">♦</a>
 <span class="sd-cn">Bro.</span>
  But angry, wrathful, and inclined to blood,</div>
<div class="dverse"><span class="lnum">120</span> If you go forward; therefore yield, or die.</div>

<div class="dverse1"><a class="lnum pginternal" href="#lnote-bdb121" id="lnum-bdb121">♦</a>
 <span class="sd-cn">Cade.</span>
  As for these silken-coated slaves, I pass not:</div>
<div class="dverse">It is to you, good people, that I speak,</div>
<div class="dverse">Over whom, in time to come, I hope to reign;</div>
<div class="dverse">For I am rightful heir unto the crown.</div>

<div class="dverse1"><span class="lnum">125</span>
 <span class="sd-cn">Staf.</span>
  Villain, thy father was a plasterer;</div>
<div class="dverse">And thou thyself a shearman, art thou not?</div>

<div class="dverse1"><span class="sd-cn">Cade.</span>
 And Adam was a gardener.</div>

<div class="dverse1"><span class="sd-cn">Bro.</span>
 And what of that?</div>

<div class="dverse1"><a class="lnum pginternal" href="#lnote-bdb129" id="lnum-bdb129">♦</a>
 <span class="sd-cn">Cade.</span>
  Marry, this: Edmund Mortimer, Earl of March,</div>
<div class="dverse"><a class="lnum pginternal" href="#lnote-bdb130" id="lnum-bdb130">130</a>
 Married the Duke of Clarence’ daughter, did he not?</div>

<div class="dverse1"><span class="sd-cn">Staf.</span>
 Ay, sir.</div>

<div class="dverse1"><span class="sd-cn">Cade.</span>
 By her he had two children at one birth.</div>

<div class="dverse1"><span class="sd-cn">Bro.</span>
 That’s false.</div>

<div class="dverse1"><span class="sd-cn">Cade.</span>
 Ay, there’s the question; but I say, ’tis true:</div>
<div class="dverse"><span class="lnum">135</span> The elder of them, being put to nurse,</div>
<div class="dverse">Was by a beggar-woman stolen away;</div>
<div class="dverse">And, ignorant of his birth and parentage,</div>
<div class="dverse">Became a bricklayer when he came to age:</div>
<div class="dverse">His son am I; deny it, if you can.</div>

<div class="dverse1"><span class="lnum">140</span>
 <span class="sd-cn">Dick.</span>
 Nay, ’tis too true; therefore he shall be king.</div>

<div class="dprose1"><span class="sd-cn">Smith.</span>
Sir, he made a chimney in my father’s house, and the bricks are alive at this day to testify it; therefore deny it not.</div>

<div class="dverse1"><span class="sd-cn">Staf.</span>
And will you credit this base drudge’s words,</div>
<div class="dverse"><span class="lnum">145</span> That speaks he knows not what?</div>

<div class="dverse1"><a class="lnum pginternal" href="#lnote-bdb146" id="lnum-bdb146">♦</a>
 <span class="sd-cn">All.</span>
 Ay, marry, will we; therefore get ye gone.</div>

<div class="dverse1"><span class="sd-cn">Bro.</span>
Jack Cade, the Duke of York hath taught you this.</div>

<div class="dverse1"><a class="lnum pginternal" href="#lnote-bdb148" id="lnum-bdb148">♦</a>
<span class="sd-cn">Cade.</span>
<span class="sd-inline">[<i>Aside</i>]</span>
 He lies, for I invented it myself.</div>

<div class="dprose"> Go to, sirrah, tell the king from me, that, for his father’s
 <span class="lnum">150</span>
sake, Henry the fifth, in whose time boys went to span-counter for French crowns, I am content he shall reign; but I’ll be protector over him.</div>

<div class="dprose1"><span class="sd-cn">Dick.</span>
 And furthermore, we’ll have the Lord Say’s head for selling the dukedom of Maine.</div>

<div class="dprose1"><span class="lnum">155</span>
 <span class="sd-cn">Cade.</span>
 And good reason; for thereby is England
 <a class="lnum pginternal" href="#lnote-bdb156" id="lnum-bdb156">♦</a>
 mained, and fain to go with a staff, but that my puissance
 <a class="lnum pginternal" href="#lnote-bdb157" id="lnum-bdb157">♦</a>
 holds it up. Fellow kings, I tell you that that Lord Say hath gelded
 the commonwealth, and made it an eunuch: and more than that, he can
 speak French; and therefore
 <span class="lnum">160</span> he is a traitor.</div>

<div class="dprose1"><span class="sd-cn">Staf.</span>
 O gross and miserable ignorance!</div>

<div class="dprose1"><span class="sd-cn">Cade.</span>
 Nay, answer, if you can: the Frenchmen are our enemies;
 go to, then, I ask but this: can he that
 <a class="lnum pginternal" href="#lnote-bdb164" id="lnum-bdb164">♦</a>
 speaks with the tongue of an enemy be a good counsellor,
 <span class="lnum">165</span> or no?</div>

<div class="dprose1"><span class="sd-cn">All.</span>
No, no; and therefore we’ll have his head.</div>

<div class="dverse1"><span class="sd-cn">Bro.</span>
 Well, seeing gentle words will not prevail,</div>
<div class="dverse">Assail them with the army of the king.</div>

<div class="dverse1"><span class="sd-cn">Staf.</span>
 Herald, away; and throughout every town</div>
<div class="dverse"><span class="lnum">170</span> Proclaim them traitors that are up with Cade;</div>
<div class="dverse">That those which fly before the battle ends</div>
<div class="dverse">May, even in their wives’ and children’s sight,</div>
<div class="dverse">Be hang’d up for example at their doors:</div>
<div class="dverse"><a class="lnum pginternal" href="#lnote-bdb174" id="lnum-bdb174">♦</a>
 And you that be the king’s friends, follow me.
 <span class="sd-verseend">[<i>Exeunt the two Staffords, and soldiers.</i></span></div>

<div class="dverse1"><span class="lnum">175</span>
 <span class="sd-cn">Cade.</span>
 And you that love the commons, follow me.</div>
<div class="dverse">
 Now show yourselves men; ’tis for liberty.</div>
<div class="dverse"><a class="lnum pginternal" href="#lnote-bdb177" id="lnum-bdb177">♦</a>
 We will not leave one lord, one gentleman:</div>
<div class="dverse"><a class="lnum pginternal" href="#lnote-bdb178" id="lnum-bdb178">♦</a>
 Spare none but such as go in clouted shoon;</div>
<div class="dverse">For they are thrifty honest men and such</div>
<div class="dverse"><span class="lnum">180</span> As would, but that they dare not, take our parts.</div>

<div class="dverse1"><a class="lnum pginternal" href="#lnote-bdb181" id="lnum-bdb181">♦</a>
 <span class="sd-cn">Dick.</span>
 They are all in order and march toward us.</div>

<div class="dprose1"><span class="sd-cn">Cade.</span>
But then are we in order when we are most out <a class="lnum pginternal" href="#lnote-bdb183" id="lnum-bdb183">♦</a>
of order. Come, march forward. <span class="sd-proseend">[<i>Exeunt.</i></span></div>

<div class="section">
<h4 class="h4main"><span class="dnavigate">bdc</span> <span class="smcaps">S<span>CENE</span></span> III. <i>Another part of
Blackheath</i>.</h4>

<div class="sd-schg"><i>Alarums to the fight, wherein both the</i> <span class="smcaps">S<span>TAFFORDS</span></span> <i>are slain. Enter</i> <span class="smcaps">C<span>ADE</span></span> <i>and the rest</i>.</div></div>

<div class="dprose1"><a class="lnum pginternal" href="#lnote-bdc001" id="lnum-bdc001">♦</a>
 <span class="sd-cn">Cade.</span>
Where’s Dick, the butcher of Ashford?</div>

<div class="dprose1"><span class="sd-cn">Dick.</span>
Here, sir.</div>

<div class="dprose1"><span class="sd-cn">Cade.</span>
They fell before thee like sheep and oxen, and thou behavedst thyself as if thou hadst been in thine own <a class="lnum pginternal" href="#lnote-bdc005" id="lnum-bdc005">5</a>
slaughter-house: therefore thus will I reward thee, the Lent <a class="lnum pginternal" href="#lnote-bdc006" id="lnum-bdc006">♦</a>
shall be as long again as it is; and thou shalt have a license <a class="lnum pginternal" href="#lnote-bdc007" id="lnum-bdc007">♦</a>
to kill for a hundred lacking one.</div>

<div class="dprose1"><span class="sd-cn">Dick.</span>
 I desire no more.</div>

<div class="dprose1"><span class="sd-cn">Cade.</span>
And, to speak truth, thou deservest no less. This <a class="lnum pginternal" href="#lnote-bdc010" id="lnum-bdc010">10</a>
monument of the victory will I bear; <span class="sd-inline">[<i>putting on Sir Humphrey’s brigandine</i>]</span> and the bodies shall be dragged at my <a class="lnum pginternal" href="#lnote-bdc012" id="lnum-bdc012">♦</a>
horse heels till I do come to London, where we will have the mayor’s sword borne before us.</div>

<div class="dprose1"><a class="lnum pginternal" href="#lnote-bdc014" id="lnum-bdc014">♦</a>
 <span class="sd-cn">Dick.</span>
If we mean to thrive and do good, break open <a class="lnum pginternal" href="#lnote-bdc015" id="lnum-bdc015">15</a>
the gaols and let out the prisoners.</div>

<div class="dprose1"><span class="sd-cn">Cade.</span>
 Fear not that, I warrant thee. Come, let’s march towards London. <span class="sd-proseend">[<i>Exeunt.</i></span>
</div>

<div class="section">
<h4 class="h4main"><span class="dnavigate">bdd</span> <span class="smcaps">S<span>CENE</span></span> IV. <i>London. The
palace</i>.</h4>

<div class="sd-schg"><i>Enter the</i> <span class="smcaps">K<span>ING</span></span> <i>with a supplication,
and the</i> <span class="smcaps">Q<span>UEEN</span></span> <i>with
Suffolk’s head, the</i> <span class="smcaps">D<span>UKE</span></span>
<span class="smmaj">OF</span> <span class="smcaps">B<span>UCKINGHAM</span></span> <i>and the</i>
<span class="smcaps">L<span>ORD</span></span> <span class="smcaps">S<span>AY</span>.</span></div></div>

<div class="dverse1"><a class="lnum pginternal" href="#lnote-bdd001" id="lnum-bdd001">♦</a>
 <span class="sd-cn">Queen.</span>
  Oft have I heard that grief softens the mind</div>
<div class="dverse">And makes it fearful and degenerate;</div>
<div class="dverse">Think therefore on revenge and cease to weep.</div>
<div class="dverse">But who can cease to weep and look on this?</div>
<div class="dverse"><span class="lnum">5</span> Here may his head lie on my throbbing breast:</div>
<div class="dverse">But where’s the body that I should embrace?</div>

<div class="dverse1"><span class="sd-cn">Buck.</span>
 What answer makes your grace to the rebels’</div>
<div class="dverse">supplication?</div>

<div class="dverse1"><span class="sd-cn">King.</span>
 I’ll send some holy bishop to entreat;</div>
<div class="dverse"><span class="lnum">10</span> For God forbid so many simple souls</div>
<div class="dverse">Should perish by the sword! And I myself,</div>
<div class="dverse"><a class="lnum pginternal" href="#lnote-bdd012" id="lnum-bdd012">♦</a>
 Rather than bloody war shall cut them short,</div>
<div class="dverse">Will parley with Jack Cade their general:</div>
<div class="dverse">But stay, I’ll read it over once again.</div>

<div class="dverse1"><span class="lnum">15</span>
 <span class="sd-cn">Queen.</span>
  Ah, barbarous villains! hath this lovely face</div>
<div class="dverse">Ruled, like a wandering planet, over me,</div>
<div class="dverse">And could it not enforce them to relent,</div>
<div class="dverse">That were unworthy to behold the same?</div>

<div class="dverse1"><span class="sd-cn">King.</span>
 Lord Say, Jack Cade hath sworn to have thy head.</div>

<div class="dverse1"><span class="lnum">20</span>
 <span class="sd-cn">Say.</span>
  Ay, but I hope your highness shall have his.</div>

<div class="dverse1"><span class="sd-cn">King.</span>
 How now, madam!</div>
<div class="dverse"><a class="lnum pginternal" href="#lnote-bdd022" id="lnum-bdd022">♦</a>
 Still lamenting and mourning for Suffolk’s death?</div>
<div class="dverse"><a class="lnum pginternal" href="#lnote-bdd023" id="lnum-bdd023">♦</a>
 I fear me, love, if that I had been dead,</div>
<div class="dverse"><a class="lnum pginternal" href="#lnote-bdd024" id="lnum-bdd024">♦</a>
 Thou wouldest not have mourn’d so much for me.</div>

<div class="dverse1"><a class="lnum pginternal" href="#lnote-bdd025" id="lnum-bdd025">25</a>
 <span class="sd-cn">Queen.</span>
  No, my love, I should not mourn, but die for thee.</div>

<div class="sd-entry"><i>Enter a</i> Messenger.</div>

<div class="dverse1"><span class="sd-cn">King.</span>
 How now! what news? why comest thou in such haste?</div>

<div class="dverse1"><span class="sd-cn">Mess.</span>
 The rebels are in Southwark; fly, my lord!</div>
<div class="dverse">Jack Cade proclaims himself Lord Mortimer,</div>
<div class="dverse"><a class="lnum pginternal" href="#lnote-bdd029" id="lnum-bdd029">♦</a>
 Descended from the Duke of Clarence’ house,</div>
<div class="dverse"><span class="lnum">30</span> And calls your grace usurper openly</div>
<div class="dverse">And vows to crown himself in Westminster.</div>
<div class="dverse">His army is a ragged multitude</div>
<div class="dverse">Of hinds and peasants, rude and merciless:</div>
<div class="dverse">Sir Humphrey Stafford and his brother’s death</div>
<div class="dverse"><span class="lnum">35</span> Hath given them heart and courage to proceed:</div>
<div class="dverse">All scholars, lawyers, courtiers, gentlemen,</div>
<div class="dverse">They call false caterpillars and intend their death.</div>

<div class="dverse1"><span class="sd-cn">King.</span>
 O graceless men! they know not what they do.</div>

<div class="dverse1"><a class="lnum pginternal" href="#lnote-bdd039" id="lnum-bdd039">♦</a>
 <span class="sd-cn">Buck.</span>
  My gracious lord, retire to Killingworth,</div>
<div class="dverse"><span class="lnum">40</span> Until a power be raised to put them down.</div>

<div class="dverse1"><span class="sd-cn">Queen.</span>
 Ah, were the Duke of Suffolk now alive,</div>
<div class="dverse"><a class="lnum pginternal" href="#lnote-bdd042" id="lnum-bdd042">♦</a>
 These Kentish rebels would be soon appeased!</div>

<div class="dverse1"><a class="lnum pginternal" href="#lnote-bdd043" id="lnum-bdd043">♦</a>
 <span class="sd-cn">King.</span>
  Lord Say, the traitors hate thee;</div>
<div class="dverse">Therefore away with us to Killingworth.</div>

<div class="dverse1"><span class="lnum">45</span>
 <span class="sd-cn">Say.</span>
  So might your grace’s person be in danger.</div>
<div class="dverse">The sight of me is odious in their eyes;</div>
<div class="dverse">And therefore in this city will I stay</div>
<div class="dverse"><a class="lnum pginternal" href="#lnote-bdd048" id="lnum-bdd048">♦</a>
 And live alone as secret as I may.</div>

<div class="sd-entry"><i>Enter another</i> Messenger.</div>

<div class="dverse1"><a class="lnum pginternal" href="#lnote-bdd049" id="lnum-bdd049">♦</a>
 <span class="sd-cn">Mess.</span>
  Jack Cade hath gotten London bridge:</div>
<div class="dverse"><a class="lnum pginternal" href="#lnote-bdd050" id="lnum-bdd050">50</a>
 The citizens fly and forsake their houses:</div>
<div class="dverse">The rascal people, thirsting after prey,</div>
<div class="dverse">Join with the traitor, and they jointly swear</div>
<div class="dverse">To spoil the city and your royal court.</div>

<div class="dverse1"><span class="sd-cn">Buck.</span>
 Then linger not, my lord; away, take horse.</div>

<div class="dverse1"><span class="lnum">55</span>
 <span class="sd-cn">King.</span>
  Come, Margaret; God, our hope, will succour us.</div>

<div class="dverse1"><span class="sd-cn">Queen.</span>
 My hope is gone, now Suffolk is deceased.</div>

<div class="dverse1"><a class="lnum pginternal" href="#lnote-bdd057" id="lnum-bdd057">♦</a>
 <span class="sd-cn">King.</span>
  Farewell, my lord: trust not the Kentish rebels.</div>

<div class="dverse1"><a class="lnum pginternal" href="#lnote-bdd058" id="lnum-bdd058">♦</a>
 <span class="sd-cn">Buck.</span>
  Trust nobody, for fear you be betray’d.</div>

<div class="dverse1"><span class="sd-cn">Say.</span>
 The trust I have is in mine innocence,</div>
<div class="dverse"><span class="lnum">60</span>
And therefore am I bold and resolute. <span class="sd-verseend">[<i>Exeunt.</i></span></div>

<div class="section">
<h4 class="h4main"><span class="dnavigate">bde</span>
<span class="smcaps">S<span>CENE</span></span> V. <i>London. The Tower</i>.</h4>

<div class="sd-schg"><i>Enter</i> <span class="smcaps">L<span>ORD</span></span> <span class="smcaps">S<span>CALES</span></span>
 <i>upon the Tower, walking. Then enter two or three</i> Citizens <i>below</i>.</div></div>

<div class="dprose1"><a class="lnum pginternal" href="#lnote-bde001" id="lnum-bde001">♦</a>
 <span class="sd-cn">Scales.</span>
How now! is Jack Cade slain?</div>

<div class="dprose1"><a class="lnum pginternal" href="#lnote-bde002" id="lnum-bde002">♦</a>
 <span class="sd-cn">First Cit.</span>
No, my lord, nor likely to be slain; for they have won the bridge, killing all those that withstand them: the lord mayor craves aid of your honour from the Tower <span class="lnum">5</span> to defend the city from the rebels.</div>

<div class="dverse1"><span class="sd-cn">Scales.</span>
 Such aid as I can spare you shall command;</div>
<div class="dverse">But I am troubled here with them myself;</div>
<div class="dverse">The rebels have assay’d to win the Tower.</div>
<div class="dverse"><a class="lnum pginternal" href="#lnote-bde009" id="lnum-bde009">♦</a>
 But get you to Smithfield and gather head,</div>
<div class="dverse"><a class="lnum pginternal" href="#lnote-bde010" id="lnum-bde010">10</a>
 And thither I will send you Matthew Goffe;</div>
<div class="dverse">Fight for your king, your country and your lives;</div>
<div class="dverse"><a class="lnum pginternal" href="#lnote-bde012" id="lnum-bde012">♦</a>
And so, farewell, for I must hence again. <span class="sd-verseend">[<i>Exeunt.</i></span></div>

<div class="section">
<h4 class="h4main"><span class="dnavigate">bdf</span>
<span class="smcaps">S<span>CENE</span></span> VI. <i>London. Cannon Street</i>.</h4>

<div class="sd-schg"><i>Enter</i> <span class="smcaps">J<span>ACK</span></span> <span class="smcaps">C<span>ADE</span></span> <i>and the rest, and strikes his staff
on London-stone</i>.</div></div>

<div class="dprose1"><a class="lnum pginternal" href="#lnote-bdf001" id="lnum-bdf001">♦</a>
 <span class="sd-cn">Cade.</span>
Now is Mortimer lord of this city. And here, sitting upon London-stone, I charge and command that, of the city’s cost, the pissing-conduit run nothing but claret <a class="lnum pginternal" href="#lnote-bdf004" id="lnum-bdf004">♦</a>
wine this first year of our reign. And now henceforward <span class="lnum">5</span>
it shall be treason for any that calls me other than Lord Mortimer.</div>

<div class="sd-entry"><i>Enter a</i> Soldier, <i>running</i>.</div>

<div class="dprose1"><span class="sd-cn">Sold.</span>
Jack Cade! Jack Cade!</div>

<div class="dprose1"><span class="sd-cn">Cade.</span>
 Knock him down there.
 <span class="sd-proseend">[<i>They kill him.</i></span></div>

<div class="dprose1"><a class="lnum pginternal" href="#lnote-bdf009" id="lnum-bdf009">♦</a>
 <span class="sd-cn">Smith.</span>
If this fellow be wise, he’ll never call ye Jack <span class="lnum">10</span> Cade more: I think he hath a very fair warning.</div>

<div class="dprose1"><span class="sd-cn">Dick.</span>
My lord, there’s an army gathered together in Smithfield.</div>

<div class="dprose1"><a class="lnum pginternal" href="#lnote-bdf013" id="lnum-bdf013">♦</a>
 <span class="sd-cn">Cade.</span>
Come, then, let’s go fight with them: but first, go and set London bridge on fire; and, if you can, burn <a class="lnum pginternal" href="#lnote-bdf015" id="lnum-bdf015">15</a>
down the Tower too. Come, let’s away.
 <span class="sd-proseend">[<i>Exeunt.</i></span></div>

<div class="section">
<h4 class="h4main"><span class="dnavigate">bdg</span>
<span class="smcaps">S<span>CENE</span></span> VII. <i>London. Smithfield</i>.</h4>

<div class="sd-schg"><i>Alarums.</i> <span class="smcaps">M<span>ATTHEW</span></span> <span class="smcaps">G<span>OFFE</span></span> <i>is slain, and all the rest. Then enter</i> <span class="smcaps">J<span>ACK</span></span> <span class="smcaps">C<span>ADE</span>,</span> <i>with his company</i>. </div>
</div>

<div class="dprose1"><a class="lnum pginternal" href="#lnote-bdg001" id="lnum-bdg001">♦</a>
 <span class="sd-cn">Cade.</span>
So, sirs: now go some and pull down the Savoy; <a class="lnum pginternal" href="#lnote-bdg002" id="lnum-bdg002">♦</a>
others to the inns of court; down with them all.</div>

<div class="dprose1"><span class="sd-cn">Dick.</span>
 I have a suit unto your lordship.</div>

<div class="dprose1"><span class="sd-cn">Cade.</span>
 Be it a lordship, thou shalt have it for that word.</div>

<div class="dprose1"><span class="lnum">5</span>
 <span class="sd-cn">Dick.</span>
Only that the laws of England may come out of your mouth.</div>

<div class="dprose1"><a class="lnum pginternal" href="#lnote-bdg007" id="lnum-bdg007">♦</a>
<span class="sd-cn">Holl.</span>
<span class="sd-inline">[<i>Aside</i>]</span>
Mass, ’twill be sore law, then; for he was thrust in the mouth with a spear, and ’tis not whole yet.</div>

<div class="dprose1"><span class="sd-cn">Smith.</span>
<span class="sd-inline">[<i>Aside</i>]</span>
Nay, John, it will be stinking law; for <a class="lnum pginternal" href="#lnote-bdg010" id="lnum-bdg010">10</a>
his breath stinks with eating toasted cheese.</div>

<div class="dprose1"><span class="sd-cn">Cade.</span>
I have thought upon it, it shall be so. Away, burn all the records of the realm: my mouth shall be the parliament of England.</div>

<div class="dprose1"><a class="lnum pginternal" href="#lnote-bdg014" id="lnum-bdg014">♦</a>
<span class="sd-cn">Holl.</span>
<span class="sd-inline">[<i>Aside</i>]</span>
Then we are like to have biting statutes, <span class="lnum">15</span> unless his teeth be pulled out.</div>

<div class="dprose1"><span class="sd-cn">Cade.</span>
And henceforward all things shall be in common.</div>

<div class="sd-entry"><i>Enter a</i> Messenger.</div>

<div class="dprose1"><a class="lnum pginternal" href="#lnote-bdg017" id="lnum-bdg017">♦</a>
 <span class="sd-cn">Mess.</span>
My lord, a prize, a prize! here’s the Lord Say, <a class="lnum pginternal" href="#lnote-bdg018" id="lnum-bdg018">♦</a>
which sold the towns in France; he that made us pay one and <a class="lnum pginternal" href="#lnote-bdg019" id="lnum-bdg019">♦</a>
twenty fifteens, and one shilling to the pound, the last subsidy.</div>

<div class="sd-entry"><i>Enter</i> <span class="smcaps">G<span>EORGE</span></span> <span class="smcaps">B<span>EVIS</span>,</span> <i>with the</i>
<span class="smcaps">L<span>ORD</span></span> <span class="smcaps">S<span>AY</span>.</span></div>

<div class="dprose1"><span class="lnum">20</span>
 <span class="sd-cn">Cade.</span>
Well, he shall be beheaded for it ten times. Ah, thou say, thou serge, nay, thou buckram lord! now art thou
 <a class="lnum pginternal" href="#lnote-bdg022" id="lnum-bdg022">♦</a>
within point-blank of our jurisdiction regal. What canst
 <a class="lnum pginternal" href="#lnote-bdg023" id="lnum-bdg023">♦</a>
thou answer to my majesty for giving up of Normandy unto
 <a class="lnum pginternal" href="#lnote-bdg024" id="lnum-bdg024">♦</a>
 unto Mounsieur Basimecu, the dauphin of France? Be it known
 <a class="lnum pginternal" href="#lnote-bdg025" id="lnum-bdg025">25</a>
thee by these presence, even the presence of Lord Mortimer, that I am the besom that must sweep the court clean of such filth as thou art. Thou hast most traitorously corrupted the youth of the realm in erecting a grammar school: and whereas, before, our forefathers had no other books but
 <span class="lnum">30</span>
the score and the tally, thou hast caused printing to be used, and, contrary to the king, his crown and dignity, thou hast built a paper-mill. It will be proved to thy face that thou hast men about thee that usually talk of a noun and a verb, and such abominable words as no Christian ear can endure
 <a class="lnum pginternal" href="#lnote-bdg035" id="lnum-bdg035">35</a>
to hear. Thou hast appointed justices of peace, to call poor men before them about matters they were not able to answer.
 <a class="lnum pginternal" href="#lnote-bdg037" id="lnum-bdg037">♦</a>
Moreover, thou hast put them in prison; and because they could not read, thou hast hanged them; when, indeed, only for that cause they have been most worthy to live. Thou <a class="lnum pginternal" href="#lnote-bdg040" id="lnum-bdg040">40</a>
dost ride in a foot-cloth, dost thou not?</div>

<div class="dprose1"><span class="sd-cn">Say.</span>
 What of that?</div>

<div class="dprose1"><span class="sd-cn">Cade.</span>
 Marry, thou oughtest not to let thy horse wear a cloak, when honester men than thou go in their hose and doublets.</div>

<div class="dprose1"><span class="lnum">45</span>
 <span class="sd-cn">Dick.</span>
And work in their shirt too; as myself, for example, that am a butcher.</div>

<div class="dprose1"><span class="sd-cn">Say.</span>
 You men of Kent,—</div>

<div class="dprose1"><a class="lnum pginternal" href="#lnote-bdg048" id="lnum-bdg048">♦</a>
 <span class="sd-cn">Dick.</span>
What say you of Kent?</div>

<div class="dprose1"><a class="lnum pginternal" href="#lnote-bdg049" id="lnum-bdg049">♦</a>
 <span class="sd-cn">Say.</span>
 Nothing but this; ’tis ‘bona terra, mala gens.’</div>

<div class="dprose1"><span class="lnum">50</span>
 <span class="sd-cn">Cade.</span>
Away with him, away with him! he speaks Latin.</div>

<div class="dverse1"><a class="lnum pginternal" href="#lnote-bdg051" id="lnum-bdg051">♦</a>
 <span class="sd-cn">Say.</span>
  Hear me but speak, and bear me where you will.</div>
<div class="dverse">Kent, in the Commentaries Cæsar writ,</div>
<div class="dverse">Is term’d the civil’st place of all this isle:</div>
<div class="dverse"><a class="lnum pginternal" href="#lnote-bdg054" id="lnum-bdg054">♦</a>
 Sweet is the country, because full of riches;</div>
<div class="dverse"><a class="lnum pginternal" href="#lnote-bdg055" id="lnum-bdg055">55</a>
 The people liberal, valiant, active, wealthy;</div>
<div class="dverse"><a class="lnum pginternal" href="#lnote-bdg056" id="lnum-bdg056">♦</a>
 Which makes me hope you are not void of pity.</div>
<div class="dverse">I sold not Maine, I lost not Normandy,</div>
<div class="dverse"><a class="lnum pginternal" href="#lnote-bdg058" id="lnum-bdg058">♦</a>
 Yet, to recover them, would lose my life.</div>
<div class="dverse">Justice with favour have I always done;</div>
<div class="dverse"><span class="lnum">60</span> Prayers and tears have moved me, gifts could never.</div>
<div class="dverse"><a class="lnum pginternal" href="#lnote-bdg061" id="lnum-bdg061">♦</a>
 When have I aught exacted at your hands,</div>
<div class="dverse">But to maintain the king, the realm and you?</div>
<div class="dverse">Large gifts have I bestow’d on learned clerks,</div>
<div class="dverse"><a class="lnum pginternal" href="#lnote-bdg064" id="lnum-bdg064">♦</a>
 Because my book preferr’d me to the king,</div>
<div class="dverse"><span class="lnum">65</span> And seeing ignorance is the curse of God,</div>
<div class="dverse">Knowledge the wing wherewith we fly to heaven,</div>
<div class="dverse">Unless you be possess’d with devilish spirits,</div>
<div class="dverse"><a class="lnum pginternal" href="#lnote-bdg068" id="lnum-bdg068">♦</a>
 You cannot but forbear to murder me:</div>
<div class="dverse">This tongue hath parley’d unto foreign kings</div>
<div class="dverse"><a class="lnum pginternal" href="#lnote-bdg070" id="lnum-bdg070">70</a>
 For your behoof,—</div>

<div class="dprose1"><a class="lnum pginternal" href="#lnote-bdg071" id="lnum-bdg071">♦</a>
 <span class="sd-cn">Cade.</span>
Tut, when struck’st thou one blow in the field?</div>

<div class="dverse1"><span class="sd-cn">Say.</span>
 Great men have reaching hands: oft have I struck</div>
<div class="dverse"><a class="lnum pginternal" href="#lnote-bdg073" id="lnum-bdg073">♦</a>
 Those that I never saw and struck them dead.</div>

<div class="dprose1"><span class="sd-cn">Geo.</span>
 O monstrous coward! what, to come behind folks?</div>

<div class="dverse1"><a class="lnum pginternal" href="#lnote-bdg075" id="lnum-bdg075">75</a>
 <span class="sd-cn">Say.</span>
These cheeks are pale for watching for your good.</div>

<div class="dprose1"><span class="sd-cn">Cade.</span>
Give him a box o’ the ear and that will make ’em red again.</div>

<div class="dverse1"><span class="sd-cn">Say.</span>
 Long sitting to determine poor men’s causes</div>
<div class="dverse">Hath made me full of sickness and diseases.</div>

<div class="dprose1"><a class="lnum pginternal" href="#lnote-bdg080" id="lnum-bdg080">80</a>
 <span class="sd-cn">Cade.</span>
Ye shall have a hempen caudle then and the help of hatchet. </div>

<div class="dverse1"><span class="sd-cn">Dick.</span>
 Why dost thou quiver, man?</div>

<div class="dverse1"><a class="lnum pginternal" href="#lnote-bdg083" id="lnum-bdg083">♦</a>
 <span class="sd-cn">Say.</span>
 The palsy, and not fear, provokes me.
</div>

<div class="dprose1"><span class="sd-cn">Cade.</span>
Nay, he nods at us, as who should say, I’ll be <span class="lnum">85</span>
even with you: I’ll see if his head will stand steadier on a pole, or no. Take him away, and behead him.</div>

<div class="dverse1"><span class="sd-cn">Say.</span>
 Tell me wherein have I offended most?</div>
<div class="dverse">Have I affected wealth or honour? speak.</div>
<div class="dverse">Are my chests fill’d up with extorted gold?</div>
<div class="dverse"><span class="lnum">90</span> Is my apparel sumptuous to behold?</div>
<div class="dverse">Whom have I injured, that ye seek my death?</div>
<div class="dverse">These hands are free from guiltless blood-shedding,</div>
<div class="dverse">This breast from harbouring foul deceitful thoughts.</div>
<div class="dverse">O, let me live!</div>

<div class="dprose1"><a class="lnum pginternal" href="#lnote-bdg095" id="lnum-bdg095">95</a>
<span class="sd-cn">Cade.</span>
<span class="sd-inline">[<i>Aside</i>]</span>
I feel remorse in myself with his words; <a class="lnum pginternal" href="#lnote-bdg096" id="lnum-bdg096">♦</a>
but I’ll bridle it: he shall die, an it be but for pleading so well for his life. Away with him! he has a familiar under his <a class="lnum pginternal" href="#lnote-bdg098" id="lnum-bdg098">♦</a>
tongue; he speaks not o’ God’s name. Go, take him away, I say, and strike off his head presently; and then break <a class="lnum pginternal" href="#lnote-bdg100" id="lnum-bdg100">100</a>
into his son-in-law’s house, Sir James Cromer, and strike off his head, and bring them both upon two poles hither.</div>

<div class="dprose1"><span class="sd-cn">All.</span>
It shall be done.</div>

<div class="dverse1"><span class="sd-cn">Say.</span>
Ah, countrymen! if when you make your prayers,</div>
<div class="dverse">God should be so obdurate as yourselves,</div>
<div class="dverse"><span class="lnum">105</span> How would it fare with your departed souls?</div>
<div class="dverse">And therefore yet relent, and save my life.</div>

<div class="dprose1"><a class="lnum pginternal" href="#lnote-bdg107" id="lnum-bdg107">♦</a>
 <span class="sd-cn">Cade.</span>
Away with him! and do as I command ye.
<span class="sd-proseend">[<i>Exeunt some with Lord Say.</i></span></div>

<div class="dprose"><a class="lnum pginternal" href="#lnote-bdg108" id="lnum-bdg108">♦</a>
The proudest peer in the realm shall not wear a head on his shoulders, unless he pay me tribute; there shall not a
<a class="lnum pginternal" href="#lnote-bdg110" id="lnum-bdg110">110</a>
maid be married, but she shall pay to me her maidenhead ere they have it:
 men shall hold of me in capite; and we charge and command that their wives be as free as heart can wish or tongue can tell.</div>

<div class="dprose1"><span class="sd-cn">Dick.</span>
My lord, when shall we go to Cheapside and <span class="lnum">115</span> take up commodities upon our bills?</div>

<div class="dprose1"><span class="sd-cn">Cade.</span>
 Marry, presently.</div>

<div class="dprose1"><a class="lnum pginternal" href="#lnote-bdg117" id="lnum-bdg117">♦</a>
 <span class="sd-cn">All.</span>  O, brave!</div>

<div class="sd-entry"><i>Re-enter one with the heads.</i></div>

<div class="dprose1"><a class="lnum pginternal" href="#lnote-bdg118" id="lnum-bdg118">♦</a>
 <span class="sd-cn">Cade.</span>
But is not this braver? Let them kiss one another, <a class="lnum pginternal" href="#lnote-bdg119" id="lnum-bdg119">♦</a>
for they loved well when they were alive. Now part <span class="lnum">120</span>
them again, lest they consult about the giving up of some more towns in France.
 Soldiers, defer the spoil of the city until night: for with these borne before us,
 instead of maces, will we ride through the streets; and at every corner <a class="lnum pginternal" href="#lnote-bdg124" id="lnum-bdg124">♦</a>
 have them kiss. Away! <span class="sd-proseend">[<i>Exeunt.</i></span>
</div>

<div class="section">
<h4 class="h4main"><span class="dnavigate">bdh</span>
<span class="smcaps">S<span>CENE</span></span> VIII. <i>Southwark</i>.</h4>

<div class="sd-schg"><i>Alarum and retreat. Enter</i> <span class="smcaps">C<span>ADE</span></span> <i>and all his rabblement</i>.</div>
</div>

<div class="dprose1"><a class="lnum pginternal" href="#lnote-bdh001" id="lnum-bdh001">♦</a>
 <span class="sd-cn">Cade.</span>
Up Fish Street! down Saint Magnus’ Corner! <a class="lnum pginternal" href="#lnote-bdh002" id="lnum-bdh002">♦</a>
kill and knock down! throw them into Thames! <a class="lnum pginternal" href="#lnote-bdh003" id="lnum-bdh003">♦</a>
<span class="sd-inline">[<i>Sound a parley.</i>]</span>
What noise is this I hear? Dare any be so bold <a class="lnum pginternal" href="#lnote-bdh004" id="lnum-bdh004">♦</a>
to sound retreat or parley, when I command them kill?</div>

<div class="sd-entry"><i>Enter</i> <span class="smcaps">B<span>UCKINGHAM</span></span> <i>and old</i> <span class="smcaps">C<span>LIFFORD</span>,</span> <i>attended</i>.</div>

<div class="dverse1"><a class="lnum pginternal" href="#lnote-bdh005" id="lnum-bdh005">5</a>
 <span class="sd-cn">Buck.</span>
  Ay, here they be that dare and will disturb thee:</div>
<div class="dverse">Know, Cade, we come ambassadors from the king</div>
<div class="dverse">Unto the commons whom thou hast misled;</div>
<div class="dverse">And here pronounce free pardon to them all</div>
<div class="dverse">That will forsake thee and go home in peace.</div>

<div class="dverse1"><a class="lnum pginternal" href="#lnote-bdh010" id="lnum-bdh010">10</a>
 <span class="sd-cn">Clif.</span>
  What say ye, countrymen? will ye relent,</div>
<div class="dverse">And yield to mercy whilst ’tis offer’d you;</div>
<div class="dverse"><a class="lnum pginternal" href="#lnote-bdh012" id="lnum-bdh012">♦</a>
 Or let a rebel lead you to your deaths?</div>
<div class="dverse">Who loves the king and will embrace his pardon,</div>
<div class="dverse">Fling up his cap, and say ‘God save his majesty!’</div>
<div class="dverse"><span class="lnum">15</span> Who hateth him and honours not his father,</div>
<div class="dverse">Henry the fifth, that made all France to quake,</div>
<div class="dverse">Shake he his weapon at us and pass by.</div>

<div class="dprose1"><span class="sd-cn">All.</span>
 God save the king! God save the king!</div>

<div class="dprose1"><span class="sd-cn">Cade.</span>
What, Buckingham and Clifford, are ye so brave? <a class="lnum pginternal" href="#lnote-bdh020" id="lnum-bdh020">20</a>
And you, base peasants, do ye believe him? will you needs be hanged with your pardons about your necks? Hath my sword therefore broke through London gates, that you <a class="lnum pginternal" href="#lnote-bdh023" id="lnum-bdh023">♦</a>
should leave me at the White Hart in Southwark? I <a class="lnum pginternal" href="#lnote-bdh024" id="lnum-bdh024">♦</a>
thought ye would never have given out these arms till you <span class="lnum">25</span>
had recovered your ancient freedom: but you are all recreants and dastards, and delight to live in slavery to the nobility. Let them break your backs with burthens, take your houses over your heads, ravish your wives and daughters before your faces: for me, I will make shift for one; <span class="lnum">30</span>
and so, God’s curse light upon you all!</div>

<div class="dprose1"><a class="lnum pginternal" href="#lnote-bdh031" id="lnum-bdh031">♦</a>
 <span class="sd-cn">All.</span>
We’ll follow Cade, we’ll follow Cade!</div>

<div class="dverse1"><span class="sd-cn">Clif.</span>
 Is Cade the son of Henry the Fifth,</div>
<div class="dverse">That thus you do exclaim you’ll go with him?</div>
<div class="dverse">Will he conduct you through the heart of France,</div>
<div class="dverse"><span class="lnum">35</span> And make the meanest of you earls and dukes?</div>
<div class="dverse">Alas, he hath no home, no place to fly to;</div>
<div class="dverse">Nor knows he how to live but by the spoil,</div>
<div class="dverse">Unless by robbing of your friends and us.</div>
<div class="dverse">Were’t not a shame, that whilst you live at jar,</div>
<div class="dverse"><span class="lnum">40</span> The fearful French, whom you late vanquished,</div>
<div class="dverse">Should make a start o’er seas and vanquish you?</div>
<div class="dverse">Methinks already in this civil broil</div>
<div class="dverse">I see them lording it in London streets,</div>
<div class="dverse"><a class="lnum pginternal" href="#lnote-bdh044" id="lnum-bdh044">♦</a>
 Crying ‘Villiago!’ unto all they meet.</div>
<div class="dverse"><span class="lnum">45</span> Better ten thousand base-born Cades miscarry</div>
<div class="dverse">Than you should stoop unto a Frenchman’s mercy.</div>
<div class="dverse">To France, to France, and get what you have lost;</div>
<div class="dverse">Spare England, for it is your native coast:</div>
<div class="dverse"><a class="lnum pginternal" href="#lnote-bdh049" id="lnum-bdh049">♦</a>
 Henry hath money, you are strong and manly;</div>
<div class="dverse"><span class="lnum">50</span> God on our side, doubt not of victory.</div>

<div class="dprose1"><span class="sd-cn">All.</span>
 A Clifford! a Clifford! we’ll follow the king and Clifford.</div>

<div class="dprose1"><a class="lnum pginternal" href="#lnote-bdh053" id="lnum-bdh053">♦</a>
 <span class="sd-cn">Cade.</span>
Was ever feather so lightly blown to and fro as this multitude? The name of Henry the Fifth hales them to <span class="lnum">55</span> an hundred mischiefs and makes them leave me desolate. I see them lay their heads together to surprise me. My sword make way for me, for here is no staying. In despite <a class="lnum pginternal" href="#lnote-bdh058" id="lnum-bdh058">♦</a>
of the devils and hell, have through the very middest of you! and heavens and honour be witness that no want of <span class="lnum">60</span>
resolution in me, but only my followers’ base and ignominious <a class="lnum pginternal" href="#lnote-bdh061" id="lnum-bdh061">♦</a>
treasons, makes me betake me to my heels. <span class="sd-proseend">[<i>Exit.</i></span></div>

<div class="dverse1"><span class="sd-cn">Buck.</span>
 What, is he fled? Go some, and follow him;</div>
<div class="dverse">And he that brings his head unto the king</div>
<div class="dverse">Shall have a thousand crowns for his reward. <span class="sd-verseend">[<i>Exeunt some of them.</i></span></div>
<div class="dverse"><span class="lnum">65</span> Follow me, soldiers: we’ll devise a mean</div>
<div class="dverse"><a class="lnum pginternal" href="#lnote-bdh066" id="lnum-bdh066">♦</a>
To reconcile you all unto the king. <span class="sd-verseend">[<i>Exeunt.</i></span></div>

<div class="section">
<h4 class="h4main"><span class="dnavigate">bdi</span>
<span class="smcaps">S<span>CENE</span></span> IX. <i>Kenilworth Castle</i>.</h4>

<div class="sd-schg"><i>Sound trumpets. Enter</i> <span class="smcaps">K<span>ING</span>,</span> <span class="smcaps">Q<span>UEEN</span>,</span> <i>and</i> <span class="smcaps">S<span>OMERSET</span>,</span> <i>on the terrace</i>.</div>
</div>

<div class="dverse1"><a class="lnum pginternal" href="#lnote-bdi001" id="lnum-bdi001">♦</a>
 <span class="sd-cn">King.</span>
  Was ever king that joy’d an earthly throne,</div>
<div class="dverse">And could command no more content than I?</div>
<div class="dverse">No sooner was I crept out of my cradle</div>
<div class="dverse">But I was made a king, at nine months old.</div>
<div class="dverse"><span class="lnum">5</span> Was never subject long’d to be a king</div>
<div class="dverse"><a class="lnum pginternal" href="#lnote-bdi006" id="lnum-bdi006">♦</a>
 As I do long and wish to be a subject.</div>

<div class="sd-entry"><i>Enter</i> <span class="smcaps">B<span>UCKINGHAM</span></span> <i>and old</i> <span class="smcaps">C<span>LIFFORD</span>.</span></div>

<div class="dverse1"><span class="sd-cn">Buck.</span>
 Health and glad tidings to your majesty!</div>

<div class="dverse1"><span class="sd-cn">King.</span>
 Why, Buckingham, is the traitor Cade surprised?</div>
<div class="dverse"><a class="lnum pginternal" href="#lnote-bdi009" id="lnum-bdi009">♦</a>
 Or is he but retired to make him strong?</div>

<div class="sd-entry"><i>Enter, below, multitudes, with halters about their necks</i>.</div>

<div class="dverse1"><a class="lnum pginternal" href="#lnote-bdi010" id="lnum-bdi010">10</a>
 <span class="sd-cn">Clif.</span>
  He is fled, my lord, and all his powers do yield;</div>
<div class="dverse">And humbly thus, with halters on their necks,</div>
<div class="dverse">Expect your highness’ doom, of life or death.</div>

<div class="dverse1"><span class="sd-cn">King.</span>
 Then, heaven, set ope thy everlasting gates,</div>
<div class="dverse">To entertain my vows of thanks and praise!</div>
<div class="dverse"><span class="lnum">15</span> Soldiers, this day have you redeem’d your lives</div>
<div class="dverse">And show’d how well you love your prince and country:</div>
<div class="dverse">Continue still in this so good a mind,</div>
<div class="dverse"><a class="lnum pginternal" href="#lnote-bdi018" id="lnum-bdi018">♦</a>
 And Henry, though he be infortunate,</div>
<div class="dverse">Assure yourselves, will never be unkind:</div>
<div class="dverse"><span class="lnum">20</span> And so, with thanks and pardon to you all,</div>
<div class="dverse"><a class="lnum pginternal" href="#lnote-bdi021" id="lnum-bdi021">♦</a>
 I do dismiss you to your several countries.</div>

<div class="dverse1"><a class="lnum pginternal" href="#lnote-bdi022" id="lnum-bdi022">♦</a>
 <span class="sd-cn">All.</span>
  God save the king! God save the king!</div>

<div class="sd-entry"><i>Enter a Messenger</i>.</div>

<div class="dverse1"><span class="sd-cn">Mess.</span>
 Please it your grace to be advertised</div>
<div class="dverse">The Duke of York is newly come from Ireland,</div>
<div class="dverse"><a class="lnum pginternal" href="#lnote-bdi025" id="lnum-bdi025">25</a>
 And with a puissant and a mighty power</div>
<div class="dverse"><a class="lnum pginternal" href="#lnote-bdi026" id="lnum-bdi026">♦</a>
 Of gallowglasses and stout kernes</div>
<div class="dverse">Is marching hitherward in proud array,</div>
<div class="dverse">And still proclaimeth, as he comes along,</div>
<div class="dverse"><a class="lnum pginternal" href="#lnote-bdi029" id="lnum-bdi029">♦</a>
 His arms are only to remove from thee</div>
<div class="dverse"><span class="lnum">30</span> The Duke of Somerset, whom he terms a traitor.</div>

<div class="dverse1"><span class="sd-cn">King.</span>
 Thus stands my state, ’twixt Cade and York distress’d;</div>
<div class="dverse">Like to a ship that, having ’scaped a tempest</div>
<div class="dverse"><a class="lnum pginternal" href="#lnote-bdi033" id="lnum-bdi033">♦</a>
 Is straightway calm’d and boarded with a pirate:</div>
<div class="dverse"><a class="lnum pginternal" href="#lnote-bdi034" id="lnum-bdi034">♦</a>
 But now is Cade driven back, his men dispersed;</div>
<div class="dverse"><span class="lnum">35</span> And now is York in arms to second him.</div>
<div class="dverse"><a class="lnum pginternal" href="#lnote-bdi036" id="lnum-bdi036">♦</a>
 I pray thee, Buckingham, go and meet him,</div>
<div class="dverse">And ask him what’s the reason of these arms.</div>
<div class="dverse">Tell him I’ll send Duke Edmund to the Tower;</div>
<div class="dverse">And, Somerset, we will commit thee hither,</div>
<div class="dverse"><span class="lnum">40</span> Until his army be dismiss’d from him.</div>

<div class="dverse1"><span class="sd-cn">Som.</span>
 My lord,</div>
<div class="dverse">I’ll yield myself to prison willingly,</div>
<div class="dverse">Or unto death, to do my country good.</div>

<div class="dverse1"><span class="sd-cn">King.</span>
 In any case, be not too rough in terms;</div>
<div class="dverse"><span class="lnum">45</span> For he is fierce and cannot brook hard language.</div>

<div class="dverse1"><span class="sd-cn">Buck.</span>
 I will, my lord; and doubt not so to deal</div>
<div class="dverse">As all things shall redound unto your good.</div>

<div class="dverse1"><span class="sd-cn">King.</span>
 Come, wife, let’s in, and learn to govern better;</div>
<div class="dverse"><a class="lnum pginternal" href="#lnote-bdi049" id="lnum-bdi049">♦</a>
 For yet may England curse my wretched reign.
 <span class="sd-verseend">[<i>Flourish. Exeunt.</i></span></div>

<div class="section">
<h4 class="h4main"><span class="dnavigate">bdj</span>
<span class="smcaps">S<span>CENE</span></span> X. <i>Kent. Iden’s garden</i>.</h4>

<div class="sd-schg"><i>Enter</i> <span class="smcaps">C<span>ADE</span></span>.</div>
</div>

<div class="dprose1"><a class="lnum pginternal" href="#lnote-bdj001" id="lnum-bdj001">♦</a>
 <span class="sd-cn">Cade.</span>
Fie on ambition! fie on myself, that have a sword, and yet am ready to famish! These five days have I <a class="lnum pginternal" href="#lnote-bdj003" id="lnum-bdj003">♦</a>
hid me in these woods and durst not peep out, for all the <a class="lnum pginternal" href="#lnote-bdj004" id="lnum-bdj004">♦</a>
country is laid for me; but now am I so hungry that if I <span class="lnum">5</span>
might have a lease of my life for a thousand years I could <a class="lnum pginternal" href="#lnote-bdj006" id="lnum-bdj006">♦</a>
stay no longer. Wherefore, on a brick wall have I climbed into this garden, to see if I can eat grass, or pick a sallet another while, which is not amiss to cool a man’s stomach this hot weather. And I think this word ‘sallet’ was born <a class="lnum pginternal" href="#lnote-bdj010" id="lnum-bdj010">10</a>
to do me good: for many a time, but for a sallet, my brain-pan had been cleft with a brown bill; and many a time, <a class="lnum pginternal" href="#lnote-bdj012" id="lnum-bdj012">♦</a>
when I have been dry and bravely marching, it hath served me instead of a quart pot to drink in; and now the word <a class="lnum pginternal" href="#lnote-bdj014" id="lnum-bdj014">♦</a>
‘sallet’ must serve me to feed on.</div>

<div class="sd-entry"><i>Enter</i> <span class="smcaps">I<span>DEN</span></span>.</div>

<div class="dverse1"><span class="lnum">15</span>
 <span class="sd-cn">Iden.</span>
  Lord, who would live turmoiled in the court,</div>
<div class="dverse">And may enjoy such quiet walks as these?</div>
<div class="dverse">This small inheritance my father left me</div>
<div class="dverse"><a class="lnum pginternal" href="#lnote-bdj018" id="lnum-bdj018">♦</a>
 Contenteth me, and worth a monarchy.</div>
<div class="dverse"><a class="lnum pginternal" href="#lnote-bdj019" id="lnum-bdj019">♦</a>
 I seek not to wax great by others’ waning,</div>
<div class="dverse"><span class="lnum">20</span> Or gather wealth, I care not, with what envy:</div>
<div class="dverse">Sufficeth that I have maintains my state</div>
<div class="dverse">And sends the poor well pleased from my gate.</div>

<div class="dprose1"><a class="lnum pginternal" href="#lnote-bdj023" id="lnum-bdj023">♦</a>
 <span class="sd-cn">Cade.</span>
Here’s the lord of the soil come to seize me for <a class="lnum pginternal" href="#lnote-bdj024" id="lnum-bdj024">♦</a>
a stray, for entering his fee-simple without leave. Ah, <a class="lnum pginternal" href="#lnote-bdj025" id="lnum-bdj025">25</a>
villain, thou wilt betray me, and get a thousand crowns of the king by carrying my head to him: but I’ll make thee eat iron like an ostrich, and swallow my sword like a great pin, ere thou and I part.</div>

<div class="dverse1"><span class="sd-cn">Iden.</span>
 Why, rude companion, whatsoe’er thou be,</div>
<div class="dverse"><span class="lnum">30</span> I know thee not; why, then, should I betray thee?</div>
<div class="dverse">Is’t not enough to break into my garden,</div>
<div class="dverse">And, like a thief, to come to rob my grounds,</div>
<div class="dverse">Climbing my walls in spite of me the owner.</div>
<div class="dverse"><a class="lnum pginternal" href="#lnote-bdj034" id="lnum-bdj034">♦</a>
 But thou wilt brave me with these saucy terms?</div>

<div class="dprose1"><a class="lnum pginternal" href="#lnote-bdj035" id="lnum-bdj035">35</a>
 <span class="sd-cn">Cade.</span>
Brave thee! ay, by the best blood that ever was broached, and beard thee too. Look on me well: I have <a class="lnum pginternal" href="#lnote-bdj037" id="lnum-bdj037">♦</a>
eat no meat these five days; yet, come thou and thy five <a class="lnum pginternal" href="#lnote-bdj038" id="lnum-bdj038">♦</a>
men, and if I do not leave you all as dead as a door-nail, I pray God I may never eat grass more.</div>

<div class="dverse1"><span class="lnum">40</span>
 <span class="sd-cn">Iden.</span>
  Nay, it shall ne’er be said, while England stands,</div>
<div class="dverse"><a class="lnum pginternal" href="#lnote-bdj041" id="lnum-bdj041">♦</a>
 That Alexander Iden, an esquire of Kent,</div>
<div class="dverse">Took odds to combat a poor famish’d man.</div>
<div class="dverse"><a class="lnum pginternal" href="#lnote-bdj043" id="lnum-bdj043">♦</a>
 Oppose thy steadfast-gazing eyes to mine,</div>
<div class="dverse">See if thou canst outface me with thy looks:</div>
<div class="dverse"><span class="lnum">45</span> Set limb to limb, and thou art far the lesser;</div>
<div class="dverse">Thy hand is but a finger to my fist,</div>
<div class="dverse">Thy leg a stick compared with this truncheon;</div>
<div class="dverse">My foot shall fight with all the strength thou hast;</div>
<div class="dverse">And if mine arm be heaved in the air,</div>
<div class="dverse"><span class="lnum">50</span> Thy grave is digg’d already in the earth.</div>
<div class="dverse"><a class="lnum pginternal" href="#lnote-bdj051" id="lnum-bdj051">♦</a>
 As for words, whose greatness answers words,</div>
<div class="dverse">Let this my sword report what speech forbears.</div>

<div class="dprose1"><span class="sd-cn">Cade.</span>
By my valour, the most complete champion that <a class="lnum pginternal" href="#lnote-bdj054" id="lnum-bdj054">♦</a>
ever I heard! Steel, if thou turn the edge, or cut not out <a class="lnum pginternal" href="#lnote-bdj055" id="lnum-bdj055">55</a>
the burly-boned clown in chines of beef ere thou sleep in <a class="lnum pginternal" href="#lnote-bdj056" id="lnum-bdj056">♦</a>
thy sheath, I beseech God on my knees thou mayst be <a class="lnum pginternal" href="#lnote-bdj057" id="lnum-bdj057">♦</a>
turned to hobnails. <span class="sd-proseend">[<i>Here they fight. Cade falls.</i></span></div>

<div class="dprose1">O, I am slain! famine and no other hath slain me: let ten thousand devils come against me, and give me but the <span class="lnum">60</span>
ten meals I have lost, and I’ld defy them all. Wither, garden; and be henceforth a burying-place to all that do dwell in this house, because the unconquered soul of Cade is fled.</div>

<div class="dverse1"><span class="sd-cn">Iden.</span>
 Is’t Cade that I have slain, that monstrous traitor?</div>
<div class="dverse"><a class="lnum pginternal" href="#lnote-bdj065" id="lnum-bdj065">65</a>
 Sword, I will hallow thee for this thy deed,</div>
<div class="dverse">And hang thee o’er my tomb when I am dead:</div>
<div class="dverse">Ne’er shall this blood be wiped from thy point;</div>
<div class="dverse">But thou shalt wear it as a herald’s coat,</div>
<div class="dverse"><a class="lnum pginternal" href="#lnote-bdj069" id="lnum-bdj069">♦</a>
 To emblaze the honour that thy master got.</div>

<div class="dprose1"><span class="lnum">70</span>
 <span class="sd-cn">Cade.</span>
Iden, farewell, and be proud of thy victory. Tell Kent from me, she hath lost her best man, and exhort all the world to be cowards; for I, that never feared any, am vanquished by famine, not by valour. <span class="sd-proseend">[<i>Dies.</i></span></div>

<div class="dverse1"><span class="sd-cn">Iden.</span>
 How much thou wrong’st me, heaven be my judge.</div>
<div class="dverse"><span class="lnum">75</span> Die, damned wretch, the curse of her that bare thee;</div>
<div class="dverse"><a class="lnum pginternal" href="#lnote-bdj076" id="lnum-bdj076">♦</a>
 And as I thrust thy body in with my sword,</div>
<div class="dverse">So wish I, I might thrust thy soul to hell.</div>
<div class="dverse">Hence will I drag thee headlong by the heels</div>
<div class="dverse">Unto a dunghill which shall be thy grave,</div>
<div class="dverse"><a class="lnum pginternal" href="#lnote-bdj080" id="lnum-bdj080">80</a>
 And there cut off thy most ungracious head;</div>
<div class="dverse">Which I will bear in triumph to the king,</div>
<div class="dverse"><a class="lnum pginternal" href="#lnote-bdj082" id="lnum-bdj082">♦</a>
Leaving thy trunk for crows to feed upon. <span class="sd-verseend">[<i>Exit.</i></span></div>

<div class="section">
<h3 class="h3main">ACT V.</h3>

<h4 class="h4main"><span class="dnavigate">bea</span>
<span class="smcaps">S<span>CENE</span></span> I. <i>Fields between
Dartford and Blackheath</i>. </h4>

<div class="sd-schg"><i>Enter</i> <span class="smcaps">Y<span>ORK</span>,</span> <i>and his army of Irish, with
drum and colours</i>.</div></div>

<div class="dverse1"><a class="lnum pginternal" href="#lnote-bea001" id="lnum-bea001">♦</a>
 <span class="sd-cn">York.</span>
  From Ireland thus comes York to claim his right,</div>
<div class="dverse">And pluck the crown from feeble Henry’s head:</div>
<div class="dverse">Ring, bells, aloud; burn, bonfires, clear and bright,</div>
<div class="dverse">To entertain great England’s lawful king.</div>
<div class="dverse"><a class="lnum pginternal" href="#lnote-bea005" id="lnum-bea005">5</a>
 Ah! sancta majestas, who would not buy thee dear?</div>
<div class="dverse"><a class="lnum pginternal" href="#lnote-bea006" id="lnum-bea006">♦</a>
 Let them obey that know not how to rule;</div>
<div class="dverse">This hand was made to handle nought but gold.</div>
<div class="dverse"><a class="lnum pginternal" href="#lnote-bea008" id="lnum-bea008">♦</a>
 I cannot give due action to my words,</div>
<div class="dverse">Except a sword or sceptre balance it:</div>
<div class="dverse"><a class="lnum pginternal" href="#lnote-bea010" id="lnum-bea010">10</a>
 A sceptre shall it have, have I a soul,</div>
<div class="dverse"><a class="lnum pginternal" href="#lnote-bea011" id="lnum-bea011">♦</a>
 On which I’ll toss the flower-de-luce of France.</div>

<div class="sd-entry"><i>Enter</i> <span class="smcaps">B<span>UCKINGHAM</span></span>.</div>

<div class="dverse">Whom have we here? Buckingham, to disturb me?</div>
<div class="dverse">The king hath sent him, sure: I must dissemble.</div>

<div class="dverse1"><span class="sd-cn">Buck.</span>
 York, if thou meanest well, I greet thee well.</div>

<div class="dverse1"><span class="lnum">15</span>
 <span class="sd-cn">York.</span>
  Humphrey of Buckingham, I accept thy greeting.</div>
<div class="dverse">Art thou a messenger, or come of pleasure?</div>

<div class="dverse1"><span class="sd-cn">Buck.</span>
 A messenger from Henry, our dread liege,</div>
<div class="dverse">To know the reason of these arms in peace;</div>
<div class="dverse">Or why thou, being a subject as I am,</div>
<div class="dverse"><span class="lnum">20</span> Against thy oath and true allegiance sworn,</div>
<div class="dverse"><a class="lnum pginternal" href="#lnote-bea021" id="lnum-bea021">♦</a>
 Should raise so great a power without his leave,</div>
<div class="dverse">Or dare to bring thy force so near the court.</div>

<div class="dverse1"><a class="lnum pginternal" href="#lnote-bea023" id="lnum-bea023">♦</a>
<span class="sd-cn">York.</span>
 <span class="sd-inline">[<i>Aside</i>]</span>
 Scarce can I speak, my choler is so great:</div>
<div class="dverse">O, I could hew up rocks and fight with flint,</div>
<div class="dverse"><span class="lnum">25</span> I am so angry at these abject terms;</div>
<div class="dverse">And now, like Ajax Telamonius,</div>
<div class="dverse"><a class="lnum pginternal" href="#lnote-bea027" id="lnum-bea027">♦</a>
 On sheep or oxen could I spend my fury.</div>
<div class="dverse">I am far better born than is the king,</div>
<div class="dverse">More like a king, more kingly in my thoughts:</div>
<div class="dverse"><span class="lnum">30</span> But I must make fair weather yet a while,</div>
<div class="dverse">Till Henry be more weak and I more strong.—</div>
<div class="dverse"><a class="lnum pginternal" href="#lnote-bea032" id="lnum-bea032">♦</a>
 Buckingham, I prithee, pardon me,</div>
<div class="dverse">That I have given no answer all this while;</div>
<div class="dverse">My mind was troubled with deep melancholy.</div>
<div class="dverse"><span class="lnum">35</span> The cause why I have brought this army hither</div>
<div class="dverse">Is to remove proud Somerset from the king,</div>
<div class="dverse">Seditious to his grace and to the state.</div>

<div class="dverse1"><span class="sd-cn">Buck.</span>
 That is too much presumption on thy part:</div>
<div class="dverse"><a class="lnum pginternal" href="#lnote-bea039" id="lnum-bea039">♦</a>
 But if thy arms be to no other end,</div>
<div class="dverse"><span class="lnum">40</span> The king hath yielded unto thy demand:</div>
<div class="dverse">The Duke of Somerset is in the Tower.</div>

<div class="dverse1"><span class="sd-cn">York.</span>
 Upon thine honour, is he prisoner?</div>

<div class="dverse1"><a class="lnum pginternal" href="#lnote-bea043" id="lnum-bea043">♦</a>
 <span class="sd-cn">Buck.</span>
  Upon mine honour, he is prisoner.</div>

<div class="dverse1"><span class="sd-cn">York.</span>
 Then, Buckingham, I do dismiss my powers.</div>
<div class="dverse"><span class="lnum">45</span> Soldiers, I thank you all; disperse yourselves;</div>
<div class="dverse">Meet me to-morrow in Saint George’s field,</div>
<div class="dverse">You shall have pay and every thing you wish.</div>
<div class="dverse">And let my sovereign, virtuous Henry,</div>
<div class="dverse">Command my eldest son, nay, all my sons,</div>
<div class="dverse"><span class="lnum">50</span> As pledges of my fealty and love;</div>
<div class="dverse">I’ll send them all as willing as I live:</div>
<div class="dverse">Lands, goods, horse, armour, any thing I have,</div>
<div class="dverse">Is his to use, so Somerset may die.</div>

<div class="dverse1"><span class="sd-cn">Buck.</span>
 York, I commend this kind submission:</div>
<div class="dverse"><a class="lnum pginternal" href="#lnote-bea055" id="lnum-bea055">55</a>
 We twain will go into his highness’ tent.</div>

<div class="sd-entry"><i>Enter</i> <span class="smcaps">K<span>ING</span></span> <i>and</i> Attendants.</div>

<div class="dverse1"><a class="lnum pginternal" href="#lnote-bea056" id="lnum-bea056">♦</a>
 <span class="sd-cn">King.</span>
  Buckingham, doth York intend no harm to us,</div>
<div class="dverse">That thus he marcheth with thee arm in arm?</div>

<div class="dverse1"><span class="sd-cn">York.</span>
 In all submission and humility</div>
<div class="dverse">York doth present himself unto your highness.</div>

<div class="dverse1"><a class="lnum pginternal" href="#lnote-bea060" id="lnum-bea060">60</a>
 <span class="sd-cn">King.</span>
  Then what intends these forces thou dost bring?</div>

<div class="dverse1"><a class="lnum pginternal" href="#lnote-bea061" id="lnum-bea061">♦</a>
 <span class="sd-cn">York.</span>
  To heave the traitor Somerset from hence,</div>
<div class="dverse">And fight against that monstrous rebel Cade,</div>
<div class="dverse"><a class="lnum pginternal" href="#lnote-bea063" id="lnum-bea063">♦</a>
 Who since I heard to be discomfited.</div>

<div class="sd-entry"><i>Enter</i> <span class="smcaps">I<span>DEN</span>,</span> <i>with</i> <span class="smcaps">C<span>ADE’S</span></span> <i>head</i>.</div>

<div class="dverse1"><span class="sd-cn">Iden.</span>
 If one so rude and of so mean condition</div>
<div class="dverse"><a class="lnum pginternal" href="#lnote-bea065" id="lnum-bea065">65</a>
 May pass into the presence of a king,</div>
<div class="dverse">Lo, I present your grace a traitor’s head,</div>
<div class="dverse">The head of Cade, whom I in combat slew.</div>

<div class="dverse1"><span class="sd-cn">King.</span>
 The head of Cade! Great God, how just art Thou!</div>
<div class="dverse">O, let me view his visage, being dead,</div>
<div class="dverse"><span class="lnum">70</span> That living wrought me such exceeding trouble.</div>
<div class="dverse"><a class="lnum pginternal" href="#lnote-bea071" id="lnum-bea071">♦</a>
 Tell me, my friend, art thou the man that slew him?</div>

<div class="dverse1"><a class="lnum pginternal" href="#lnote-bea072" id="lnum-bea072">♦</a>
 <span class="sd-cn">Iden.</span>
  I was, an’t like your majesty.</div>

<div class="dverse1"><span class="sd-cn">King.</span>
 How art thou call’d? and what is thy degree?</div>

<div class="dverse1"><a class="lnum pginternal" href="#lnote-bea074" id="lnum-bea074">♦</a>
 <span class="sd-cn">Iden.</span>
  Alexander Iden, that’s my name;</div>
<div class="dverse"><a class="lnum pginternal" href="#lnote-bea075" id="lnum-bea075">75</a>
 A poor esquire of Kent, that loves his king.</div>

<div class="dverse1"><a class="lnum pginternal" href="#lnote-bea076" id="lnum-bea076">♦</a>
 <span class="sd-cn">Buck.</span>
  So please it you, my lord, ’twere not amiss</div>
<div class="dverse"><a class="lnum pginternal" href="#lnote-bea077" id="lnum-bea077">♦</a>
 He were created knight for his good service.</div>

<div class="dverse1"><a class="lnum pginternal" href="#lnote-bea078" id="lnum-bea078">♦</a>
 <span class="sd-cn">King.</span>
 Iden, kneel down. <span class="sd-inline">[<i>He kneels.</i>]</span> Rise up a knight.</div>
<div class="dverse">We give thee for reward a thousand marks,</div>
<div class="dverse"><span class="lnum">80</span> And will that thou henceforth attend on us.</div>

<div class="dverse1"><span class="sd-cn">Iden.</span>
 May Iden live to merit such a bounty,</div>
<div class="dverse"><a class="lnum pginternal" href="#lnote-bea082" id="lnum-bea082">♦</a>
And never live but true unto his liege! <span class="sd-verseend">[<i>Rises.</i></span></div>

<div class="sd-entry"><i>Enter</i> <span class="smcaps">Q<span>UEEN</span></span>
 <i>and</i> <span class="smcaps">S<span>OMERSET</span></span>.</div>

<div class="dverse1"><a class="lnum pginternal" href="#lnote-bea083" id="lnum-bea083">♦</a>
 <span class="sd-cn">King.</span>
  See, Buckingham, Somerset comes with the queen:</div>
<div class="dverse">Go, bid her hide him quickly from the duke.</div>

<div class="dverse1"><span class="lnum">85</span>
 <span class="sd-cn">Queen.</span>
  For thousand Yorks he shall not hide his head,</div>
<div class="dverse">But boldly stand and front him to his face.</div>

<div class="dverse1"><span class="sd-cn">York.</span>
 How now! is Somerset at liberty?</div>
<div class="dverse">Then, York, unloose thy long-imprison’d thoughts,</div>
<div class="dverse">And let thy tongue be equal with thy heart.</div>
<div class="dverse"><span class="lnum">90</span> Shall I endure the sight of Somerset?</div>
<div class="dverse">False king! why hast thou broken faith with me,</div>
<div class="dverse">Knowing how hardly I can brook abuse?</div>
<div class="dverse"><a class="lnum pginternal" href="#lnote-bea093" id="lnum-bea093">♦</a>
 King did I call thee? no, thou art not king,</div>
<div class="dverse"><a class="lnum pginternal" href="#lnote-bea094" id="lnum-bea094">♦</a>
 Not fit to govern and rule multitudes,</div>
<div class="dverse"><a class="lnum pginternal" href="#lnote-bea095" id="lnum-bea095">95</a>
 Which darest not, no, nor canst not rule a traitor.</div>
<div class="dverse">That head of thine doth not become a crown;</div>
<div class="dverse">Thy hand is made to grasp a palmer’s staff,</div>
<div class="dverse">And not to grace an awful princely sceptre.</div>
<div class="dverse"><a class="lnum pginternal" href="#lnote-bea099" id="lnum-bea099">♦</a>
 That gold must round engirt these brows of mine,</div>
<div class="dverse"><a class="lnum pginternal" href="#lnote-bea100" id="lnum-bea100">100</a>
 Whose smile and frown, like to Achilles’ spear,</div>
<div class="dverse">Is able with the change to kill and cure.</div>
<div class="dverse">Here is a hand to hold a sceptre up</div>
<div class="dverse"><a class="lnum pginternal" href="#lnote-bea103" id="lnum-bea103">♦</a>
 And with the same to act controlling laws.</div>
<div class="dverse">Give place: by heaven, thou shalt rule no more</div>
<div class="dverse"><span class="lnum">105</span> O’er him whom heaven created for thy ruler.</div>

<div class="dverse1"><span class="sd-cn">Som.</span>
 O monstrous traitor! I arrest thee, York,</div>
<div class="dverse">Of capital treason ’gainst the king and crown:</div>
<div class="dverse">Obey, audacious traitor; kneel for grace.</div>

<div class="dverse1"><a class="lnum pginternal" href="#lnote-bea109" id="lnum-bea109">♦</a>
 <span class="sd-cn">York.</span>
  Wouldst have me kneel? first let me ask of these,</div>
<div class="dverse"><span class="lnum">110</span> If they can brook I bow a knee to man.</div>
<div class="dverse"><a class="lnum pginternal" href="#lnote-bea111" id="lnum-bea111">♦</a>
 Sirrah, call in my sons to be my bail: <span class="sd-verseend">[<i>Exit Attendant.</i></span></div>
<div class="dverse">I know, ere they will have me go to ward,</div>
<div class="dverse"><a class="lnum pginternal" href="#lnote-bea113" id="lnum-bea113">♦</a>
 They’ll pawn their swords for my enfranchisement.</div>

<div class="dverse1"><span class="sd-cn">Queen.</span>
 Call hither Clifford; bid him come amain.</div>
<div class="dverse"><span class="lnum">115</span> To say if that the bastard boys of York</div>
<div class="dverse"><a class="lnum pginternal" href="#lnote-bea116" id="lnum-bea116">♦</a>
 Shall be the surety for their traitor father.
 <span class="sd-verseend">[<i>Exit Buckingham.</i></span></div>

<div class="dverse1"><span class="sd-cn">York.</span>
 O blood-bespotted Neapolitan,</div>
<div class="dverse">Outcast of Naples, England’s bloody scourge!</div>
<div class="dverse">The sons of York, thy betters in their birth,</div>
<div class="dverse"><a class="lnum pginternal" href="#lnote-bea120" id="lnum-bea120">120</a>
 Shall be their father’s bail; and bane to those</div>
<div class="dverse"><a class="lnum pginternal" href="#lnote-bea121" id="lnum-bea121">♦</a>
 That for my surety will refuse the boys!</div>

<div class="sd-entry"><i>Enter</i> <span class="smcaps">E<span>DWARD</span></span> <i>and</i> <span class="smcaps">R<span>ICHARD</span></span>.</div>

<div class="dverse"><a class="lnum pginternal" href="#lnote-bea122" id="lnum-bea122">♦</a>
 See where they come: I’ll warrant they’ll make it good.</div>

<div class="sd-entry"><i>Enter old</i> <span class="smcaps">C<span>LIFFORD</span></span> <i>and his</i> Son.</div>

<div class="dverse1"><span class="sd-cn">Queen.</span>
 And here comes Clifford to deny their bail.</div>

<div class="dverse1"><a class="lnum pginternal" href="#lnote-bea124" id="lnum-bea124">♦</a>
 <span class="sd-cn">Clif.</span>
 Health and all happiness to my lord the king!
 <span class="sd-verseend">[<i>Kneels</i>.</span></div>

<div class="dverse1"><a class="lnum pginternal" href="#lnote-bea125" id="lnum-bea125">125</a>
 <span class="sd-cn">York.</span>
  I thank thee, Clifford: say, what news with thee?</div>
<div class="dverse"><a class="lnum pginternal" href="#lnote-bea126" id="lnum-bea126">♦</a>
 Nay, do not fright us with an angry look:</div>
<div class="dverse">We are thy sovereign, Clifford, kneel again;</div>
<div class="dverse">For thy mistaking so, we pardon thee.</div>

<div class="dverse1"><span class="sd-cn">Clif.</span>
 This is my king, York, I do not mistake;</div>
<div class="dverse"><a class="lnum pginternal" href="#lnote-bea130" id="lnum-bea130">130</a>
 But thou mistakest me much to think I do:</div>
<div class="dverse">To Bedlam with him! is the man grown mad?</div>

<div class="dverse1"><span class="sd-cn">King.</span>
 Ay, Clifford; a bedlam and ambitious humour</div>
<div class="dverse">Makes him oppose himself against his king.</div>

<div class="dverse1"><span class="sd-cn">Clif.</span>
 He is a traitor; let him to the Tower,</div>
<div class="dverse"><a class="lnum pginternal" href="#lnote-bea135" id="lnum-bea135">135</a>
 And chop away that factious pate of his.</div>

<div class="dverse1"><span class="sd-cn">Queen.</span>
 He is arrested, but will not obey;</div>
<div class="dverse">His sons, he says, shall give their words for him.</div>

<div class="dverse1"><span class="sd-cn">York.</span>
 Will you not, sons?</div>

<div class="dverse1"><a class="lnum pginternal" href="#lnote-bea139" id="lnum-bea139">♦</a>
 <span class="sd-cn">Edw.</span>
  Ay, noble father, if our words will serve.</div>

<div class="dverse1"><span class="lnum">140</span>
 <span class="sd-cn">Rich.</span>
  And if words will not, then our weapons shall.</div>

<div class="dverse1"><span class="sd-cn">Clif.</span>
 Why, what a brood of traitors have we here!</div>

<div class="dverse1"><span class="sd-cn">York.</span>
 Look in a glass, and call thy image so:</div>
<div class="dverse"><a class="lnum pginternal" href="#lnote-bea143" id="lnum-bea143">♦</a>
 I am thy king, and thou a false-heart traitor.</div>
<div class="dverse">Call hither to the stake my two brave bears,</div>
<div class="dverse"><span class="lnum">145</span> That with the very shaking of their chains</div>
<div class="dverse"><a class="lnum pginternal" href="#lnote-bea146" id="lnum-bea146">♦</a>
 They may astonish these fell-lurking curs:</div>
<div class="dverse"><a class="lnum pginternal" href="#lnote-bea147" id="lnum-bea147">♦</a>
 Bid Salisbury and Warwick come to me.</div>

<div class="sd-entry"><i>Enter the</i> <span class="smcaps">E<span>ARLS</span></span> <span class="smmaj">OF</span>
<span class="smcaps">W<span>ARWICK</span></span> <i>and</i> <span class="smcaps">S<span>ALISBURY</span></span>.</div>

<div class="dverse1"><a class="lnum pginternal" href="#lnote-bea148" id="lnum-bea148">♦</a>
 <span class="sd-cn">Clif.</span>
  Are these thy bears? we’ll bait thy bears to death,</div>
<div class="dverse"><a class="lnum pginternal" href="#lnote-bea149" id="lnum-bea149">♦</a>
 And manacle the bear-ward in their chains,</div>
<div class="dverse"><a class="lnum pginternal" href="#lnote-bea150" id="lnum-bea150">150</a>
 If thou darest bring them to the baiting place.</div>

<div class="dverse1"><span class="sd-cn">Rich.</span>
 Oft have I seen a hot o’erweening cur</div>
<div class="dverse"><a class="lnum pginternal" href="#lnote-bea152" id="lnum-bea152">♦</a>
 Run back and bite, because he was withheld;</div>
<div class="dverse"><a class="lnum pginternal" href="#lnote-bea153" id="lnum-bea153">♦</a>
 Who, being suffer’d with the bear’s fell paw,</div>
<div class="dverse"><a class="lnum pginternal" href="#lnote-bea154" id="lnum-bea154">♦</a>
 Hath clapp’d his tail between his legs and cried:</div>
<div class="dverse"><span class="lnum">155</span> And such a piece of service will you do,</div>
<div class="dverse"><a class="lnum pginternal" href="#lnote-bea156" id="lnum-bea156">♦</a>
 If you oppose yourselves to match Lord Warwick.</div>

<div class="dverse1"><a class="lnum pginternal" href="#lnote-bea157" id="lnum-bea157">♦</a>
 <span class="sd-cn">Clif.</span>
  Hence, heap of wrath, foul indigested lump,</div>
<div class="dverse">As crooked in thy manners as thy shape!</div>

<div class="dverse1"><span class="sd-cn">York.</span>
 Nay, we shall heat you thoroughly anon.</div>

<div class="dverse1"><span class="lnum">160</span>
 <span class="sd-cn">Clif.</span>
  Take heed, lest by your heat you burn yourselves.</div>

<div class="dverse1"><span class="sd-cn">King.</span>
 Why, Warwick, hath thy knee forgot to bow?</div>
<div class="dverse">Old Salisbury, shame to thy silver hair,</div>
<div class="dverse">Thou mad misleader of thy brain-sick son!</div>
<div class="dverse">What, wilt thou on thy death-bed play the ruffian,</div>
<div class="dverse"><span class="lnum">165</span> And seek for sorrow with thy spectacles?</div>
<div class="dverse">O, where is faith? O, where is loyalty?</div>
<div class="dverse">If it be banish’d from the frosty head,</div>
<div class="dverse">Where shall it find a harbour in the earth?</div>
<div class="dverse"><a class="lnum pginternal" href="#lnote-bea169" id="lnum-bea169">♦</a>
 Wilt thou go dig a grave to find out war,</div>
<div class="dverse"><a class="lnum pginternal" href="#lnote-bea170" id="lnum-bea170">170</a>
 And shame thine honourable age with blood?</div>
<div class="dverse">Why art thou old, and want’st experience?</div>
<div class="dverse">Or wherefore dost abuse it, if thou hast it?</div>
<div class="dverse">For shame! in duty bend thy knee to me</div>
<div class="dverse"><a class="lnum pginternal" href="#lnote-bea174" id="lnum-bea174">♦</a>
 That bows unto the grave with mickle age.</div>

<div class="dverse1"><a class="lnum pginternal" href="#lnote-bea175" id="lnum-bea175">175</a>
 <span class="sd-cn">Sal.</span>
  My lord, I have consider’d with myself</div>
<div class="dverse">The title of this most renowned duke;</div>
<div class="dverse">And in my conscience do repute his grace</div>
<div class="dverse">The rightful heir to England’s royal seat.</div>

<div class="dverse1"><span class="sd-cn">King.</span>
 Hast thou not sworn allegiance unto me?</div>

<div class="dverse1"><span class="lnum">180</span>
 <span class="sd-cn">Sal.</span>
  I have.</div>

<div class="dverse1"><a class="lnum pginternal" href="#lnote-bea181" id="lnum-bea181">♦</a>
 <span class="sd-cn">King.</span>
  Canst thou dispense with heaven for such an oath?</div>

<div class="dverse1"><span class="sd-cn">Sal.</span>
 It is great sin to swear unto a sin,</div>
<div class="dverse">But greater sin to keep a sinful oath.</div>
<div class="dverse">Who can be bound by any solemn vow</div>
<div class="dverse"><span class="lnum">185</span> To do a murderous deed, to rob a man,</div>
<div class="dverse">To force a spotless virgin’s chastity,</div>
<div class="dverse">To reave the orphan of his patrimony,</div>
<div class="dverse">To wring the widow from her custom’d right,</div>
<div class="dverse"><a class="lnum pginternal" href="#lnote-bea189" id="lnum-bea189">♦</a>
 And have no other reason for this wrong</div>
<div class="dverse"><span class="lnum">190</span> But that he was bound by a solemn oath?</div>

<div class="dverse1"><span class="sd-cn">Queen.</span>
 A subtle traitor needs no sophister.</div>

<div class="dverse1"><span class="sd-cn">King.</span>
 Call Buckingham, and bid him arm himself.</div>

<div class="dverse1"><span class="sd-cn">York.</span>
 Call Buckingham, and all the friends thou hast,</div>
<div class="dverse"><a class="lnum pginternal" href="#lnote-bea194" id="lnum-bea194">♦</a>
 I am resolved for death or dignity.</div>

<div class="dverse1"><a class="lnum pginternal" href="#lnote-bea195" id="lnum-bea195">195</a>
 <span class="sd-cn">Clif.</span>
  The first I warrant thee, if dreams prove true.</div>

<div class="dverse1"><a class="lnum pginternal" href="#lnote-bea196" id="lnum-bea196">♦</a>
 <span class="sd-cn">War.</span>
  You were best to go to bed and dream again,</div>
<div class="dverse">To keep thee from the tempest of the field.</div>

<div class="dverse1"><span class="sd-cn">Clif.</span>
 I am resolved to bear a greater storm</div>
<div class="dverse">Than any thou canst conjure up to-day;</div>
<div class="dverse"><span class="lnum">200</span> And that I’ll write upon thy burgonet,</div>
<div class="dverse"><a class="lnum pginternal" href="#lnote-bea201" id="lnum-bea201">♦</a>
 Might I but know thee by thy household badge.</div>

<div class="dverse1"><a class="lnum pginternal" href="#lnote-bea202" id="lnum-bea202">♦</a>
 <span class="sd-cn">War.</span>
  Now, by my father’s badge, old Nevil’s crest,</div>
<div class="dverse"><a class="lnum pginternal" href="#lnote-bea203" id="lnum-bea203">♦</a>
 The rampant bear chain’d to the ragged staff,</div>
<div class="dverse">This day I’ll wear aloft my burgonet,</div>
<div class="dverse"><span class="lnum">205</span> As on a mountain top the cedar shows</div>
<div class="dverse">That keeps his leaves in spite of any storm,</div>
<div class="dverse"><a class="lnum pginternal" href="#lnote-bea207" id="lnum-bea207">♦</a>
 Even to affright thee with the view thereof.</div>

<div class="dverse1"><span class="sd-cn">Clif.</span>
 And from thy burgonet I’ll rend thy bear</div>
<div class="dverse">And tread it under foot with all contempt,</div>
<div class="dverse"><a class="lnum pginternal" href="#lnote-bea210" id="lnum-bea210">210</a>
 Despite the bear-ward that protects the bear.</div>

<div class="dverse1"><a class="lnum pginternal" href="#lnote-bea211" id="lnum-bea211">♦</a>
 <span class="sd-cn">Y. Clif.</span>
  And so to arms, victorious father,</div>
<div class="dverse"><a class="lnum pginternal" href="#lnote-bea212" id="lnum-bea212">♦</a>
 To quell the rebels and their complices.</div>

<div class="dverse1"><span class="sd-cn">Rich.</span>
 Fie! charity, for shame! speak not in spite,</div>
<div class="dverse">For you shall sup with Jesu Christ to-night.</div>

<div class="dverse1"><span class="lnum">215</span>
 <span class="sd-cn">Y. Clif.</span>
  Foul stigmatic, that’s more than thou canst tell.</div>

<div class="dverse1"><a class="lnum pginternal" href="#lnote-bea216" id="lnum-bea216">♦</a>
 <span class="sd-cn">Rich.</span>
 If not in heaven, you’ll surely sup in hell.
 <span class="sd-verseend">[<i>Exeunt severally.</i></span></div>

<div class="section">
<h4 class="h4main"><span class="dnavigate">beb</span>
<span class="smcaps">S<span>CENE</span></span> II. <i>Saint Alban’s</i>.</h4>

<div class="sd-schg"><i>Alarums to the battle. Enter</i> <span class="smcaps">W<span>ARWICK</span></span>.</div>
</div>

<div class="dverse1"><span class="sd-cn">War.</span>
 Clifford of Cumberland, ’tis Warwick calls:</div>
<div class="dverse"><a class="lnum pginternal" href="#lnote-beb002" id="lnum-beb002">♦</a>
 And if thou dost not hide thee from the bear,</div>
<div class="dverse">Now, when the angry trumpet sounds alarum</div>
<div class="dverse"><a class="lnum pginternal" href="#lnote-beb004" id="lnum-beb004">♦</a>
 And dead men’s cries do fill the empty air,</div>
<div class="dverse"><span class="lnum">5</span> Clifford, I say, come forth and fight with me:</div>
<div class="dverse">Proud northern lord, Clifford of Cumberland,</div>
<div class="dverse">Warwick is hoarse with calling thee to arms.</div>

<div class="sd-entry"><i>Enter</i>
<span class="smcaps">Y<span>ORK</span></span>.</div>

<div class="dverse"><a class="lnum pginternal" href="#lnote-beb008" id="lnum-beb008">♦</a>
 How now, my noble lord! what, all a-foot?</div>

<div class="dverse1"><span class="sd-cn">York.</span>
 The deadly-handed Clifford slew my steed,</div>
<div class="dverse"><span class="lnum">10</span> But match to match I have encounter’d him</div>
<div class="dverse"><a class="lnum pginternal" href="#lnote-beb011" id="lnum-beb011">♦</a>
 And made a prey for carrion kites and crows</div>
<div class="dverse"><a class="lnum pginternal" href="#lnote-beb012" id="lnum-beb012">♦</a>
 Even of the bonny beast he loved so well.</div>

<div class="sd-entry"><i>Enter old</i>
<span class="smcaps">C<span>LIFFORD</span></span>.</div>

<div class="dverse1"><span class="sd-cn">War.</span>
 Of one or both of us the time is come.</div>

<div class="dverse1"><span class="sd-cn">York.</span>
 Hold, Warwick, seek thee out some other chase,</div>
<div class="dverse"><span class="lnum">15</span> For I myself must hunt this deer to death.</div>

<div class="dverse1"><span class="sd-cn">War.</span>
 Then, nobly, York; ’tis for a crown thou fight’st.</div>
<div class="dverse">As I intend, Clifford, to thrive to-day,</div>
<div class="dverse">It grieves my soul to leave thee unassail’d. <span class="sd-verseend">[<i>Exit.</i></span></div>

<div class="dverse1"><a class="lnum pginternal" href="#lnote-beb019" id="lnum-beb019">♦</a>
 <span class="sd-cn">Clif.</span>
  What seest thou in me, York? why dost thou pause?</div>

<div class="dverse1"><span class="lnum">20</span>
 <span class="sd-cn">York.</span>
  With thy brave bearing should I be in love,</div>
<div class="dverse">But that thou art so fast mine enemy.</div>

<div class="dverse1"><span class="sd-cn">Clif.</span>
 Nor should thy prowess want praise and esteem,</div>
<div class="dverse">But that ’tis shown ignobly and in treason.</div>

<div class="dverse1"><a class="lnum pginternal" href="#lnote-beb024" id="lnum-beb024">♦</a>
 <span class="sd-cn">York.</span>
  So let it help me now against thy sword</div>
<div class="dverse"><span class="lnum">25</span> As I in justice and true right express it.</div>

<div class="dverse1"><span class="sd-cn">Clif.</span>
 My soul and body on the action both!</div>

<div class="dverse1"><a class="lnum pginternal" href="#lnote-beb027" id="lnum-beb027">♦</a>
 <span class="sd-cn">York.</span>
 A dreadful lay! Address thee instantly.
 <span class="sd-verseend">[<i>They fight, and Clifford falls.</i></span></div>

<div class="dverse1"><a class="lnum pginternal" href="#lnote-beb028" id="lnum-beb028">♦</a>
 <span class="sd-cn">Clif.</span>
 La fin couronne les œuvres. <span class="sd-verseend">[<i>Dies.</i></span></div>

<div class="dverse1"><span class="sd-cn">York.</span>
 Thus war hath given thee peace, for thou art still.</div>
<div class="dverse"><span class="lnum">30</span>
 Peace with his soul, heaven, if it be thy will!
 <span class="sd-verseend">[<i>Exit.</i></span></div>

<div class="sd-entry"><i>Enter young</i>
<span class="smcaps">C<span>LIFFORD</span></span>.</div>

<div class="dverse1"><a class="lnum pginternal" href="#lnote-beb031" id="lnum-beb031">♦</a>
 <span class="sd-cn">Y. Clif.</span>
  Shame and confusion! all is on the rout;</div>
<div class="dverse">Fear frames disorder, and disorder wounds</div>
<div class="dverse">Where it should guard. O war, thou son of hell,</div>
<div class="dverse">Whom angry heavens do make their minister,</div>
<div class="dverse"><span class="lnum">35</span> Throw in the frozen bosoms of our part</div>
<div class="dverse"><a class="lnum pginternal" href="#lnote-beb036" id="lnum-beb036">♦</a>
 Hot coals of vengeance! Let no soldier fly.</div>
<div class="dverse">He that is truly dedicate to war</div>
<div class="dverse"><a class="lnum pginternal" href="#lnote-beb038" id="lnum-beb038">♦</a>
 Hath no self-love, nor he that loves himself</div>
<div class="dverse">Hath not essentially but by circumstance</div>
<div class="dverse"><a class="lnum pginternal" href="#lnote-beb040" id="lnum-beb040">40</a>
 The name of valour. <span class="sd-inline">[<i>Seeing his dead father</i>]</span>
  O, let the vile world end,</div>
<div class="dverse"><a class="lnum pginternal" href="#lnote-beb041" id="lnum-beb041">♦</a>
 And the premised flames of the last day</div>
<div class="dverse"><a class="lnum pginternal" href="#lnote-beb042" id="lnum-beb042">♦</a>
 Knit earth and heaven together!</div>
<div class="dverse">Now let the general trumpet blow his blast,</div>
<div class="dverse">Particularities and petty sounds</div>
<div class="dverse"><a class="lnum pginternal" href="#lnote-beb045" id="lnum-beb045">45</a>
 To cease! Wast thou ordain’d, dear father,</div>
<div class="dverse">To lose thy youth in peace, and to achieve</div>
<div class="dverse">The silver livery of advised age,</div>
<div class="dverse">And, in thy reverence and thy chair-days, thus</div>
<div class="dverse">To die in ruffian battle? Even at this sight</div>
<div class="dverse"><span class="lnum">50</span> My heart is turn’d to stone: and while ’tis mine,</div>
<div class="dverse">It shall be stony. York not our old men spares;</div>
<div class="dverse">No more will I their babes: tears virginal</div>
<div class="dverse">Shall be to me even as the dew to fire,</div>
<div class="dverse">And beauty that the tyrant oft reclaims</div>
<div class="dverse"><span class="lnum">55</span> Shall to my flaming wrath be oil and flax.</div>
<div class="dverse">Henceforth I will not have to do with pity:</div>
<div class="dverse">Meet I an infant of the house of York,</div>
<div class="dverse">Into as many gobbets will I cut it</div>
<div class="dverse"><a class="lnum pginternal" href="#lnote-beb059" id="lnum-beb059">♦</a>
 As wild Medea young Absyrtus did:</div>
<div class="dverse"><span class="lnum">60</span> In cruelty will I seek out my fame.</div>
<div class="dverse">Come, thou new ruin of old Clifford’s house:</div>
<div class="dverse">As did Æneas old Anchises bear,</div>
<div class="dverse">So bear I thee upon my manly shoulders;</div>
<div class="dverse">But then Æneas bare a living load,</div>
<div class="dverse"><a class="lnum pginternal" href="#lnote-beb065" id="lnum-beb065">65</a>
 Nothing so heavy as these woes of mine.
 <span class="sd-verseend">[<i>Exit, bearing off his father.</i></span></div>

<div class="sd-entry"><i>Enter</i> <span class="smcaps">R<span>ICHARD</span></span> <i>and</i> <span class="smcaps">S<span>OMERSET</span></span> <i>to fight.</i> <span class="smcaps">S<span>OMERSET</span></span> <i>is killed</i>.</div>

<div class="dverse1"><a class="lnum pginternal" href="#lnote-beb066" id="lnum-beb066">♦</a>
 <span class="sd-cn">Rich.</span>
  So, lie thou there;</div>
<div class="dverse"><a class="lnum pginternal" href="#lnote-beb067" id="lnum-beb067">♦</a>
 For underneath an alehouse’ paltry sign,</div>
<div class="dverse">The Castle in Saint Alban’s, Somerset</div>
<div class="dverse">Hath made the wizard famous in his death.</div>
<div class="dverse"><span class="lnum">70</span> Sword, hold thy temper; heart, be wrathful still:</div>
<div class="dverse"><a class="lnum pginternal" href="#lnote-beb071" id="lnum-beb071">♦</a>
 Priests pray for enemies, but princes kill. <span class="sd-verseend">[<i>Exit.</i></span></div>

<div class="sd-entry"><i>Fight: excursions. Enter</i>
<span class="smcaps">K<span>ING</span>,</span> <span class="smcaps">Q<span>UEEN</span>,</span> <i>and others</i>.</div>

<div class="dverse1"><a class="lnum pginternal" href="#lnote-beb072" id="lnum-beb072">♦</a>
 <span class="sd-cn">Queen.</span>
  Away, my lord! you are slow; for shame, away!</div>

<div class="dverse1"><span class="sd-cn">King.</span>
 Can we outrun the heavens? good Margaret, stay.</div>

<div class="dverse1"><a class="lnum pginternal" href="#lnote-beb074" id="lnum-beb074">♦</a>
 <span class="sd-cn">Queen.</span>
  What are you made of? you’ll nor fight nor fly:</div>
<div class="dverse"><span class="lnum">75</span> Now is it manhood, wisdom and defence,</div>
<div class="dverse">To give the enemy way, and to secure us</div>
<div class="dverse">By what we can, which can no more but fly. <span class="sd-verseend">[<i>Alarum afar off.</i></span></div>
<div class="dverse"><a class="lnum pginternal" href="#lnote-beb078" id="lnum-beb078">♦</a>
 If you be ta’en, we then should see the bottom</div>
<div class="dverse">Of all our fortunes: but if we haply scape,</div>
<div class="dverse"><a class="lnum pginternal" href="#lnote-beb080" id="lnum-beb080">80</a>
 As well we may, if not through your neglect,</div>
<div class="dverse">We shall to London get, where you are loved</div>
<div class="dverse"><a class="lnum pginternal" href="#lnote-beb082" id="lnum-beb082">♦</a>
 And where this breach now in our fortunes made</div>
<div class="dverse"><a class="lnum pginternal" href="#lnote-beb083" id="lnum-beb083">♦</a>
 May readily be stopp’d.</div>

<div class="sd-entry"><i>Re-enter young</i>
<span class="smcaps">C<span>LIFFORD</span></span>.</div>

<div class="dverse1"><a class="lnum pginternal" href="#lnote-beb084" id="lnum-beb084">♦</a>
 <span class="sd-cn">Y. Clif.</span>
  But that my heart’s on future mischief set,</div>
<div class="dverse"><span class="lnum">85</span> I would speak blasphemy ere bid you fly:</div>
<div class="dverse"><a class="lnum pginternal" href="#lnote-beb086" id="lnum-beb086">♦</a>
 But fly you must; uncurable discomfit</div>
<div class="dverse"><a class="lnum pginternal" href="#lnote-beb087" id="lnum-beb087">♦</a>
 Reigns in the hearts of all our present parts.</div>
<div class="dverse">Away, for your relief! and we will live</div>
<div class="dverse">To see their day and them our fortune give:</div>
<div class="dverse"><span class="lnum">90</span>
 Away, my lord, away! <span class="sd-verseend">[<i>Exeunt.</i></span></div>

<div class="section">
<h4 class="h4main"><span class="dnavigate">bec</span>
<span class="smcaps">S<span>CENE</span></span> III.
<i>Fields near St Alban’s</i>.</h4>

<div class="sd-schg"><i>Alarum. Retreat. Enter</i> <span class="smcaps">Y<span>ORK</span>,</span> <span class="smcaps">R<span>ICHARD</span>,</span> <span class="smcaps">W<span>ARWICK</span>,</span> <i>and</i> Soldiers, <i>with drum and colours</i>. </div>
</div>

<div class="dverse1"><a class="lnum pginternal" href="#lnote-bec001" id="lnum-bec001">♦</a>
 <span class="sd-cn">York.</span>
  Of Salisbury, who can report of him,</div>
<div class="dverse">That winter lion, who in rage forgets</div>
<div class="dverse"><a class="lnum pginternal" href="#lnote-bec003" id="lnum-bec003">♦</a>
 Aged contusions and all brush of time,</div>
<div class="dverse"><a class="lnum pginternal" href="#lnote-bec004" id="lnum-bec004">♦</a>
 And, like a gallant in the brow of youth,</div>
<div class="dverse"><span class="lnum">5</span> Repairs him with occasion? This happy day</div>
<div class="dverse">Is not itself, nor have we won one foot,</div>
<div class="dverse">If Salisbury be lost.</div>

<div class="dverse1"><span class="sd-cn">Rich.</span>
 <span class="i09"> </span> My noble father,</div>
<div class="dverse"><a class="lnum pginternal" href="#lnote-bec008" id="lnum-bec008">♦</a>
 Three times to-day I holp him to his horse,</div>
<div class="dverse">Three times bestrid him; thrice I led him off,</div>
<div class="dverse"><span class="lnum">10</span> Persuaded him from any further act:</div>
<div class="dverse">But still, where danger was, still there I met him;</div>
<div class="dverse"><a class="lnum pginternal" href="#lnote-bec012" id="lnum-bec012">♦</a>
 And like rich hangings in a homely house,</div>
<div class="dverse">So was his will in his old feeble body.</div>
<div class="dverse"><a class="lnum pginternal" href="#lnote-bec014" id="lnum-bec014">♦</a>
 But, noble as he is, look where he comes.</div>

<div class="sd-entry"><i>Enter</i>
 <span class="smcaps">S<span>ALISBURY</span></span>.</div>

<div class="dverse1"><span class="lnum">15</span>
 <span class="sd-cn">Sal.</span>
  Now, by my sword, well hast thou fought to-day;</div>
<div class="dverse"><a class="lnum pginternal" href="#lnote-bec016" id="lnum-bec016">♦</a>
 By the mass, so did we all. I thank you, Richard:</div>
<div class="dverse">God knows how long it is I have to live;</div>
<div class="dverse">And it hath pleased him that three times to-day</div>
<div class="dverse"><a class="lnum pginternal" href="#lnote-bec019" id="lnum-bec019">♦</a>
 You have defended me from imminent death.</div>
<div class="dverse"><span class="lnum">20</span> Well, lords, we have not got that which we have:</div>
<div class="dverse">’Tis not enough our foes are this time fled,</div>
<div class="dverse">Being opposites of such repairing nature.</div>

<div class="dverse1"><span class="sd-cn">York.</span>
 I know our safety is to follow them;</div>
<div class="dverse">For, as I hear, the king is fled to London,</div>
<div class="dverse"><span class="lnum">25</span> To call a present court of parliament.</div>
<div class="dverse">Let us pursue him ere the writs go forth.</div>
<div class="dverse"><a class="lnum pginternal" href="#lnote-bec027" id="lnum-bec027">♦</a>
 What says Lord Warwick? shall we after them?</div>

<div class="dverse1"><span class="sd-cn">War.</span>
 After them! nay, before them, if we can.</div>
<div class="dverse"><a class="lnum pginternal" href="#lnote-bec029" id="lnum-bec029">♦</a>
 Now, by my faith, lords, ’twas a glorious day:</div>
<div class="dverse"><span class="lnum">30</span> Saint Alban’s battle won by famous York</div>
<div class="dverse">Shall be eternized in all age to come.</div>
<div class="dverse"><a class="lnum pginternal" href="#lnote-bec032" id="lnum-bec032">♦</a>
 Sound drums and trumpets, and to London all:</div>
<div class="dverse"><a class="lnum pginternal" href="#lnote-bec033" id="lnum-bec033">♦</a>
 And more such days as these to us befall! <span class="sd-verseend">[<i>Exeunt.</i></span></div>

<div class="right toppada">
<a href="#idtoc" class="pginternal">toc</a></div>

